"use client"

import { Database, Trash2, RefreshCw, TrendingUp, Key, HardDrive } from "lucide-react"
import { useState, useEffect } from "react"

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { useToast } from "@/hooks/use-toast"

interface CacheStats {
  hits: number
  misses: number
  keys: number
  hitRate: number
  size: number
}

export function CacheManager() {
  const [stats, setStats] = useState<CacheStats | null>(null)
  const [loading, setLoading] = useState(true)
  const [purging, setPurging] = useState(false)
  const [purgePattern, setPurgePattern] = useState("")
  const [purgeAllOpen, setPurgeAllOpen] = useState(false)
  const { toast } = useToast()

  const fetchStats = async () => {
    try {
      const response = await fetch('/api/administracion/cache/stats')
      const data = await response.json()
      if (data.success) {
        setStats(data.stats)
      }
    } catch (error) {
      console.error('Error fetching cache stats:', error)
      toast({
        title: "Error",
        description: "No se pudieron cargar las estadísticas del caché",
        variant: "destructive",
      })
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchStats()
    const interval = setInterval(fetchStats, 10000) // Actualizar cada 10 segundos
    return () => clearInterval(interval)
  }, [])

  const handlePurgePattern = async () => {
    if (!purgePattern.trim()) {
      toast({
        title: "Error",
        description: "Ingresa un patrón válido",
        variant: "destructive",
      })
      return
    }

    setPurging(true)
    try {
      const response = await fetch('/api/administracion/cache/purge', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ pattern: purgePattern }),
      })

      const data = await response.json()
      if (data.success) {
        toast({
          title: "Éxito",
          description: data.message,
        })
        setPurgePattern("")
        fetchStats()
      } else {
        throw new Error(data.error || 'Error al purgar')
      }
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Error al purgar el caché",
        variant: "destructive",
      })
    } finally {
      setPurging(false)
    }
  }

  const handlePurgeAll = async () => {
    setPurging(true)
    try {
      const response = await fetch('/api/administracion/cache/purge', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ all: true }),
      })

      const data = await response.json()
      if (data.success) {
        toast({
          title: "Éxito",
          description: data.message,
        })
        setPurgeAllOpen(false)
        fetchStats()
      } else {
        throw new Error(data.error || 'Error al purgar')
      }
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Error al purgar el caché",
        variant: "destructive",
      })
    } finally {
      setPurging(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <RefreshCw className="h-6 w-6 animate-spin text-gray-400" />
      </div>
    )
  }

  if (!stats) {
    return (
      <Card>
        <CardContent className="p-6 text-center text-gray-500">
          No se pudieron cargar las estadísticas
        </CardContent>
      </Card>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Gestión de Caché</h2>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            Administra el caché del sistema
          </p>
        </div>
        <Button onClick={fetchStats} variant="outline" size="sm">
          <RefreshCw className="h-4 w-4 mr-2" />
          Actualizar
        </Button>
      </div>

      {/* Estadísticas */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-medium flex items-center gap-2">
              <TrendingUp className="h-4 w-4" />
              Hit Rate
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">{stats.hitRate.toFixed(2)}%</p>
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
              {stats.hits} hits / {stats.misses} misses
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-medium flex items-center gap-2">
              <Database className="h-4 w-4" />
              Hits
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">{stats.hits.toLocaleString()}</p>
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">Aciertos</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-medium flex items-center gap-2">
              <Database className="h-4 w-4" />
              Misses
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">{stats.misses.toLocaleString()}</p>
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">Fallos</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-medium flex items-center gap-2">
              <Key className="h-4 w-4" />
              Claves
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">{stats.keys}</p>
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">En caché</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-medium flex items-center gap-2">
              <HardDrive className="h-4 w-4" />
              Tamaño
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">{stats.size.toFixed(2)}</p>
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">MB</p>
          </CardContent>
        </Card>
      </div>

      {/* Purga */}
      <Card>
        <CardHeader>
          <CardTitle>Purgar Caché</CardTitle>
          <CardDescription>
            Elimina claves del caché por patrón o limpia todo el caché
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>Purgar por Patrón (Regex)</Label>
            <div className="flex gap-2">
              <Input
                placeholder="Ej: admin:organizations:*"
                value={purgePattern}
                onChange={(e) => setPurgePattern(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handlePurgePattern()
                  }
                }}
              />
              <Button
                onClick={handlePurgePattern}
                disabled={!purgePattern.trim() || purging}
                variant="outline"
              >
                <Trash2 className="h-4 w-4 mr-2" />
                Purgar
              </Button>
            </div>
            <p className="text-xs text-gray-500 dark:text-gray-400">
              Ejemplos: <code>admin:organizations:*</code>, <code>admin:users:*</code>
            </p>
          </div>

          <div className="pt-4 border-t">
            <Dialog open={purgeAllOpen} onOpenChange={setPurgeAllOpen}>
              <DialogTrigger asChild>
                <Button variant="destructive">
                  <Trash2 className="h-4 w-4 mr-2" />
                  Purgar Todo el Caché
                </Button>
              </DialogTrigger>
              <DialogContent>
                <DialogHeader>
                  <DialogTitle>¿Purgar todo el caché?</DialogTitle>
                  <DialogDescription>
                    Esta acción eliminará todas las claves del caché. Esta operación no se puede deshacer.
                  </DialogDescription>
                </DialogHeader>
                <DialogFooter>
                  <Button
                    variant="outline"
                    onClick={() => setPurgeAllOpen(false)}
                    disabled={purging}
                  >
                    Cancelar
                  </Button>
                  <Button
                    variant="destructive"
                    onClick={handlePurgeAll}
                    disabled={purging}
                  >
                    {purging ? (
                      <>
                        <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                        Purgando...
                      </>
                    ) : (
                      "Confirmar"
                    )}
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { useState } from "react"
import { toast } from "sonner"

import { CmsPageFormDialog } from "./cms-page-form-dialog"
import { CmsPagePreviewDialog } from "./cms-page-preview-dialog"
import { CmsPagesContainer } from "./cms-pages-container"


interface CmsPage {
  id: string
  organizationId?: string | null
  slug: string
  title: string
  content: string
  excerpt?: string | null
  metaTitle?: string | null
  metaDescription?: string | null
  pageType: string
  isPublished: boolean
  publishedAt?: string | null
  order: number
  createdAt: string
  updatedAt: string
  createdBy?: {
    id: string
    fullName: string | null
    email: string
  } | null
  updatedBy?: {
    id: string
    fullName: string | null
    email: string
  } | null
  organization?: {
    id: string
    name: string
    slug: string
  } | null
}

interface CmsPagesPageClientProps {
  initialPages: CmsPage[]
  initialTotal: number
}

export function CmsPagesPageClient({ initialPages, initialTotal }: CmsPagesPageClientProps) {
  const [pages, setPages] = useState<CmsPage[]>(initialPages)
  const [total, setTotal] = useState(initialTotal)
  const [isFormDialogOpen, setIsFormDialogOpen] = useState(false)
  const [isPreviewDialogOpen, setIsPreviewDialogOpen] = useState(false)
  const [selectedPage, setSelectedPage] = useState<CmsPage | null>(null)
  const [previewPage, setPreviewPage] = useState<CmsPage | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  const fetchPages = async (organizationId?: string, pageType?: string, isPublished?: boolean) => {
    setIsLoading(true)
    try {
      const params = new URLSearchParams()
      if (organizationId) params.append('organizationId', organizationId)
      if (pageType) params.append('pageType', pageType)
      if (isPublished !== undefined) params.append('isPublished', String(isPublished))

      const response = await fetch(`/api/administracion/cms/pages?${params.toString()}`)
      if (!response.ok) throw new Error('Error al cargar páginas')

      const data = await response.json()
      setPages(data.pages || [])
      setTotal(data.total || 0)
    } catch (error) {
      toast.error('Error al cargar páginas')
      console.error(error)
    } finally {
      setIsLoading(false)
    }
  }

  const handleNewClick = () => {
    setSelectedPage(null)
    setIsFormDialogOpen(true)
  }

  const handleEdit = (page: CmsPage) => {
    setSelectedPage(page)
    setIsFormDialogOpen(true)
  }

  const handleSave = async (pageData: any) => {
    try {
      const url = selectedPage
        ? `/api/administracion/cms/pages/${selectedPage.slug}`
        : '/api/administracion/cms/pages'

      const method = selectedPage ? 'PATCH' : 'POST'

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(pageData),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.error || 'Error al guardar página')
      }

      toast.success(selectedPage ? 'Página actualizada' : 'Página creada')
      setIsFormDialogOpen(false)
      setSelectedPage(null)

      // Recargar páginas
      await fetchPages()
    } catch (error: any) {
      toast.error(error.message || 'Error al guardar página')
    }
  }

  const handleDelete = async (page: CmsPage) => {
    if (!confirm(`¿Estás seguro de eliminar la página "${page.title}"?`)) return

    try {
      const params = new URLSearchParams()
      // Solo agregar organizationId si existe y no está vacío
      if (page.organizationId && page.organizationId.trim() !== '') {
        params.append('organizationId', page.organizationId)
      }

      const url = `/api/administracion/cms/pages/${encodeURIComponent(page.slug)}${params.toString() ? `?${params.toString()}` : ''}`

      const response = await fetch(url, {
        method: 'DELETE',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
        },
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({ error: 'Error desconocido' }))
        throw new Error(errorData.error || `Error al eliminar página (${response.status})`)
      }

      toast.success('Página eliminada')
      await fetchPages()
    } catch (error: any) {
      console.error('Error al eliminar página:', error)
      toast.error(error.message || 'Error al eliminar página')
    }
  }

  const handleTogglePublish = async (page: CmsPage) => {
    try {
      const params = new URLSearchParams()
      if (page.organizationId) params.append('organizationId', page.organizationId)

      const response = await fetch(`/api/administracion/cms/pages/${page.slug}?${params.toString()}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isPublished: !page.isPublished }),
      })

      if (!response.ok) throw new Error('Error al actualizar estado')

      toast.success(page.isPublished ? 'Página despublicada' : 'Página publicada')
      await fetchPages()
    } catch (error) {
      toast.error('Error al actualizar estado')
    }
  }

  const handlePreview = (page: CmsPage) => {
    setPreviewPage(page)
    setIsPreviewDialogOpen(true)
  }

  return (
    <>
      <CmsPagesContainer
        pages={pages}
        total={total}
        isLoading={isLoading}
        onNewClick={handleNewClick}
        onEdit={handleEdit}
        onDelete={handleDelete}
        onTogglePublish={handleTogglePublish}
        onPreview={handlePreview}
        onRefresh={fetchPages}
      />

      <CmsPageFormDialog
        open={isFormDialogOpen}
        onOpenChange={setIsFormDialogOpen}
        page={selectedPage}
        onSave={handleSave}
      />

      <CmsPagePreviewDialog
        open={isPreviewDialogOpen}
        onOpenChange={setIsPreviewDialogOpen}
        page={previewPage}
      />
    </>
  )
}

"use client"

import { useState } from "react"

import { CustomersCards } from "./customers-cards"
import { CustomersFilters } from "./customers-filters"
import { CustomersPagination } from "./customers-pagination"
import { CustomersStats } from "./customers-stats"
import { CustomersTable } from "./customers-table"

import { Customer } from "@/lib/types"

interface CustomersContainerProps {
  customers: Customer[]
  onEdit?: (customer: Customer) => void
  onViewDetails?: (customer: Customer) => void
  onToggleStatus?: (customer: Customer) => void
  onDelete?: (customer: Customer) => void
}

export function CustomersContainer({ customers, onEdit, onViewDetails, onToggleStatus, onDelete }: CustomersContainerProps) {
  const [pageSize, setPageSize] = useState(5)
  const [currentPage, setCurrentPage] = useState(1)
  const [statusFilter, setStatusFilter] = useState("all")
  const [searchTerm, setSearchTerm] = useState("")

  // Filtrar clientes por búsqueda y estado
  const filteredCustomers = customers.filter(customer => {
    // Filtrar por búsqueda
    if (searchTerm && searchTerm.trim() !== "") {
      const searchLower = searchTerm.toLowerCase()
      const matchesSearch = 
        customer.email?.toLowerCase().includes(searchLower) ||
        customer.nombre?.toLowerCase().includes(searchLower) ||
        customer.apellido?.toLowerCase().includes(searchLower) ||
        customer.razonSocial?.toLowerCase().includes(searchLower) ||
        customer.nit?.toLowerCase().includes(searchLower) ||
        customer.ci?.toLowerCase().includes(searchLower)

      if (!matchesSearch) return false
    }

    // Filtrar por estado
    if (statusFilter === "active") return customer.isActive
    if (statusFilter === "inactive") return !customer.isActive
    return true // "all" - mostrar todos
  })

  const handleSearchChange = (term: string) => {
    setSearchTerm(term)
    setCurrentPage(1) // Resetear a la primera página cuando cambia la búsqueda
  }

  // Calcular clientes para la página actual
  const startIndex = (currentPage - 1) * pageSize
  const endIndex = startIndex + pageSize
  const currentCustomers = filteredCustomers.slice(startIndex, endIndex)

  const handleStatusChange = (status: string) => {
    setStatusFilter(status)
    setCurrentPage(1) // Resetear a la primera página cuando cambia el filtro
  }

  const handlePageSizeChange = (size: number) => {
    setPageSize(size)
    setCurrentPage(1) // Resetear a la primera página cuando cambia el tamaño
  }

  const handlePageChange = (page: number) => {
    setCurrentPage(page)
  }

  const handlePrevious = () => {
    if (currentPage > 1) {
      setCurrentPage(currentPage - 1)
    }
  }

  const handleNext = () => {
    const totalPages = Math.ceil(filteredCustomers.length / pageSize)
    if (currentPage < totalPages) {
      setCurrentPage(currentPage + 1)
    }
  }

  return (
    <div className="space-y-4 md:space-y-6 py-4 md:py-6 px-0 md:px-6">
      {/* Estadísticas */}
      <CustomersStats customers={customers} />

      {/* Filtros */}
      <CustomersFilters 
        onPageSizeChange={handlePageSizeChange}
        onStatusChange={handleStatusChange}
        onSearchChange={handleSearchChange}
      />

      {/* Cards de clientes (solo móvil) */}
      <CustomersCards customers={currentCustomers} onEdit={onEdit} onViewDetails={onViewDetails} onToggleStatus={onToggleStatus} onDelete={onDelete} />

      {/* Tabla de clientes (solo desktop) - Solo mostrar si hay clientes */}
      {customers.length > 0 && (
        <div className="hidden md:block rounded-md border border-gray-200 dark:border-[#2a2a2a]">
          <CustomersTable 
            customers={currentCustomers} 
            onViewDetails={onViewDetails}
            onEditClick={onEdit} 
            onToggleStatus={onToggleStatus} 
            onDeleteClick={onDelete} 
          />
        </div>
      )}

      {/* Paginación - Solo mostrar si hay clientes */}
      {customers.length > 0 && (
        <div className="flex justify-center">
          <CustomersPagination
            currentPage={currentPage}
            totalPages={Math.ceil(filteredCustomers.length / pageSize)}
            pageSize={pageSize}
            onPageChange={handlePageChange}
            onPageSizeChange={handlePageSizeChange}
          />
        </div>
      )}
    </div>
  )
}

"use client";

import { CustomerDeleteDialog } from "./customer-delete-dialog";
import { CustomerDetailDialog } from "./customer-detail-dialog";
import { CustomerFormDialog } from "./customer-form-dialog";
import { CustomersContainer } from "./customers-container";
import { CustomersHeader } from "./customers-header";

import { AdminLayout } from "@/components/layout/admin-layout";
import { useCustomerActions } from "@/hooks/admin/customer/use-customer-actions";
import { Customer } from "@/lib/types";

interface CustomersPageClientProps {
  initialCustomers: Customer[];
}

export function CustomersPageClient({
  initialCustomers,
}: CustomersPageClientProps) {
  const {
    isFormDialogOpen,
    isDeleteDialogOpen,
    isDetailDialogOpen,
    setIsDetailDialogOpen,
    selectedCustomer,
    customerDetails,
    isLoadingDetails,
    openCreateDialog,
    openEditDialog,
    openDeleteDialog,
    openDetailDialog,
    closeDialogs,
    handleSave,
    handleDelete,
    handleToggleStatus,
  } = useCustomerActions();

  return (
    <AdminLayout>
        <div className="space-y-4 md:space-y-6 px-4 md:px-0">
        {/* Header con título y botón */}
        <CustomersHeader
          title="Gestión de Clientes"
          description="Administra todos los clientes de tu organización"
          newButtonText="Agregar Cliente"
          onNewClick={openCreateDialog}
        />

        {/* Contenedor con filtros, tabla y paginación */}
        <CustomersContainer
          customers={initialCustomers}
          onEdit={openEditDialog}
          onViewDetails={openDetailDialog}
          onToggleStatus={handleToggleStatus}
          onDelete={openDeleteDialog}
        />

        {/* Modal de crear/editar cliente */}
        <CustomerFormDialog
          open={isFormDialogOpen}
          onOpenChange={closeDialogs}
          customer={selectedCustomer}
          onSave={handleSave}
        />

        {/* Modal de detalles del cliente */}
        <CustomerDetailDialog
          open={isDetailDialogOpen}
          onOpenChange={setIsDetailDialogOpen}
          customer={customerDetails}
        />

        {/* Modal de confirmación de eliminar */}
        <CustomerDeleteDialog
          open={isDeleteDialogOpen}
          onOpenChange={closeDialogs}
          customer={selectedCustomer}
          onDelete={handleDelete}
        />
      </div>
    </AdminLayout>
  );
}

"use client"

import { Pagination, PaginationContent, PaginationItem, PaginationLink, PaginationPrevious, PaginationNext } from "@/components/ui/pagination"

interface CustomersPaginationProps {
  currentPage: number
  totalPages: number
  pageSize: number
  onPageChange: (page: number) => void
  onPageSizeChange: (pageSize: number) => void
}

export function CustomersPagination({
  currentPage,
  totalPages,
  pageSize,
  onPageChange,
  onPageSizeChange,
}: CustomersPaginationProps) {
  const getPageNumbers = () => {
    const pages: (number | string)[] = []
    
    if (totalPages <= 5) {
      for (let i = 1; i <= totalPages; i++) {
        pages.push(i)
      }
    } else {
      if (currentPage <= 3) {
        pages.push(1, 2, 3, 4, '...', totalPages)
      } else if (currentPage >= totalPages - 2) {
        pages.push(1, '...', totalPages - 3, totalPages - 2, totalPages - 1, totalPages)
      } else {
        pages.push(1, '...', currentPage - 1, currentPage, currentPage + 1, '...', totalPages)
      }
    }
    
    return pages
  }

  const pages = getPageNumbers()
  const onPrevious = () => onPageChange(currentPage - 1)
  const onNext = () => onPageChange(currentPage + 1)

  return (
    <div className="flex justify-center mt-6">
      <Pagination>
        <PaginationContent>
          <PaginationItem>
            <PaginationPrevious 
              href="#" 
              onClick={(e) => {
                e.preventDefault()
                if (currentPage > 1) onPrevious()
              }}
              className={currentPage === 1 ? "pointer-events-none opacity-50" : ""}
            />
          </PaginationItem>
          
          {pages.map((page, index) => {
            if (page === '...') {
              return (
                <PaginationItem key={`ellipsis-${index}`}>
                  <span className="px-2 text-gray-500 dark:text-gray-400">...</span>
                </PaginationItem>
              )
            }
            
            const pageNum = page as number
            return (
              <PaginationItem key={pageNum}>
                <PaginationLink
                  href="#"
                  isActive={currentPage === pageNum}
                  onClick={(e) => {
                    e.preventDefault()
                    onPageChange(pageNum)
                  }}
                >
                  {pageNum}
                </PaginationLink>
              </PaginationItem>
            )
          })}
          
          <PaginationItem>
            <PaginationNext 
              href="#" 
              onClick={(e) => {
                e.preventDefault()
                if (currentPage < totalPages) onNext()
              }}
              className={currentPage === totalPages ? "pointer-events-none opacity-50" : ""}
            />
          </PaginationItem>
        </PaginationContent>
      </Pagination>
    </div>
  )
}

"use client"


import {
  AlertTriangle,
  RefreshCw,
  LayoutDashboard,
} from "lucide-react"
import { useState, useEffect } from "react"

import { CustomizeWidgetsDialog } from "./widgets/customize-widgets-dialog"
import { Widget } from "./widgets/types"
import { useWidgetConfig } from "./widgets/use-widget-config"
import { DragAndDropWidgets } from "./widgets/widget-container"
import { WidgetRenderer } from "./widgets/widget-renderer"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"

interface DashboardStats {
  organizations: {
    total: number
    active: number
    suspended: number
  }
  users: {
    total: number
  }
  revenue: {
    total: number
  }
}

interface SystemMetrics {
  totalProducts: number
  totalOrders: number
  totalUsers: number
}

interface RecentActivity {
  id: string
  type: string
  description: string
  createdAt: string
  userId?: string
  organizationId?: string
}

interface HealthMetrics {
  uptime: number // Porcentaje
  averageLatency: number // En ms
  errorRate: number // Porcentaje
  lastCheck: string
}

interface AlertItem {
  id: string
  type: "warning" | "error" | "info"
  title: string
  message: string
  actionUrl?: string
  actionLabel?: string
}

interface DashboardClientProps {
  initialStats: DashboardStats
  initialMetrics: SystemMetrics
  initialActivity: RecentActivity[]
  initialHealth?: HealthMetrics
}

type PeriodFilter = "7d" | "30d" | "90d" | "1y" | "all"

export function DashboardClient({
  initialStats,
  initialMetrics,
  initialActivity,
  initialHealth,
}: DashboardClientProps) {
  const [period, setPeriod] = useState<PeriodFilter>("30d")
  const [alerts, setAlerts] = useState<AlertItem[]>([])
  const [health, setHealth] = useState<HealthMetrics | null>(initialHealth || null)
  const [activity, setActivity] = useState<RecentActivity[]>(initialActivity)
  const [refreshing, setRefreshing] = useState(false)
  const [isCustomizeOpen, setIsCustomizeOpen] = useState(false)
  const [recentSubscriptions, setRecentSubscriptions] = useState<any[]>([])

  const { widgets, isLoading: widgetsLoading, saveWidgets, updateWidget, removeWidget } = useWidgetConfig()

  useEffect(() => {
    fetchAlerts()
    fetchHealthMetrics()
    fetchRecentSubscriptions()
  }, [])

  useEffect(() => {
    fetchActivity()
  }, [period])

  const fetchAlerts = async () => {
    try {
      const response = await fetch("/api/administracion/dashboard/alerts")
      const data = await response.json()
      if (data.success) {
        setAlerts(data.alerts || [])
      }
    } catch (error) {
      console.error("Error fetching alerts:", error)
    }
  }

  const fetchHealthMetrics = async () => {
    try {
      const response = await fetch("/api/administracion/dashboard/health")
      const data = await response.json()
      if (data.success) {
        setHealth(data.health)
      }
    } catch (error) {
      console.error("Error fetching health metrics:", error)
    }
  }

  const fetchActivity = async () => {
    try {
      const response = await fetch(`/api/administracion/dashboard/activity?period=${period}`)
      const data = await response.json()
      if (data.success) {
        setActivity(data.activity || [])
      }
    } catch (error) {
      console.error("Error fetching activity:", error)
    }
  }

  const fetchRecentSubscriptions = async () => {
    try {
      const response = await fetch("/api/administracion/dashboard/recent-subscriptions")
      const data = await response.json()
      if (data.success) {
        setRecentSubscriptions(data.subscriptions || [])
      }
    } catch (error) {
      console.error("Error fetching recent subscriptions:", error)
    }
  }

  const handleRefresh = async () => {
    setRefreshing(true)
    await Promise.all([
      fetchAlerts(),
      fetchHealthMetrics(),
      fetchActivity(),
      fetchRecentSubscriptions(),
    ])
    setRefreshing(false)
  }

  const getWidgetData = (widget: Widget) => {
    switch (widget.type) {
      case "stats":
        return initialStats
      case "health":
        return health
      case "activity":
        return activity
      case "recent-subscriptions":
        return recentSubscriptions
      default:
        return null
    }
  }

  const handleSizeChange = (id: string, size: Widget['size']) => {
    updateWidget(id, { size })
  }

  const handleRemoveWidget = (id: string) => {
    removeWidget(id)
  }

  const getPeriodLabel = (p: PeriodFilter) => {
    const labels: Record<PeriodFilter, string> = {
      "7d": "7 días",
      "30d": "30 días",
      "90d": "90 días",
      "1y": "1 año",
      all: "Todo",
    }
    return labels[p]
  }

  if (widgetsLoading) {
    return <div>Cargando widgets...</div>
  }

  return (
    <div className="space-y-6">
      {/* Filtros rápidos y controles */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div className="flex flex-wrap gap-2">
          {(["7d", "30d", "90d", "1y", "all"] as PeriodFilter[]).map((p) => (
            <Button
              key={p}
              variant={period === p ? "default" : "outline"}
              size="sm"
              onClick={() => setPeriod(p)}
            >
              {getPeriodLabel(p)}
            </Button>
          ))}
        </div>
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setIsCustomizeOpen(true)}
          >
            <LayoutDashboard className="h-4 w-4 mr-2" />
            Personalizar
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={handleRefresh}
            disabled={refreshing}
          >
            <RefreshCw className={`h-4 w-4 mr-2 ${refreshing ? "animate-spin" : ""}`} />
            Actualizar
          </Button>
        </div>
      </div>

      {/* Alertas destacadas */}
      {alerts.length > 0 && (
        <div className="space-y-3">
          {alerts.map((alert) => (
            <Alert
              key={alert.id}
              variant={alert.type === "error" ? "destructive" : alert.type === "warning" ? "default" : "default"}
              className={
                alert.type === "warning"
                  ? "border-yellow-500 bg-yellow-50 dark:bg-yellow-900/20"
                  : alert.type === "error"
                  ? "border-red-500"
                  : ""
              }
            >
              <AlertTriangle className="h-4 w-4" />
              <AlertTitle>{alert.title}</AlertTitle>
              <AlertDescription className="flex items-center justify-between">
                <span>{alert.message}</span>
                {alert.actionUrl && (
                  <Button
                    variant="link"
                    size="sm"
                    className="ml-4"
                    onClick={() => window.location.href = alert.actionUrl!}
                  >
                    {alert.actionLabel || "Ver"}
                  </Button>
                )}
              </AlertDescription>
            </Alert>
          ))}
        </div>
      )}

      {/* Widgets con drag and drop */}
      <DragAndDropWidgets
        widgets={widgets}
        onWidgetsChange={saveWidgets}
        onRemove={handleRemoveWidget}
        onSizeChange={handleSizeChange}
        columns={4}
      >
        {(widget) => {
          const data = getWidgetData(widget)
          if (!data) return null
          return <WidgetRenderer widget={widget} data={data} />
        }}
      </DragAndDropWidgets>

      {/* Diálogo de personalización */}
      <CustomizeWidgetsDialog
        open={isCustomizeOpen}
        onOpenChange={setIsCustomizeOpen}
        widgets={widgets}
        onSave={saveWidgets}
      />
    </div>
  )
}

"use client"

import { Search, User, Building2, CreditCard, Ticket, FileText, Loader2 } from "lucide-react"
import { useRouter } from "next/navigation"
import { useState, useEffect, useRef } from "react"

import { Badge } from "@/components/ui/badge"
import { Card } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"

interface SearchResult {
  id: string
  type: 'user' | 'organization' | 'subscription' | 'ticket' | 'log'
  title: string
  description: string
  url: string
  metadata?: Record<string, any>
}

const typeIcons = {
  user: User,
  organization: Building2,
  subscription: CreditCard,
  ticket: Ticket,
  log: FileText,
}

const typeLabels = {
  user: 'Usuario',
  organization: 'Organización',
  subscription: 'Suscripción',
  ticket: 'Ticket',
  log: 'Log',
}

export function GlobalSearch() {
  const [open, setOpen] = useState(false)
  const [query, setQuery] = useState("")
  const [results, setResults] = useState<SearchResult[]>([])
  const [loading, setLoading] = useState(false)
  const [selectedIndex, setSelectedIndex] = useState(0)
  const router = useRouter()
  const inputRef = useRef<HTMLInputElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)

  // Atajo de teclado Cmd/Ctrl + K
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        setOpen(true)
      }
      
      if (e.key === 'Escape') {
        setOpen(false)
        setQuery("")
        setResults([])
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [])

  // Focus en el input cuando se abre
  useEffect(() => {
    if (open && inputRef.current) {
      inputRef.current.focus()
    }
  }, [open])

  // Buscar cuando cambia el query
  useEffect(() => {
    if (!open || query.length < 2) {
      setResults([])
      return
    }

    const timeoutId = setTimeout(async () => {
      setLoading(true)
      try {
        const response = await fetch(`/api/administracion/search?q=${encodeURIComponent(query)}&limit=10`)
        const data = await response.json()
        if (data.success) {
          setResults(data.results)
          setSelectedIndex(0)
        }
      } catch (error) {
        console.error('Error searching:', error)
      } finally {
        setLoading(false)
      }
    }, 300) // Debounce

    return () => clearTimeout(timeoutId)
  }, [query, open])

  // Navegar con teclado
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!open) return

      if (e.key === 'ArrowDown') {
        e.preventDefault()
        setSelectedIndex((prev) => (prev < results.length - 1 ? prev + 1 : prev))
      } else if (e.key === 'ArrowUp') {
        e.preventDefault()
        setSelectedIndex((prev) => (prev > 0 ? prev - 1 : 0))
      } else if (e.key === 'Enter' && results[selectedIndex]) {
        e.preventDefault()
        handleSelectResult(results[selectedIndex])
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [open, results, selectedIndex])

  // Cerrar al hacer click fuera
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setOpen(false)
      }
    }

    if (open) {
      document.addEventListener('mousedown', handleClickOutside)
      return () => document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [open])

  const handleSelectResult = (result: SearchResult) => {
    router.push(result.url)
    setOpen(false)
    setQuery("")
    setResults([])
  }

  if (!open) {
    return (
      <button
        onClick={() => setOpen(true)}
        className="flex items-center gap-2 px-3 py-2 text-sm text-gray-600 dark:text-gray-400 bg-gray-100 dark:bg-[#2a2a2a] rounded-lg hover:bg-gray-200 dark:hover:bg-[#333] transition-colors"
      >
        <Search className="h-4 w-4" />
        <span className="hidden sm:inline">Buscar...</span>
        <kbd className="hidden sm:inline-flex h-5 select-none items-center gap-1 rounded border bg-muted px-1.5 font-mono text-[10px] font-medium opacity-100">
          <span className="text-xs">⌘</span>K
        </kbd>
      </button>
    )
  }

  return (
    <div ref={containerRef} className="relative w-full max-w-2xl">
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
        <Input
          ref={inputRef}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Buscar usuarios, organizaciones, tickets..."
          className="pl-10 pr-10 h-10"
        />
        {loading && (
          <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 animate-spin text-gray-400" />
        )}
      </div>

      {results.length > 0 && (
        <Card className="absolute top-full mt-2 w-full z-50 max-h-96 overflow-auto">
          <div className="p-2">
            {results.map((result, index) => {
              const Icon = typeIcons[result.type]
              return (
                <button
                  key={result.id}
                  onClick={() => handleSelectResult(result)}
                  className={cn(
                    "w-full text-left p-3 rounded-lg hover:bg-gray-100 dark:hover:bg-[#2a2a2a] transition-colors",
                    index === selectedIndex && "bg-gray-100 dark:bg-[#2a2a2a]"
                  )}
                >
                  <div className="flex items-start gap-3">
                    <Icon className="h-5 w-5 text-gray-400 mt-0.5 flex-shrink-0" />
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <p className="font-medium text-sm text-gray-900 dark:text-white truncate">
                          {result.title}
                        </p>
                        <Badge variant="secondary" className="text-xs">
                          {typeLabels[result.type]}
                        </Badge>
                      </div>
                      <p className="text-xs text-gray-500 dark:text-gray-400 line-clamp-1">
                        {result.description}
                      </p>
                    </div>
                  </div>
                </button>
              )
            })}
          </div>
        </Card>
      )}

      {query.length >= 2 && !loading && results.length === 0 && (
        <Card className="absolute top-full mt-2 w-full z-50">
          <div className="p-4 text-center text-sm text-gray-500 dark:text-gray-400">
            No se encontraron resultados
          </div>
        </Card>
      )}
    </div>
  )
}

"use client"

import { Plus } from 'lucide-react'

import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'


interface Integration {
  id: string
  name: string
  slug: string
  description?: string
  category: string
  isActive: boolean
  isPublic: boolean
  _count?: {
    installations: number
  }
}

interface Organization {
  id: string
  name: string
  slug: string
}

interface IntegrationsClientProps {
  initialIntegrations: Integration[]
  initialOrganizations: Organization[]
}

export function IntegrationsClient({ initialIntegrations, initialOrganizations }: IntegrationsClientProps) {
  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <div className="flex justify-between items-center">
            <CardTitle>Integraciones ({initialIntegrations.length})</CardTitle>
            <Button>
              <Plus className="h-4 w-4 mr-2" />
              Nueva Integración
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {initialIntegrations.map((integration) => (
              <div key={integration.id} className="border rounded-lg p-4 hover:shadow-md transition-shadow">
                <div className="flex justify-between items-start mb-2">
                  <h3 className="font-semibold">{integration.name}</h3>
                  <Badge variant="outline">{integration.category}</Badge>
                </div>
                {integration.description && (
                  <p className="text-sm text-muted-foreground mb-3">{integration.description}</p>
                )}
                <div className="flex gap-2">
                  {integration.isActive && <Badge variant="default">Activa</Badge>}
                  {integration.isPublic && <Badge variant="secondary">Pública</Badge>}
                  {integration._count && (
                    <Badge variant="outline">{integration._count.installations} instalaciones</Badge>
                  )}
                </div>
              </div>
            ))}
            {initialIntegrations.length === 0 && (
              <div className="col-span-full text-center text-muted-foreground py-8">
                No hay integraciones disponibles aún
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { Loader2, CheckSquare2 } from "lucide-react"
import { useEffect, useState } from "react"
import { toast } from "sonner"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { PermissionAdminService } from "@/lib/services/admin/permission-admin-service"

interface PermissionFormDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSuccess: () => void
}

export function PermissionFormDialog({ open, onOpenChange, onSuccess }: PermissionFormDialogProps) {
  const [selectedModule, setSelectedModule] = useState<string>("")
  const [selectedActions, setSelectedActions] = useState<string[]>([])
  const [existingPermissionNames, setExistingPermissionNames] = useState<string[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [loadingExistingPermissions, setLoadingExistingPermissions] = useState(false)

  const modules = PermissionAdminService.getAvailableModules()
  const actions = PermissionAdminService.getAvailableActions()

  // Reset form when dialog opens/closes
  useEffect(() => {
    if (!open) {
      setSelectedModule("")
      setSelectedActions([])
      setExistingPermissionNames([])
    }
  }, [open])

  // Cargar permisos existentes cuando se selecciona un módulo
  useEffect(() => {
    if (selectedModule) {
      loadExistingPermissions(selectedModule)
    } else {
      setSelectedActions([])
    }
  }, [selectedModule])

  const loadExistingPermissions = async (module: string) => {
    setLoadingExistingPermissions(true)
    try {
      const response = await fetch("/api/administracion/permisos")
      if (!response.ok) {
        throw new Error("Error al cargar permisos existentes")
      }

      const allPermissions: Array<{ name: string }> = await response.json()
      
      // Filtrar permisos del módulo seleccionado
      const modulePermissions = allPermissions.filter(perm => 
        perm.name.startsWith(`${module}_`)
      )

      // Extraer las acciones de los permisos existentes
      const existingActions: string[] = []
      const existingNames: string[] = []
      
      actions.forEach(action => {
        const permissionName = PermissionAdminService.generatePermissionName(module, action.id)
        if (modulePermissions.some(p => p.name === permissionName)) {
          existingActions.push(action.id)
          existingNames.push(permissionName)
        }
      })

      setSelectedActions(existingActions)
      setExistingPermissionNames(existingNames)
    } catch (error) {
      console.error("Error al cargar permisos existentes:", error)
      // Si falla, no marcar ningún checkbox
      setSelectedActions([])
    } finally {
      setLoadingExistingPermissions(false)
    }
  }

  const handleActionToggle = (actionId: string) => {
    setSelectedActions(prev =>
      prev.includes(actionId)
        ? prev.filter(id => id !== actionId)
        : [...prev, actionId]
    )
  }

  const handleSelectAllActions = () => {
    if (selectedModule) {
      // Marcar todas las acciones disponibles
      setSelectedActions(actions.map(action => action.id))
    }
  }

  const handleSubmit = async () => {
    if (!selectedModule) {
      toast.error("Por favor selecciona un módulo")
      return
    }

    if (selectedActions.length === 0) {
      toast.error("Por favor selecciona al menos una acción")
      return
    }

    setIsLoading(true)

    try {
      // Obtener permisos existentes para filtrar solo los nuevos
      const existingPermissionsResponse = await fetch("/api/administracion/permisos")
      const existingPermissions: Array<{ name: string }> = existingPermissionsResponse.ok 
        ? await existingPermissionsResponse.json()
        : []

      // Generar permisos para cada acción seleccionada
      const allPermissions = selectedActions.map(action =>
        PermissionAdminService.generatePermissionName(selectedModule, action)
      )

      // Filtrar solo los permisos que no existen
      const newPermissions = allPermissions.filter(perm =>
        !existingPermissions.some(existing => existing.name === perm)
      )

      // Si no hay permisos nuevos, solo informar
      if (newPermissions.length === 0) {
        toast.info("Todos los permisos ya están registrados", {
          description: `Todos los permisos seleccionados para el módulo ${modules.find(m => m.id === selectedModule)?.label} ya existen en el sistema`,
        })
        onSuccess()
        onOpenChange(false)
        setIsLoading(false)
        return
      }

      // Crear solo los permisos nuevos en la BD
      const newActions = selectedActions.filter(action => {
        const permissionName = PermissionAdminService.generatePermissionName(selectedModule, action)
        return newPermissions.includes(permissionName)
      })

      const response = await fetch("/api/administracion/permisos", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          module: selectedModule,
          actions: newActions,
          permissions: newPermissions,
        }),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.error || "Error al crear los permisos")
      }

      const existingCount = allPermissions.length - newPermissions.length
      const message = existingCount > 0
        ? `Se han creado ${newPermissions.length} permiso(s) nuevo(s). ${existingCount} permiso(s) ya existían.`
        : `Se han creado ${newPermissions.length} permiso(s) para el módulo ${modules.find(m => m.id === selectedModule)?.label}`

      toast.success("Permisos registrados correctamente", {
        description: message,
      })

      onSuccess()
      onOpenChange(false)
    } catch (error: any) {
      console.error("Error al crear permisos:", error)
      toast.error("Error al registrar permisos", {
        description: error.message || "No se pudieron crear los permisos",
      })
    } finally {
      setIsLoading(false)
    }
  }

  const selectedModuleLabel = modules.find(m => m.id === selectedModule)?.label || ""

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] flex flex-col overflow-hidden p-0 rounded-lg">
        <div className="px-6 py-5 border-b border-gray-200 dark:border-[#2a2a2a] bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky top-0 z-10">
          <DialogHeader className="px-0 py-0 space-y-2">
            <DialogTitle>Registrar Nuevos Permisos</DialogTitle>
            <DialogDescription>
              Selecciona un módulo y las acciones que deseas registrar como permisos
            </DialogDescription>
          </DialogHeader>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-6 space-y-6 bg-gray-50/60 dark:bg-[#0c0c0c]">
          {/* Selector de Módulo */}
          <div className="space-y-2">
            <Label htmlFor="module" className="text-sm font-semibold text-gray-700 dark:text-gray-200">
              Módulo
            </Label>
            <Select value={selectedModule} onValueChange={setSelectedModule}>
              <SelectTrigger id="module" className="rounded-full">
                <SelectValue placeholder="Selecciona un módulo" />
              </SelectTrigger>
              <SelectContent>
                {modules.map((module) => (
                  <SelectItem key={module.id} value={module.id}>
                    {module.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Selectores de Acciones */}
          {selectedModule && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <Label className="text-sm font-semibold text-gray-700 dark:text-gray-200">
                  Acciones para {selectedModuleLabel}
                  {loadingExistingPermissions && (
                    <span className="ml-2 text-xs text-gray-500 dark:text-gray-400">
                      (Cargando permisos existentes...)
                    </span>
                  )}
                </Label>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={handleSelectAllActions}
                  disabled={loadingExistingPermissions || !selectedModule}
                  className="rounded-full text-xs"
                >
                  <CheckSquare2 className="h-3 w-3 mr-1" />
                  Marcar Todos
                </Button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3 border border-gray-200 dark:border-[#2a2a2a] rounded-lg p-4">
                {actions.map((action) => {
                  const permissionName = PermissionAdminService.generatePermissionName(
                    selectedModule,
                    action.id
                  )
                  const description = PermissionAdminService.generatePermissionDescription(
                    selectedModule,
                    action.id
                  )
                  const isChecked = selectedActions.includes(action.id)

                  return (
                    <div key={action.id} className="flex items-start space-x-3">
                      <Checkbox
                        id={`action-${action.id}`}
                        checked={isChecked}
                        onCheckedChange={() => handleActionToggle(action.id)}
                        className="mt-1"
                        disabled={loadingExistingPermissions}
                      />
                      <div className="flex-1 space-y-1">
                        <div className="flex items-center gap-2">
                          <Label
                            htmlFor={`action-${action.id}`}
                            className="cursor-pointer font-medium text-gray-900 dark:text-white"
                          >
                            {action.label}
                          </Label>
                          {isChecked && (
                            <span className="text-xs px-2 py-0.5 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300 rounded-full">
                              Existente
                            </span>
                          )}
                        </div>
                        <p className="text-xs text-gray-500 dark:text-gray-400">
                          {description}
                        </p>
                        <p className="text-xs font-mono text-gray-400 dark:text-gray-500">
                          {permissionName}
                        </p>
                      </div>
                    </div>
                  )
                })}
              </div>
            </div>
          )}

          {/* Resumen de permisos */}
          {selectedModule && selectedActions.length > 0 && (() => {
            const newPermissions = selectedActions
              .map(action => PermissionAdminService.generatePermissionName(selectedModule, action))
              .filter(name => !existingPermissionNames.includes(name))
            
            const existingCount = selectedActions.length - newPermissions.length

            return (
              <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
                <p className="text-sm font-semibold text-blue-900 dark:text-blue-200 mb-2">
                  Permisos seleccionados ({selectedActions.length}):
                  {existingCount > 0 && (
                    <span className="ml-2 text-xs font-normal text-green-700 dark:text-green-300">
                      ({existingCount} existente(s), {newPermissions.length} nuevo(s))
                    </span>
                  )}
                </p>
                <ul className="space-y-1">
                  {selectedActions.map((action) => {
                    const permissionName = PermissionAdminService.generatePermissionName(
                      selectedModule,
                      action
                    )
                    const isExisting = existingPermissionNames.includes(permissionName)
                    return (
                      <li key={action} className="text-xs font-mono text-blue-700 dark:text-blue-300 flex items-center gap-2 flex-wrap">
                        <span>• {permissionName}</span>
                        {isExisting && (
                          <span className="text-xs px-1.5 py-0.5 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300 rounded-full">
                            Ya existe
                          </span>
                        )}
                        {!isExisting && (
                          <span className="text-xs px-1.5 py-0.5 bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 rounded-full">
                            Nuevo
                          </span>
                        )}
                      </li>
                    )
                  })}
                </ul>
              </div>
            )
          })()}
        </div>

        <DialogFooter className="flex w-full flex-col sm:flex-row sm:justify-center items-center gap-3 border-t border-gray-200 dark:border-[#2a2a2a] px-6 py-4 bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky bottom-0 z-10">
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isLoading}
            className="w-full sm:w-auto rounded-full"
          >
            Cancelar
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={!selectedModule || selectedActions.length === 0 || isLoading}
            className="w-full sm:w-auto rounded-full px-6"
          >
            {isLoading ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Agregando...
              </>
            ) : (
              "Agregar"
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client";

import {
  CreditCard,
  DollarSign,
  Power,
  TrendingUp,
} from "lucide-react";

import { SerializedSubscriptionPlanWithStats } from "./types";

import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

interface PlansStatsProps {
  plans: SerializedSubscriptionPlanWithStats[];
}

export function PlansStats({ plans }: PlansStatsProps) {
  const totalPlans = plans.length;
  const plansInUse = plans.filter(
    (plan) => plan._count.organizations > 0
  ).length;
  const plansNotUsed = plans.filter(
    (plan) => plan._count.organizations === 0
  ).length;
  const plansActive = plans.filter((plan) => plan.isActive ?? true).length;
  const plansInactive = plans.filter((plan) => !(plan.isActive ?? true)).length;
  const totalRevenue = plans.reduce((sum, plan) => {
    // Calcular ingresos mensuales: usar priceMonthly si existe, sino usar priceYearly / 12
    const monthlyPrice =
      plan.hasMonthly && plan.priceMonthly
        ? plan.priceMonthly
        : plan.hasYearly && plan.priceYearly
        ? plan.priceYearly / 12
        : 0;
    return sum + monthlyPrice * plan._count.organizations;
  }, 0);

  const usagePercentage =
    totalPlans > 0 ? Math.round((plansInUse / totalPlans) * 100) : 0;
  const activePercentage =
    totalPlans > 0 ? Math.round((plansActive / totalPlans) * 100) : 0;

  return (
    <div className="grid grid-cols-2 gap-3 md:gap-6 md:grid-cols-2 lg:grid-cols-4">
      <Card className="bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a] hover:shadow-lg transition-shadow">
        <CardHeader className="flex flex-row items-center justify-between pb-0 p-1.5 md:p-4">
          <CardTitle className="text-[10px] md:text-sm font-medium text-gray-700 dark:text-gray-300">
            Total
          </CardTitle>
          <CreditCard className="h-3 w-3 md:h-5 md:w-5 text-blue-600 dark:text-blue-400" />
        </CardHeader>
        <CardContent className="p-1.5 md:p-4 pt-0 pb-1 -mt-4 md:mt-0">
          <div className="text-base md:text-3xl font-bold text-gray-900 dark:text-white leading-tight">
            {totalPlans}
          </div>
          <CardDescription className="text-[9px] md:text-xs text-gray-600 dark:text-gray-400 mt-0">
            Planes en el sistema
          </CardDescription>
        </CardContent>
      </Card>

      <Card className="bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a] hover:shadow-lg transition-shadow">
        <CardHeader className="flex flex-row items-center justify-between pb-0 p-1.5 md:p-4">
          <CardTitle className="text-[10px] md:text-sm font-medium text-gray-700 dark:text-gray-300">
            En Uso
          </CardTitle>
          <TrendingUp className="h-3 w-3 md:h-5 md:w-5 text-green-600 dark:text-green-400" />
        </CardHeader>
        <CardContent className="p-1.5 md:p-4 pt-0 pb-1 -mt-4 md:mt-0">
          <div className="text-base md:text-3xl font-bold text-gray-900 dark:text-white leading-tight">
            {plansInUse}
          </div>
          <CardDescription className="text-[9px] md:text-xs text-gray-600 dark:text-gray-400 mt-0">
            {usagePercentage}% del total
          </CardDescription>
          <div className="mt-1 w-full bg-gray-200 dark:bg-[#2a2a2a] rounded-full h-1">
            <div
              className="bg-green-600 dark:bg-green-500 h-1 rounded-full transition-all"
              style={{ width: `${usagePercentage}%` }}
            />
          </div>
        </CardContent>
      </Card>

      <Card className="bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a] hover:shadow-lg transition-shadow">
        <CardHeader className="flex flex-row items-center justify-between pb-0 p-1.5 md:p-4">
          <CardTitle className="text-[10px] md:text-sm font-medium text-gray-700 dark:text-gray-300">
            Activos
          </CardTitle>
          <Power className="h-3 w-3 md:h-5 md:w-5 text-purple-600 dark:text-purple-400" />
        </CardHeader>
        <CardContent className="p-1.5 md:p-4 pt-0 pb-1 -mt-4 md:mt-0">
          <div className="text-base md:text-3xl font-bold text-gray-900 dark:text-white leading-tight">
            {plansActive}
          </div>
          <CardDescription className="text-[9px] md:text-xs text-gray-600 dark:text-gray-400 mt-0">
            {activePercentage}% del total
          </CardDescription>
          <div className="mt-1 w-full bg-gray-200 dark:bg-[#2a2a2a] rounded-full h-1">
            <div
              className="bg-purple-600 dark:bg-purple-500 h-1 rounded-full transition-all"
              style={{ width: `${activePercentage}%` }}
            />
          </div>
        </CardContent>
      </Card>

      <Card className="bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a] hover:shadow-lg transition-shadow">
        <CardHeader className="flex flex-row items-center justify-between pb-0 p-1.5 md:p-4">
          <CardTitle className="text-[10px] md:text-sm font-medium text-gray-700 dark:text-gray-300">
