"use client"

import { Upload, X, Loader2 } from "lucide-react"
import { useState, useRef, useEffect } from "react"
import { toast } from "sonner"

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"

interface PhotoUploadProps {
  currentPhoto?: string | null
  onPhotoChange: (photoUrl: string | null) => void
  userId?: string
  disabled?: boolean
  fullName?: string | null
}

export function PhotoUpload({
  currentPhoto,
  onPhotoChange,
  userId,
  disabled = false,
  fullName,
}: PhotoUploadProps) {
  const [preview, setPreview] = useState<string | null>(currentPhoto || null)
  const [uploading, setUploading] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  // Sincronizar preview con currentPhoto cuando cambie desde fuera
  useEffect(() => {
    setPreview(currentPhoto || null)
  }, [currentPhoto])

  const getInitials = () => {
    if (fullName) {
      const parts = fullName.split(" ")
      if (parts.length >= 2) {
        return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase()
      }
      return fullName.slice(0, 2).toUpperCase()
    }
    return "U"
  }

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    // Validar tipo
    const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp']
    if (!allowedTypes.includes(file.type)) {
      toast.error('Tipo de archivo no permitido', {
        description: 'Use JPEG, PNG o WebP',
      })
      return
    }

    // Validar tamaño (5MB)
    const maxSize = 5 * 1024 * 1024
    if (file.size > maxSize) {
      toast.error('Archivo demasiado grande', {
        description: 'El tamaño máximo es 5MB',
      })
      return
    }

    // Mostrar preview inmediatamente
    const reader = new FileReader()
    reader.onloadend = () => {
      setPreview(reader.result as string)
    }
    reader.readAsDataURL(file)

    // Subir archivo
    setUploading(true)
    try {
      const formData = new FormData()
      formData.append('photo', file)

      const response = await fetch('/api/administracion/users/upload-photo', {
        method: 'POST',
        body: formData,
        credentials: 'include',
      })

      const data = await response.json()

      if (!response.ok) {
        throw new Error(data.error || 'Error al subir la foto')
      }

      // Actualizar preview con la URL de la foto
      setPreview(data.photoUrl)
      onPhotoChange(data.photoUrl)
      toast.success('Foto subida correctamente')
    } catch (error: any) {
      console.error('Error subiendo foto:', error)
      toast.error('Error al subir la foto', {
        description: error.message || 'Intente nuevamente',
      })
      // Revertir preview
      setPreview(currentPhoto || null)
    } finally {
      setUploading(false)
      // Limpiar input
      if (fileInputRef.current) {
        fileInputRef.current.value = ''
      }
    }
  }

  const handleRemovePhoto = () => {
    setPreview(null)
    onPhotoChange(null)
    if (fileInputRef.current) {
      fileInputRef.current.value = ''
    }
    toast.success('Foto eliminada')
  }

  return (
    <div className="flex flex-col items-center gap-4">
      <Avatar className="w-24 h-24 border-2 border-gray-200 dark:border-gray-700">
        <AvatarImage src={preview || undefined} alt="Foto de perfil" />
        <AvatarFallback className="bg-gradient-to-br from-blue-500 to-blue-600 text-white text-2xl font-semibold">
          {getInitials()}
        </AvatarFallback>
      </Avatar>

      <div className="flex flex-col gap-2 items-center">
        <Input
          ref={fileInputRef}
          type="file"
          accept="image/jpeg,image/jpg,image/png,image/webp"
          onChange={handleFileSelect}
          disabled={disabled || uploading}
          className="hidden"
          id="photo-upload"
        />

        <div className="flex gap-2">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => fileInputRef.current?.click()}
            disabled={disabled || uploading}
            className="rounded-full"
          >
            {uploading ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Subiendo...
              </>
            ) : (
              <>
                <Upload className="h-4 w-4 mr-2" />
                {preview ? 'Cambiar Foto' : 'Subir Foto'}
              </>
            )}
          </Button>

          {preview && (
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={handleRemovePhoto}
              disabled={disabled || uploading}
              className="rounded-full text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-900/20"
            >
              <X className="h-4 w-4 mr-2" />
              Eliminar
            </Button>
          )}
        </div>

        <p className="text-xs text-gray-500 dark:text-gray-400 text-center">
          JPEG, PNG o WebP. Máximo 5MB
        </p>
      </div>
    </div>
  )
}

"use client";

import { useState, useEffect } from "react";

import { PhotoUpload } from "./photo-upload";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { UserWithDetails } from "@/lib/services/admin/user-admin-service";

interface Role {
  id: string;
  name: string;
  description?: string;
}

interface UserFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  user?: UserWithDetails;
  onSave: (data: any) => void;
}

// Función para capitalizar texto
const capitalizeText = (text: string): string => {
  return text
    .toLowerCase()
    .split(" ")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
};

export function UserFormDialog({
  open,
  onOpenChange,
  user,
  onSave,
}: UserFormDialogProps) {
  const [email, setEmail] = useState(user?.email || "");
  const [ci, setCi] = useState("");
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [address, setAddress] = useState("");
  const [phone, setPhone] = useState("");
  const [roleId, setRoleId] = useState<string>("");
  const [isSuperAdmin, setIsSuperAdmin] = useState(user?.isSuperAdmin || false);
  const [password, setPassword] = useState("");
  const [photo, setPhoto] = useState<string | null>(user?.photo || null);
  const [isLoading, setIsLoading] = useState(false);
  const [roles, setRoles] = useState<Role[]>([]);
  const [rolesLoading, setRolesLoading] = useState(false);

  // Validar si el formulario es válido
  const isFormValid =
    email.trim() !== "" &&
    ci.trim() !== "" &&
    firstName.trim() !== "" &&
    lastName.trim() !== "" &&
    phone.trim() !== "";

  // Cargar roles al abrir el modal
  useEffect(() => {
    if (open) {
      loadRoles();
    }
  }, [open]);

  const loadRoles = async () => {
    try {
      setRolesLoading(true);
      const response = await fetch("/api/administracion/roles");
      if (response.ok) {
        const data = await response.json();
        setRoles(data);
      }
    } catch (error) {
      console.error("Error al cargar roles:", error);
    } finally {
      setRolesLoading(false);
    }
  };

  // Resetear el formulario cuando el modal se abre o se cambia el usuario
  useEffect(() => {
    if (user) {
      setEmail(user.email);
      setCi((user as any).ci || "");
      // Dividir fullName en firstName y lastName
      const fullName = user.fullName || "";
      const nameParts = fullName.split(" ");
      const fName = nameParts[0] || "";
      const lName = nameParts.slice(1).join(" ") || "";
      setFirstName(fName);
      setLastName(lName);
      setAddress(user.address || "");
      setPhone(user.phone || "");
      setPhoto((user as any).photo || null);
      // Intentar obtener el rol del usuario
      // Buscar el rol en la lista de roles cargados por nombre
      const roleMatch = roles.find((r) => r.name === user.role);
      setRoleId(roleMatch?.id || "");
      setIsSuperAdmin(user.isSuperAdmin);
      setPassword("");
    } else {
      setEmail("");
      setCi("");
      setFirstName("");
      setLastName("");
      setAddress("");
      setPhone("");
      setRoleId("");
      setIsSuperAdmin(false);
      setPassword("");
    }
  }, [user, open]);

  // Actualizar el rolId cuando se cargue la lista de roles
  useEffect(() => {
    if (user && roles.length > 0 && !roleId) {
      // Buscar el rol en la lista de roles cargados por nombre
      const roleMatch = roles.find((r) => r.name === user.role);
      if (roleMatch) {
        setRoleId(roleMatch.id);
      }
    }
  }, [roles, user, roleId]);

  // Sincronizar photo cuando cambia el usuario
  useEffect(() => {
    if (user) {
      setPhoto((user as any).photo || null);
    } else {
      setPhoto(null);
    }
  }, [user]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const selectedRole = roles.find((r) => r.id === roleId);
      // Combinar nombre y apellido
      const fullName = `${firstName} ${lastName}`.trim();
      const data: any = {
        email,
        ci,
        fullName,
        address,
        phone,
        role: selectedRole?.name || "user",
        roleId,
        isSuperAdmin,
        isActive: user ? user.isActive : true, // Mantener el estado actual si es edición, crear como activo si es nuevo
        photo: photo || undefined,
      };

      // Para nuevos usuarios, usar el CI como contraseña. Para edición, solo si se especificó password
      if (!user) {
        data.password = ci; // El CI será hasheado en el servidor
      } else if (password && password.trim() !== "") {
        data.password = password;
      }

      await onSave(data);
      onOpenChange(false);
      // Resetear formulario
      setEmail("");
      setCi("");
      setFirstName("");
      setLastName("");
      setAddress("");
      setPhone("");
      setRoleId("");
      setIsSuperAdmin(false);
      setPassword("");
      setPhoto(null);
    } catch (error) {
      console.error("Error al guardar el usuario:", error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg max-h-[90vh] flex flex-col overflow-hidden p-0 rounded-lg">
        <div className="px-6 py-5 border-b border-gray-200 dark:border-[#2a2a2a] bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky top-0 z-10">
          <DialogHeader className="px-0 py-0 space-y-2">
            <DialogTitle>
              {user ? "Editar Usuario" : "Nuevo Usuario"}
            </DialogTitle>
            <DialogDescription>
              {user
                ? "Actualiza la información del usuario"
                : "Completa la información para crear un nuevo usuario"}
            </DialogDescription>
          </DialogHeader>
        </div>
        <form onSubmit={handleSubmit} className="flex flex-col flex-1 min-h-0">
          <div className="flex-1 overflow-y-auto px-6 py-6 space-y-8 bg-gray-50/60 dark:bg-[#0c0c0c]">
            {/* Foto de perfil */}
            <div className="flex justify-center">
              <PhotoUpload
                currentPhoto={photo}
                onPhotoChange={setPhoto}
                userId={user?.id}
                disabled={isLoading}
                fullName={user?.fullName || `${firstName} ${lastName}`.trim() || null}
              />
            </div>

            <div className="grid gap-4">
              <div className="space-y-2">
                <Label
                  htmlFor="ci"
                  className="text-sm font-semibold text-gray-700 dark:text-gray-200"
                >
                  CI (Cédula de Identidad){" "}
                  <span className="text-red-500">*</span>
                </Label>
                <Input
                  id="ci"
                  type="text"
                  placeholder="12345678"
                  value={ci}
                  onChange={(e) => setCi(e.target.value)}
                  required
                  className="rounded-full bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a] text-gray-900 dark:text-white"
                />
              </div>

              <div className="space-y-2">
                <Label
                  htmlFor="email"
                  className="text-sm font-semibold text-gray-700 dark:text-gray-200"
                >
                  Email <span className="text-red-500">*</span>
                </Label>
                <Input
                  id="email"
                  type="email"
                  placeholder="usuario@ejemplo.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  className="rounded-full bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a] text-gray-900 dark:text-white"
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label
                    htmlFor="firstName"
                    className="text-sm font-semibold text-gray-700 dark:text-gray-200"
                  >
                    Nombre <span className="text-red-500">*</span>
                  </Label>
                  <Input
                    id="firstName"
                    placeholder="Juan"
                    value={firstName}
                    onChange={(e) =>
                      setFirstName(capitalizeText(e.target.value))
                    }
                    required
                    className="rounded-full bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a] text-gray-900 dark:text-white"
                  />
                </div>
                <div className="space-y-2">
                  <Label
                    htmlFor="lastName"
                    className="text-sm font-semibold text-gray-700 dark:text-gray-200"
                  >
                    Apellido <span className="text-red-500">*</span>
                  </Label>
                  <Input
                    id="lastName"
                    placeholder="Pérez"
                    value={lastName}
                    onChange={(e) =>
                      setLastName(capitalizeText(e.target.value))
                    }
                    required
                    className="rounded-full bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a] text-gray-900 dark:text-white"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label
                  htmlFor="address"
                  className="text-sm font-semibold text-gray-700 dark:text-gray-200"
                >
                  Dirección
                </Label>
                <Input
                  id="address"
                  placeholder="Calle Principal 123"
                  value={address}
                  onChange={(e) => setAddress(capitalizeText(e.target.value))}
                  className="rounded-full bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a] text-gray-900 dark:text-white"
                />
              </div>

              <div
                className={`grid gap-4 ${
                  isSuperAdmin ? "grid-cols-1" : "grid-cols-1 md:grid-cols-2"
                }`}
              >
                <div className="space-y-2">
                  <Label
                    htmlFor="phone"
                    className="text-sm font-semibold text-gray-700 dark:text-gray-200"
                  >
                    Teléfono <span className="text-red-500">*</span>
                  </Label>
                  <Input
                    id="phone"
                    type="tel"
                    placeholder="+59170000000"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    required
                    className="rounded-full bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a] text-gray-900 dark:text-white"
                  />
                </div>

                {!isSuperAdmin && (
                  <div className="space-y-2">
                    <Label
                      htmlFor="role"
                      className="text-sm font-semibold text-gray-700 dark:text-gray-200"
                    >
                      Rol
                    </Label>
                    <Select
                      value={roleId}
                      onValueChange={setRoleId}
                      disabled={rolesLoading}
                    >
                      <SelectTrigger className="rounded-full w-full bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a] text-gray-900 dark:text-white">
                        <SelectValue
                          placeholder={
                            rolesLoading
                              ? "Cargando roles..."
                              : "Selecciona un rol"
                          }
                        />
                      </SelectTrigger>
                      <SelectContent className="bg-white dark:bg-[#1a1a1a] border border-gray-200 dark:border-[#2a2a2a] text-gray-900 dark:text-white">
                        {roles.map((role) => (
                          <SelectItem
                            key={role.id}
                            value={role.id}
                            className="hover:bg-gray-100 dark:hover:bg-[#2a2a2a]"
                          >
                            {role.name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                )}
              </div>
              {roles.length === 0 && !rolesLoading && (
                <p className="text-xs text-gray-500 dark:text-gray-400">
                  No hay roles disponibles. Crea roles en el módulo de Roles.
                </p>
              )}

              <div className="flex items-center justify-between py-2">
                <div className="space-y-0.5">
                  <Label className="text-sm font-semibold text-gray-700 dark:text-gray-200">
                    Super Administrador
                  </Label>
                  <p className="text-xs text-gray-500 dark:text-gray-400">
                    Acceso completo al sistema
                  </p>
                </div>
                <Switch
                  checked={isSuperAdmin}
                  onCheckedChange={(checked) => {
                    setIsSuperAdmin(checked);
                    // Limpiar el rol si se activa super admin
                    if (checked) {
                      setRoleId("");
                    }
                  }}
                  className="data-[state=checked]:bg-blue-600"
                />
              </div>
            </div>
          </div>
          <DialogFooter className="flex w-full flex-col sm:flex-row sm:justify-center items-center gap-3 border-t border-gray-200 dark:border-[#2a2a2a] px-6 py-4 bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky bottom-0 z-10">
            <Button
              type="button"
              variant="outline"
              className="w-full sm:w-auto rounded-full"
              onClick={() => onOpenChange(false)}
              disabled={isLoading}
            >
              Cancelar
            </Button>
            <Button
              type="submit"
              className="w-full sm:w-auto rounded-full px-6"
              disabled={isLoading || !isFormValid}
            >
              {isLoading ? "Guardando..." : user ? "Actualizar" : "Agregar"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client"

import { Plus } from 'lucide-react'

import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'


interface Version {
  id: string
  version: string
  versionName?: string
  releaseType?: string
  isReleased: boolean
  isCurrent: boolean
  releasedAt?: string
}

interface VersionsClientProps {
  initialVersions: Version[]
  initialCurrentVersion: Version | null
  initialStats: any
}

export function VersionsClient({ initialVersions, initialCurrentVersion, initialStats }: VersionsClientProps) {
  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <div className="flex justify-between items-center">
            <CardTitle>Versión Actual</CardTitle>
            <Button>
              <Plus className="h-4 w-4 mr-2" />
              Nueva Versión
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          {initialCurrentVersion ? (
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <span className="text-2xl font-bold">{initialCurrentVersion.version}</span>
                {initialCurrentVersion.versionName && (
                  <span className="text-muted-foreground">({initialCurrentVersion.versionName})</span>
                )}
                <Badge>Actual</Badge>
              </div>
              {initialCurrentVersion.releasedAt && (
                <p className="text-sm text-muted-foreground">
                  Liberada: {new Date(initialCurrentVersion.releasedAt).toLocaleDateString()}
                </p>
              )}
            </div>
          ) : (
            <p className="text-muted-foreground">No hay versión actual</p>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Historial de Versiones</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {initialVersions.map((version) => (
              <div key={version.id} className="border rounded-lg p-4">
                <div className="flex justify-between items-start">
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-semibold">{version.version}</span>
                      {version.versionName && (
                        <span className="text-muted-foreground">({version.versionName})</span>
                      )}
                      {version.isCurrent && <Badge>Actual</Badge>}
                      {version.isReleased && <Badge variant="outline">Liberada</Badge>}
                      {version.releaseType && (
                        <Badge variant="secondary">{version.releaseType}</Badge>
                      )}
                    </div>
                    {version.releasedAt && (
                      <p className="text-sm text-muted-foreground mt-1">
                        {new Date(version.releasedAt).toLocaleDateString()}
                      </p>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { useState } from 'react'

import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Switch } from '@/components/ui/switch'
import { useToast } from '@/hooks/use-toast'

interface Organization {
  id: string
  name: string
  slug: string
}

interface Branding {
  id?: string
  organizationId: string
  logoUrl?: string
  faviconUrl?: string
  primaryColor?: string
  secondaryColor?: string
  customEmailDomain?: string
  customEmailFrom?: string
  companyName?: string
  companyWebsite?: string
  enabled?: boolean
  organization?: Organization
}

interface WhiteLabelClientProps {
  initialOrganizations: Organization[]
}

export function WhiteLabelClient({ initialOrganizations }: WhiteLabelClientProps) {
  const [organizations] = useState(initialOrganizations)
  const [selectedOrg, setSelectedOrg] = useState<string | null>(null)
  const [branding, setBranding] = useState<Branding | null>(null)
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const { toast } = useToast()

  const handleSelectOrg = async (orgId: string) => {
    setSelectedOrg(orgId)
    setIsLoading(true)
    try {
      const res = await fetch(`/api/administracion/white-label/${orgId}`)
      const data = await res.json()
      if (data.success) {
        setBranding(data.branding || { organizationId: orgId, enabled: false })
        setIsDialogOpen(true)
      }
    } catch (error) {
      toast({ title: 'Error', description: 'Error al cargar branding', variant: 'destructive' })
    } finally {
      setIsLoading(false)
    }
  }

  const handleSave = async () => {
    if (!selectedOrg || !branding) return

    setIsLoading(true)
    try {
      const res = await fetch(`/api/administracion/white-label/${selectedOrg}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(branding),
      })
      const data = await res.json()
      if (data.success) {
        toast({ title: 'Éxito', description: 'Branding actualizado correctamente' })
        setIsDialogOpen(false)
      } else {
        throw new Error(data.error)
      }
    } catch (error: any) {
      toast({ title: 'Error', description: error.message || 'Error al guardar branding', variant: 'destructive' })
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Organizaciones</CardTitle>
          <CardDescription>Selecciona una organización para configurar su branding</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            {organizations.map((org) => (
              <div
                key={org.id}
                className="flex items-center justify-between p-4 border rounded-lg hover:bg-accent cursor-pointer"
                onClick={() => handleSelectOrg(org.id)}
              >
                <div>
                  <p className="font-medium">{org.name}</p>
                  <p className="text-sm text-muted-foreground">{org.slug}</p>
                </div>
                <Button variant="outline" size="sm">
                  Configurar
                </Button>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Configurar Branding</DialogTitle>
            <DialogDescription>
              Personaliza la apariencia y branding para esta organización
            </DialogDescription>
          </DialogHeader>
          {branding && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <Label htmlFor="enabled">Habilitado</Label>
                <Switch
                  id="enabled"
                  checked={branding.enabled}
                  onCheckedChange={(checked) => setBranding({ ...branding, enabled: checked })}
                />
              </div>
              <div>
                <Label htmlFor="logoUrl">URL del Logo</Label>
                <Input
                  id="logoUrl"
                  value={branding.logoUrl || ''}
                  onChange={(e) => setBranding({ ...branding, logoUrl: e.target.value })}
                  placeholder="https://ejemplo.com/logo.png"
                />
              </div>
              <div>
                <Label htmlFor="faviconUrl">URL del Favicon</Label>
                <Input
                  id="faviconUrl"
                  value={branding.faviconUrl || ''}
                  onChange={(e) => setBranding({ ...branding, faviconUrl: e.target.value })}
                  placeholder="https://ejemplo.com/favicon.ico"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="primaryColor">Color Primario</Label>
                  <Input
                    id="primaryColor"
                    type="color"
                    value={branding.primaryColor || '#000000'}
                    onChange={(e) => setBranding({ ...branding, primaryColor: e.target.value })}
                  />
                </div>
                <div>
                  <Label htmlFor="secondaryColor">Color Secundario</Label>
                  <Input
                    id="secondaryColor"
                    type="color"
                    value={branding.secondaryColor || '#000000'}
                    onChange={(e) => setBranding({ ...branding, secondaryColor: e.target.value })}
                  />
                </div>
              </div>
