interface SasSession {
  userId: string
  nombre?: string
  apellido?: string
  fullName?: string
  correo?: string
  rol?: string | null
  foto?: string | null
  customerSlug: string
  customerId: string
  sucursalId?: string | null
}

function getCookie(name: string): string | null {
  if (typeof document === 'undefined') return null
  const value = `; ${document.cookie}`
  const parts = value.split(`; ${name}=`)
  if (parts.length === 2) return parts.pop()!.split(';').shift() || null
  return null
}

function setCookie(name: string, value: string, days = 365) {
  if (typeof document === 'undefined') return
  const isProduction = typeof window !== 'undefined' && window.location.protocol === 'https:'
  const expires = new Date(Date.now() + days * 24 * 60 * 60 * 1000).toUTCString()
  document.cookie = `${name}=${encodeURIComponent(value)}; Path=/; SameSite=Lax; Expires=${expires}${isProduction ? '; Secure' : ''}`
}

export function SalesHeader() {
  const pathname = usePathname()
  const [session, setSession] = useState<SasSession | null>(null)
  const { theme, setTheme } = useTheme()
  const [mounted, setMounted] = useState(false)

  const fetchUserFromAPI = async () => {
    try {
      const slug = pathname.split('/').filter(Boolean)[0]
      if (!slug) return
      
      const response = await fetch(`/api/${slug}/auth/me`, {
        credentials: 'include'
      })
      
      if (response.ok) {
        const userData = await response.json()
        if (userData) {
          const newSession = {
            userId: userData.id,
            nombre: userData.nombre,
            apellido: userData.apellido,
            fullName: `${userData.nombre || ''} ${userData.apellido || ''}`.trim() || userData.email || 'Usuario',
            email: userData.email,
            rol: userData.rol?.nombre || null,
            foto: userData.foto || null,
            customerSlug: slug,
            customerId: userData.organizationId || '',
            sucursalId: userData.sucursalId || null,
          }
          setSession(newSession)
          
          // Actualizar la cookie de sesión con la nueva información
          const sessionData = {
            ...newSession,
            organizationSlug: slug,
          }
          const sessionEncoded = btoa(JSON.stringify(sessionData))
          setCookie('sas-session', sessionEncoded)
        }
      }
    } catch (error) {
      console.error('Error obteniendo usuario desde API:', error)
    }
  }

  useEffect(() => {
    const loadSession = async () => {
      try {
        const raw = getCookie('sas-session')
        if (raw) {
          // La sesión está codificada en base64
          try {
            // Decodificar base64 en el navegador usando atob
            const decoded = atob(raw)
            const parsed = JSON.parse(decoded)
            // Normalizar customerSlug (puede venir como organizationSlug)
            if (parsed.organizationSlug && !parsed.customerSlug) {
              parsed.customerSlug = parsed.organizationSlug
            }
            setSession(parsed)
          } catch {
            // Si falla el parseo base64, intentar como JSON directo (para compatibilidad)
            try {
              const parsed = JSON.parse(decodeURIComponent(raw))
              // Normalizar customerSlug
              if (parsed.organizationSlug && !parsed.customerSlug) {
                parsed.customerSlug = parsed.organizationSlug
              }
              setSession(parsed)
            } catch {
              // Si ambos fallan, intentar obtener desde la API
              await fetchUserFromAPI()
            }
          }
        } else {
          // Si no hay cookie, intentar obtener desde la API
          await fetchUserFromAPI()
        }
      } catch (error) {
        console.error('Error cargando sesión:', error)
        // Intentar obtener desde la API como fallback
        await fetchUserFromAPI()
      }
      setMounted(true)
    }

    loadSession()

    // Escuchar eventos personalizados para actualizar la sesión cuando se actualice el usuario
    const handleUserUpdated = (event: CustomEvent) => {
      const updatedUser = event.detail
      if (updatedUser) {
        // Verificar si es el usuario logueado comparando con la cookie de sesión
        const currentSession = getCookie('sas-session')
        if (currentSession) {
          try {
            const decoded = atob(currentSession)
            const parsed = JSON.parse(decoded)
            if (parsed.userId === updatedUser.id) {
              // Si el usuario actualizado es el usuario logueado, refrescar la sesión
              fetchUserFromAPI()
            }
          } catch {
            // Si no se puede parsear, intentar refrescar de todas formas
            fetchUserFromAPI()
          }
        }
      }
    }

    window.addEventListener('sas-user-updated', handleUserUpdated as EventListener)
    
    // Escuchar cambios en storage (por si se actualiza desde otra pestaña)
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'sas-user-updated') {
        fetchUserFromAPI()
      }
    }
    window.addEventListener('storage', handleStorageChange)

    return () => {
      window.removeEventListener('sas-user-updated', handleUserUpdated as EventListener)
      window.removeEventListener('storage', handleStorageChange)
    }
  }, [pathname])

  const fullName = session?.fullName || `${session?.nombre || ''} ${session?.apellido || ''}`.trim() || 'Usuario'
  const slug = session?.customerSlug || pathname.split('/').filter(Boolean)[0]

  useEffect(() => {
    // Al montar, leer el tema por cliente desde cookie y aplicarlo
    const key = slug ? `sas-theme-${slug}` : 'sas-theme'
    const saved = getCookie(key)
    if (saved && (saved === 'light' || saved === 'dark' || saved === 'system')) {
      setTheme(saved)
    }
    // Cargar color del sistema desde preferencias
    if (slug) {
      const prefsRaw = getCookie(`sas-prefs-${slug}`)
      if (prefsRaw) {
        try {
          const prefs = JSON.parse(decodeURIComponent(prefsRaw))
          const color = prefs.themeColor || 'green'
          if (typeof document !== 'undefined') {
            document.documentElement.setAttribute('data-sas-color', color)
          }
        } catch {}
      }
    }
  }, [slug, setTheme])

  const applyTheme = (value: 'light' | 'dark' | 'system') => {
    setTheme(value)
    const key = slug ? `sas-theme-${slug}` : 'sas-theme'
    setCookie(key, value)
  }

  const handleLogout = async () => {
    const slug = session?.customerSlug || pathname.split('/').filter(Boolean)[0]
    try {
      await fetch(`/${slug ? 'api/' + slug + '/logout' : '/api/logout'}`, { method: 'POST' })
    } catch {}
    window.location.href = `/${slug}/login`
  }

  const { toggle } = useSidebar()

  return (
    <header className="fixed top-0 left-0 lg:left-64 right-0 h-16 z-30 lg:bg-white lg:dark:bg-[#1a1a1a] lg:border-b lg:border-gray-200 lg:dark:border-[#2a2a2a]">
      {/* Header flotante en móvil */}
      <div className="lg:hidden fixed top-4 left-4 right-4 h-14 bg-white/95 dark:bg-[#1a1a1a]/95 backdrop-blur-sm rounded-2xl shadow-lg border border-gray-200/50 dark:border-[#2a2a2a]/50">
        <div className="flex items-center justify-between h-full px-4">
          <div className="flex items-center gap-2">
            {/* Botón hamburguesa para móvil */}
            <Button
              variant="ghost"
              size="icon"
              className="mr-2"
              onClick={toggle}
            >
              <Menu className="h-5 w-5" />
            </Button>
            <div className="font-semibold text-gray-800 dark:text-gray-200 flex items-center gap-2">
              <Building2 className="h-5 w-5" />
              <span className="text-sm">{session?.customerSlug || 'SAS'}</span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {/* Notificaciones */}
            <NotificationsDropdown system="sas" slug={slug} />
            {/* Toggle de tema */}
            {mounted && (
              <button
                onClick={() => {
                  const current = theme || 'system'
                  if (current === 'light') applyTheme('dark')
                  else if (current === 'dark') applyTheme('system')
                  else applyTheme('light')
                }}
                className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-[#2a2a2a] transition-colors"
                title="Tema"
              >
                {theme === 'light' ? (
                  <Sun className="h-5 w-5 text-gray-600 dark:text-gray-300" />
                ) : theme === 'dark' ? (
                  <Moon className="h-5 w-5 text-gray-600 dark:text-gray-300" />
                ) : (
                  <Monitor className="h-5 w-5 text-gray-600 dark:text-gray-300" />
                )}
              </button>
            )}
            <DropdownMenu>
              <DropdownMenuTrigger className="flex items-center gap-2 outline-none">
                <Avatar className="w-7 h-7">
                  {session?.foto && <AvatarImage src={session.foto} alt={fullName} />}
                  <AvatarFallback style={{ background: 'var(--primary)', color: 'var(--primary-foreground)' } as CSSProperties}>
                    {(fullName || 'U').slice(0,2).toUpperCase()}
                  </AvatarFallback>
                </Avatar>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-56">
                <DropdownMenuLabel>Cuenta</DropdownMenuLabel>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => { const slug = session?.customerSlug || pathname.split('/').filter(Boolean)[0]; window.location.href = `/${slug}/perfil` }}>Perfil</DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={handleLogout} className="text-red-600 focus:text-red-600">
                  <LogOut className="mr-2 h-4 w-4" /> Salir
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>
      </div>
      
      {/* Header normal en desktop */}
      <div className="hidden lg:flex items-center justify-between h-full px-6">
        <div className="flex items-center gap-2">
          <div className="font-semibold text-gray-800 dark:text-gray-200 flex items-center gap-2">
            <Building2 className="h-5 w-5" />
            <span>{session?.customerSlug || 'SAS'}</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          {/* Notificaciones */}
          <NotificationsDropdown system="sas" slug={slug} />
          {/* Toggle de tema */}
          {mounted && (
            <div className="relative group">
              <button
                onClick={() => {
                  const current = theme || 'system'
                  if (current === 'light') applyTheme('dark')
                  else if (current === 'dark') applyTheme('system')
                  else applyTheme('light')
                }}
                className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-[#2a2a2a] transition-colors"
                title="Tema"
              >
                {theme === 'light' ? (
                  <Sun className="h-5 w-5 text-gray-600 dark:text-gray-300" />
                ) : theme === 'dark' ? (
                  <Moon className="h-5 w-5 text-gray-600 dark:text-gray-300" />
                ) : (
                  <Monitor className="h-5 w-5 text-gray-600 dark:text-gray-300" />
                )}
              </button>
              <div className="absolute right-0 top-full mt-2 w-32 bg-white dark:bg-[#1a1a1a] border border-gray-200 dark:border-[#2a2a2a] rounded-lg shadow-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-50">
                <div className="p-1">
                  <button onClick={() => applyTheme('light')} className={`w-full text-left px-3 py-2 rounded hover:bg-gray-100 dark:hover:bg-[#2a2a2a] text-sm ${theme==='light'?'font-semibold':''}`}> 
                    <Sun className="inline h-4 w-4 mr-2" /> Claro
                  </button>
                  <button onClick={() => applyTheme('dark')} className={`w-full text-left px-3 py-2 rounded hover:bg-gray-100 dark:hover:bg-[#2a2a2a] text-sm ${theme==='dark'?'font-semibold':''}`}>
                    <Moon className="inline h-4 w-4 mr-2" /> Oscuro
                  </button>
                  <button onClick={() => applyTheme('system')} className={`w-full text-left px-3 py-2 rounded hover:bg-gray-100 dark:hover:bg-[#2a2a2a] text-sm ${theme==='system'?'font-semibold':''}`}>
                    <Monitor className="inline h-4 w-4 mr-2" /> Sistema
                  </button>
                </div>
              </div>
            </div>
          )}
          <DropdownMenu>
            <DropdownMenuTrigger className="flex items-center gap-3 outline-none">
              <div className="hidden sm:flex flex-col items-end mr-1">
                <span className="text-sm text-gray-900 dark:text-white">{fullName}</span>
                <span className="text-xs text-gray-500 dark:text-gray-400">{session?.rol || 'Usuario'}</span>
              </div>
              <Avatar className="w-8 h-8">
                {session?.foto && <AvatarImage src={session.foto} alt={fullName} />}
                <AvatarFallback style={{ background: 'var(--primary)', color: 'var(--primary-foreground)' } as CSSProperties}>
                  {(fullName || 'U').slice(0,2).toUpperCase()}
                </AvatarFallback>
              </Avatar>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-56">
              <DropdownMenuLabel>Cuenta</DropdownMenuLabel>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={() => { const slug = session?.customerSlug || pathname.split('/').filter(Boolean)[0]; window.location.href = `/${slug}/perfil` }}>Perfil</DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={handleLogout} className="text-red-600 focus:text-red-600">
                <LogOut className="mr-2 h-4 w-4" /> Salir
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </header>
  )
}

"use client"

import { X } from "lucide-react"
import {
  LayoutDashboard,
  Users,
  ShoppingBag,
  FileText,
  ShoppingCart,
  Banknote,
  BarChart3,
  Receipt,
  DollarSign,
  Building2,
  Settings
} from "lucide-react"
import Link from "next/link"
import { usePathname, useRouter } from "next/navigation"
import { toast } from "sonner"

import { useSidebar } from "./sidebar-context"

import type { CSSProperties, ComponentType } from "react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"




interface NavItem { title: string; href: string; icon: ComponentType<{ className?: string }>; }
interface NavSection { label: string; items: NavItem[] }

interface SalesSidebarProps {
  organizationSlug: string
}

export function SalesSidebar({ organizationSlug }: SalesSidebarProps) {
  const pathname = usePathname()
  const router = useRouter()
  const { isOpen, close } = useSidebar()

  const sections: NavSection[] = [
    {
      label: 'Inicio',
      items: [
        { title: 'Dashboard', href: `/${organizationSlug}/dashboard`, icon: LayoutDashboard },
      ],
    },
    {
      label: 'Operación',
      items: [
        { title: 'Ventas', href: `/${organizationSlug}/ventas`, icon: ShoppingCart },
        { title: 'Cajas', href: `/${organizationSlug}/cajas`, icon: Banknote },
        { title: 'Cotizaciones', href: `/${organizationSlug}/cotizaciones`, icon: Receipt },
        { title: 'Gastos', href: `/${organizationSlug}/gastos`, icon: DollarSign },
      ],
    },
    {
      label: 'Catálogo',
      items: [
        { title: 'Productos', href: `/${organizationSlug}/productos`, icon: ShoppingBag },
        { title: 'Categorías', href: `/${organizationSlug}/categorias`, icon: ShoppingBag },
        { title: 'Clientes', href: `/${organizationSlug}/clientes`, icon: Users },
      ],
    },
    {
      label: 'Gestión',
      items: [
        { title: 'Usuarios', href: `/${organizationSlug}/usuarios`, icon: Users },
        { title: 'Roles', href: `/${organizationSlug}/roles`, icon: Users },
        { title: 'Permisos', href: `/${organizationSlug}/permisos`, icon: FileText },
        { title: 'Sucursales', href: `/${organizationSlug}/sucursales`, icon: Building2 },
        { title: 'Configuración', href: `/${organizationSlug}/configuracion`, icon: Settings },
      ],
    },
    {
      label: 'Reportes',
      items: [
        { title: 'Reportes', href: `/${organizationSlug}/reportes`, icon: BarChart3 },
      ],
    },
  ]

  const handleLogout = async () => {
    try {
      const response = await fetch(`/api/${organizationSlug}/logout`, {
        method: "POST",
      })

      if (response.ok) {
        toast.success("Sesión cerrada correctamente")
        router.push(`/${organizationSlug}/login`)
        router.refresh()
      } else {
        toast.error("Error al cerrar sesión")
      }
    } catch (error) {
      toast.error("Error al cerrar sesión")
    }
  }

  return (
    <>
      {/* Overlay para móvil */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={close}
        />
      )}
      
      <aside className={cn(
        "fixed left-0 top-0 h-full w-64 bg-white dark:bg-[#1a1a1a] text-gray-900 dark:text-white border-r border-gray-200 dark:border-[#2a2a2a] z-50 transition-transform duration-300 ease-in-out",
        "lg:translate-x-0",
        isOpen ? "translate-x-0" : "-translate-x-full"
      )}>
        <div className="flex flex-col h-full">
          {/* Logo y título */}
          <div className="flex items-center justify-between p-6 border-b border-gray-200 dark:border-[#2a2a2a]">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-gradient-to-br from-green-500 to-green-600 rounded-lg flex items-center justify-center">
                <ShoppingCart className="h-5 w-5 text-white" />
              </div>
              <div>
                <h1 className="text-lg font-semibold text-gray-900 dark:text-white">Sistema Ventas</h1>
                <p className="text-xs text-gray-500 dark:text-gray-400">{organizationSlug}</p>
              </div>
            </div>
            {/* Botón cerrar en móvil */}
            <Button
              variant="ghost"
              size="icon"
              className="lg:hidden"
              onClick={close}
            >
              <X className="h-5 w-5" />
            </Button>
          </div>

        {/* Navegación */}
        <nav className="flex-1 overflow-y-auto p-3">
          {sections.map((section) => (
            <div key={section.label} className="mb-4">
              <div className="px-3 py-2 text-xs font-semibold uppercase tracking-wider text-gray-500 dark:text-gray-400">
                {section.label}
              </div>
              <ul className="space-y-1">
                {section.items.map((item) => {
                  const Icon = item.icon
                  const isActive = pathname === item.href || pathname.startsWith(`${item.href}/`)
                  return (
                    <li key={item.href}>
                  <Link
                        href={item.href}
                        onClick={() => close()}
                        className={cn(
                          "flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors",
                      !isActive && "text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-[#2a2a2a] hover:text-gray-900 dark:hover:text-white"
                        )}
                    style={isActive ? ({ background: 'var(--primary)', color: 'var(--primary-foreground)' } as CSSProperties) : undefined}
                      >
                        <Icon className={cn(
                          "h-5 w-5",
                      isActive ? "text-white" : "text-gray-500 dark:text-gray-400"
                        )} />
                        {item.title}
                      </Link>
                    </li>
                  )
                })}
              </ul>
            </div>
          ))}
        </nav>

        {/* Footer espacio */}
        <div className="p-3 border-t border-transparent" />
        </div>
      </aside>
    </>
  )
}

"use client";

import { Branch } from "@prisma/client";
import {
  Building2,
  Mail,
  Phone,
  MapPin,
  Users,
  Calendar,
  CheckCircle2,
  XCircle,
  User,
} from "lucide-react";
import { useState, useEffect } from "react";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Separator } from "@/components/ui/separator";

interface BranchDetailDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  branch: (Branch & {
    organization?: {
      id: string;
      razonSocial: string | null;
      name: string | null;
      slug: string | null;
    } | null;
    _count?: { usuariosSas: number };
  }) | null;
  customerSlug: string;
}

interface UsuarioAsociado {
  id: string;
  nombre: string | null;
  apellido: string | null;
  ci: string | null;
  correo: string | null;
  telefono: string | null;
  isActive: boolean;
  foto: string | null;
  rol?: {
    id: string;
    nombre: string;
  } | null;
}

export function BranchDetailDialog({
  open,
  onOpenChange,
  branch,
  customerSlug,
}: BranchDetailDialogProps) {
  const [usuarios, setUsuarios] = useState<UsuarioAsociado[]>([]);
  const [isLoadingUsuarios, setIsLoadingUsuarios] = useState(false);

  useEffect(() => {
    if (open && branch?.id) {
      loadUsuarios();
    } else {
      setUsuarios([]);
    }
  }, [open, branch?.id, customerSlug]);

  const loadUsuarios = async () => {
    if (!branch?.id) return;
    
    setIsLoadingUsuarios(true);
    try {
      // Usar endpoint optimizado específico para usuarios de sucursal
      const response = await fetch(
        `/api/${customerSlug}/sucursales/${branch.id}/usuarios`,
        {
          credentials: 'include',
          cache: 'no-store' // Evitar cache para obtener datos actualizados
        }
      );
      if (response.ok) {
        const data = await response.json();
        setUsuarios(data.usuarios || []);
      } else {
        console.error("Error cargando usuarios:", response.statusText);
        setUsuarios([]);
      }
    } catch (error) {
      console.error("Error cargando usuarios:", error);
      setUsuarios([]);
    } finally {
      setIsLoadingUsuarios(false);
    }
  };

  if (!branch) return null;

  const usuariosActivos = usuarios.filter((u) => u.isActive).length;
  const usuariosInactivos = usuarios.filter((u) => !u.isActive).length;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[700px] max-h-[90vh] flex flex-col overflow-hidden p-0 rounded-lg">
        {/* Header estático */}
        <div className="px-6 py-5 border-b border-gray-200 dark:border-[#2a2a2a] bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky top-0 z-10">
          <DialogHeader className="px-0 py-0 space-y-2">
            <DialogTitle className="flex items-center gap-3">
              <div className="h-10 w-10 rounded-lg bg-purple-500 dark:bg-purple-600 flex items-center justify-center">
                <Building2 className="h-5 w-5 text-white" />
              </div>
              <span>Detalles de la Sucursal</span>
            </DialogTitle>
            <DialogDescription>
              Información completa de la sucursal y usuarios asociados
            </DialogDescription>
          </DialogHeader>
        </div>

        {/* Contenido con scroll */}
        <div className="flex-1 overflow-y-auto px-6 py-6 space-y-6 bg-gray-50/60 dark:bg-[#0c0c0c]">
          {/* Información de la Sucursal */}
          <div className="space-y-3">
            <h3 className="text-base font-semibold text-gray-900 dark:text-white flex items-center gap-2">
              <Building2 className="h-4 w-4 text-purple-600 dark:text-purple-400" />
              Información General
            </h3>
            <div className="bg-white dark:bg-[#1a1a1a] rounded-lg p-4 border border-gray-200 dark:border-[#2a2a2a]">
              <div className="flex items-start gap-3">
             
                <div className="flex-1 space-y-2.5">
                  {/* Nombre y Estado en la misma línea */}
                  <div className="flex items-center justify-between gap-3">
                    <div className="flex-1 min-w-0">
                      <p className="text-base font-semibold text-gray-900 dark:text-white truncate">
                        {branch.name}
                      </p>
                    </div>
                    <Badge
                      className={
                        branch.isActive
                          ? "bg-green-100 text-green-700 dark:bg-green-900/20 dark:text-green-400 border-green-200 dark:border-green-800 flex-shrink-0"
                          : "bg-gray-100 text-gray-700 dark:bg-gray-900/20 dark:text-gray-400 border-gray-200 dark:border-gray-800 flex-shrink-0"
                      }
                    >
                      {branch.isActive ? (
                        <>
                          <CheckCircle2 className="h-3 w-3 mr-1" />
                          Activa
                        </>
                      ) : (
                        <>
                          <XCircle className="h-3 w-3 mr-1" />
                          Inactiva
                        </>
                      )}
                    </Badge>
                  </div>

                  {/* Información de contacto en grid compacto */}
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                    {branch.email && (
                      <div className="flex items-center gap-2 text-sm">
                        <Mail className="h-3.5 w-3.5 text-gray-400 flex-shrink-0" />
                        <span className="text-gray-900 dark:text-white truncate">{branch.email}</span>
                      </div>
                    )}
                    {branch.phone && (
                      <div className="flex items-center gap-2 text-sm">
                        <Phone className="h-3.5 w-3.5 text-gray-400 flex-shrink-0" />
                        <span className="text-gray-900 dark:text-white">{branch.phone}</span>
                      </div>
                    )}
                  </div>

                  {/* Dirección */}
                  {branch.address && (
                    <div className="flex items-start gap-2 text-sm">
