"use client"

import { SalesProduct, Category, Branch } from "@prisma/client"
import { useState } from "react"

import { ProductsFilters } from "./products-filters"
import { ProductsGrid } from "./products-grid"
import { ProductsPagination } from "./products-pagination"
import { ProductsStats } from "./products-stats"
import { ProductsTable } from "./products-table"

import { Card, CardContent } from "@/components/ui/card"


interface ProductsContainerProps {
  products: (SalesProduct & { category: Category | null; branch: Branch | null })[]
  categoryName?: string
  showBranchColumn?: boolean
  isAdmin?: boolean
  branches?: Branch[]
  selectedBranchId?: string | null
  onBranchChange?: (branchId: string | null) => void
  userBranchId?: string | null
  onEdit?: (product: SalesProduct & { category: Category | null; branch: Branch | null }) => void
  onToggleStatus?: (product: SalesProduct & { category: Category | null; branch: Branch | null }) => void
  onDelete?: (product: SalesProduct & { category: Category | null; branch: Branch | null }) => void
}

export function ProductsContainer({ 
  products, 
  categoryName, 
  showBranchColumn = false, 
  isAdmin = false,
  branches = [],
  selectedBranchId = null,
  onBranchChange,
  userBranchId = null,
  onEdit, 
  onToggleStatus, 
  onDelete 
}: ProductsContainerProps) {
  const [pageSize, setPageSize] = useState(10)
  const [currentPage, setCurrentPage] = useState(1)
  const [statusFilter, setStatusFilter] = useState("all")
  const [searchTerm, setSearchTerm] = useState("")
  const [viewMode, setViewMode] = useState<"table" | "grid">("table")

  // Determinar el branchId a usar para filtrar
  const effectiveBranchId = (() => {
    if (!isAdmin) {
      // Si no es admin, filtrar por su sucursal
      return userBranchId
    }
    // Si es admin, usar la sucursal seleccionada (puede ser null para "todas")
    return selectedBranchId
  })()

  // Filtrar productos por sucursal, búsqueda y estado
  const filteredProducts = products.filter(product => {
    // Filtrar por sucursal
    if (effectiveBranchId !== null && effectiveBranchId !== undefined) {
      if (product.branchId !== effectiveBranchId) return false
    }

    // Filtrar por búsqueda
    if (searchTerm && searchTerm.trim() !== "") {
      const searchLower = searchTerm.toLowerCase()
      const matchesSearch = 
        product.name?.toLowerCase().includes(searchLower) ||
        product.description?.toLowerCase().includes(searchLower) ||
        product.sku?.toLowerCase().includes(searchLower) ||
        product.barcode?.toLowerCase().includes(searchLower)
      
      if (!matchesSearch) return false
    }

    // Filtrar por estado
    if (statusFilter === "active") return product.isActive
    if (statusFilter === "inactive") return !product.isActive
    return true // "all" - mostrar todos
  })

  const handleSearchChange = (term: string) => {
    setSearchTerm(term)
    setCurrentPage(1)
  }

  // Calcular productos para la página actual
  const startIndex = (currentPage - 1) * pageSize
  const endIndex = startIndex + pageSize
  const currentProducts = filteredProducts.slice(startIndex, endIndex)

  const handleStatusChange = (status: string) => {
    setStatusFilter(status)
    setCurrentPage(1)
  }

  const handlePageSizeChange = (size: number) => {
    setPageSize(size)
    setCurrentPage(1)
  }

  const handlePageChange = (page: number) => {
    setCurrentPage(page)
  }

  const handleBranchChange = (branchId: string | null) => {
    if (onBranchChange) {
      onBranchChange(branchId)
    }
    setCurrentPage(1) // Resetear a la primera página cuando cambia la sucursal
  }

  return (
    <div className="space-y-4 md:space-y-6">
      {/* Estadísticas */}
      <ProductsStats products={filteredProducts} />

      {/* Filtros en Card */}
      <Card className="bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a]">
        <CardContent className="pt-6">
          <ProductsFilters 
            onPageSizeChange={handlePageSizeChange}
            onStatusChange={handleStatusChange}
            onSearchChange={handleSearchChange}
            statusValue={statusFilter}
            isAdmin={isAdmin}
            branches={branches}
            selectedBranchId={selectedBranchId}
            onBranchChange={handleBranchChange}
            viewMode={viewMode}
            onViewModeChange={(mode) => {
              setViewMode(mode)
              setCurrentPage(1)
            }}
          />
        </CardContent>
      </Card>

      {viewMode === "table" ? (
        <div className="rounded-md border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#1a1a1a] overflow-hidden">
          <ProductsTable 
            products={currentProducts.map(p => ({
              ...p,
              price: typeof p.price === 'object' && 'toNumber' in p.price ? p.price.toNumber() : Number(p.price),
              cost: typeof p.cost === 'object' && 'toNumber' in p.cost ? p.cost.toNumber() : Number(p.cost),
            })) as any} 
            showBranchColumn={showBranchColumn}
            onEditClick={onEdit as any} 
            onToggleStatus={onToggleStatus as any} 
            onDeleteClick={onDelete as any} 
          />
        </div>
      ) : (
        <ProductsGrid
          products={currentProducts}
          showBranchColumn={showBranchColumn}
          onEdit={onEdit}
          onToggleStatus={onToggleStatus}
          onDelete={onDelete}
        />
      )}

      {/* Paginación */}
      <div className="flex justify-center">
        <ProductsPagination
          currentPage={currentPage}
          totalPages={Math.ceil(filteredProducts.length / pageSize)}
          pageSize={pageSize}
          onPageChange={handlePageChange}
          onPageSizeChange={handlePageSizeChange}
        />
      </div>
    </div>
  )
}

"use client"

import { SalesProduct, Category, Branch } from "@prisma/client"
import { useState, useEffect, useCallback } from "react"

import { CategoryCards } from "./category-cards"
import { ProductDeleteDialog } from "./product-delete-dialog"
import { ProductFormDialog } from "./product-form-dialog"
import { ProductsContainer } from "./products-container"
import { ProductsHeader } from "./products-header"

import { useProductActions } from "@/hooks/sales/product/use-product-actions"

interface ProductsPageClientProps {
  initialCategories: Category[]
  customerSlug: string
}

export function ProductsPageClient({ initialCategories, customerSlug }: ProductsPageClientProps) {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null)
  const [products, setProducts] = useState<(SalesProduct & { category: Category | null; branch: Branch | null })[]>([])
  const [categories, setCategories] = useState<Category[]>(initialCategories)
  const [isLoading, setIsLoading] = useState(false)
  const [showBranchColumn, setShowBranchColumn] = useState(false)
  const [isAdmin, setIsAdmin] = useState(false)
  const [branches, setBranches] = useState<Branch[]>([])
  const [selectedBranchId, setSelectedBranchId] = useState<string | null>(null)
  const [userBranchId, setUserBranchId] = useState<string | null>(null)

  const selectedCategoryName = selectedCategory
    ? categories.find((category) => category.id === selectedCategory)?.name
    : undefined

  // Función para cargar productos
  const loadProducts = useCallback(async () => {
    if (!selectedCategory) {
      setProducts([])
      return
    }

    setIsLoading(true)
    try {
      const response = await fetch(`/api/${customerSlug}/productos?categoryId=${selectedCategory}&page=1&pageSize=1000`)
      const data = await response.json()
      setProducts(data.products || [])
    } catch (error) {
      console.error('Error al cargar productos:', error)
      setProducts([])
    } finally {
      setIsLoading(false)
    }
  }, [selectedCategory, customerSlug])

  // Obtener información del usuario y sucursales
  useEffect(() => {
    const fetchUserInfo = async () => {
      try {
        const userResponse = await fetch(`/api/${customerSlug}/auth/me`)
        if (userResponse.ok) {
          const userData = await userResponse.json()
          const userRoleName = userData.rol?.nombre?.toLowerCase() || ""
          const isUserAdmin = userRoleName.includes("administrador") || userRoleName === "admin"
          setIsAdmin(isUserAdmin)
          setShowBranchColumn(isUserAdmin)
          setUserBranchId(userData.sucursalId || null)

          // Si es administrador, cargar sucursales activas
          if (isUserAdmin) {
            try {
              const branchesResponse = await fetch(`/api/${customerSlug}/sucursales?status=active&page=1&pageSize=1000`)
              if (branchesResponse.ok) {
                const branchesData = await branchesResponse.json()
                setBranches(branchesData.branches || [])
              }
            } catch (error) {
              console.error("Error al cargar sucursales:", error)
            }
          }
        }
      } catch (error) {
        console.error("Error al obtener información del usuario:", error)
      }
    }
    fetchUserInfo()
  }, [customerSlug])

  // Cargar productos cuando se selecciona una categoría
  useEffect(() => {
    loadProducts()
  }, [loadProducts])

  const {
    isFormDialogOpen,
    isDeleteDialogOpen,
    selectedProduct,
    openCreateDialog,
    openEditDialog,
    openDeleteDialog,
    closeDialogs,
    handleSave,
    handleDelete,
    handleToggleStatus
  } = useProductActions(customerSlug, loadProducts)

  return (
    <div className="space-y-4 md:space-y-6 py-4 md:py-6 px-0 md:px-6">
      {/* Header con título y botón */}
      <ProductsHeader
        title="Gestión de Productos"
        description="Administra los productos de tu inventario"
        newButtonText="Agregar Producto"
        onNewClick={openCreateDialog}
        showButton={selectedCategory !== null}
        showBackButton={selectedCategory !== null}
        onBackClick={() => setSelectedCategory(null)}
      />

      {selectedCategory ? (
        /* Contenedor con filtros, tabla y paginación */
        <ProductsContainer 
          products={products} 
          categoryName={selectedCategoryName}
          showBranchColumn={showBranchColumn}
          isAdmin={isAdmin}
          branches={branches}
          selectedBranchId={selectedBranchId}
          onBranchChange={setSelectedBranchId}
          userBranchId={userBranchId}
          onEdit={openEditDialog}
          onToggleStatus={handleToggleStatus}
          onDelete={openDeleteDialog}
        />
      ) : (
        /* Vista de categorías con cards mejorados */
        <CategoryCards 
          categories={categories} 
          onCategorySelect={setSelectedCategory}
          customerSlug={customerSlug}
        />
      )}

      {/* Modal de crear/editar producto */}
      <ProductFormDialog
        open={isFormDialogOpen}
        onOpenChange={closeDialogs}
        product={selectedProduct}
        categories={categories}
        defaultCategoryId={selectedCategory || undefined}
        onSave={handleSave}
      />

      {/* Modal de confirmación de eliminar */}
      <ProductDeleteDialog
        open={isDeleteDialogOpen}
        onOpenChange={closeDialogs}
        product={selectedProduct}
        onDelete={handleDelete}
      />
    </div>
  )
}

"use client"

import { ChevronLeft, ChevronRight } from "lucide-react"

import { Button } from "@/components/ui/button"

interface ProductsPaginationProps {
  currentPage: number
  totalPages: number
  pageSize: number
  onPageChange: (page: number) => void
  onPageSizeChange: (size: number) => void
}

export function ProductsPagination({
  currentPage,
  totalPages,
  pageSize,
  onPageChange,
  onPageSizeChange
}: ProductsPaginationProps) {
  const handlePrevious = () => {
    if (currentPage > 1) {
      onPageChange(currentPage - 1)
    }
  }

  const handleNext = () => {
    if (currentPage < totalPages) {
      onPageChange(currentPage + 1)
    }
  }

  if (totalPages <= 1) return null

  return (
    <div className="flex items-center justify-center gap-4 py-4">
      <div className="text-sm text-gray-600 dark:text-gray-400">
        Página {currentPage} de {totalPages}
      </div>
      <div className="flex gap-2">
        <Button
          variant="outline"
          size="sm"
          onClick={handlePrevious}
          disabled={currentPage === 1}
          className="rounded-full"
        >
          <ChevronLeft className="h-4 w-4" />
          Anterior
        </Button>
        <Button
          variant="outline"
          size="sm"
          onClick={handleNext}
          disabled={currentPage === totalPages}
          className="rounded-full"
        >
          Siguiente
          <ChevronRight className="h-4 w-4" />
        </Button>
      </div>
    </div>
  )
}

"use client";

import { BrowserMultiFormatReader } from "@zxing/library";
import { Plus, Trash2, QrCode } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";

import { SalesQuotationWithRelations } from "./types";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

const paymentOptions = [
  { value: "cash", label: "Efectivo" },
  { value: "card", label: "Tarjeta" },
  { value: "transfer", label: "Transferencia" },
  { value: "qr", label: "QR / Billetera" },
];

interface ProductOption {
  id: string;
  name: string;
  price: number;
  stock: number;
}

interface LineItem {
  id: string;
  productId: string;
  productName: string;
  quantity: number;
  unitPrice: number;
  codes: string[];
}

const generateTempId = () =>
  typeof crypto !== "undefined" && crypto.randomUUID
    ? crypto.randomUUID()
    : Math.random().toString(36).slice(2);

const EMPTY_PRODUCT_VALUE = "__none__";

const formatDate = (value?: string | Date | null) => {
  if (!value) return "--";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "--";
  return date.toLocaleDateString("es-BO", {
    day: "2-digit",
    month: "long",
    year: "numeric",
  });
};

const formatCurrency = (value: unknown) =>
  Number(value ?? 0).toLocaleString("es-BO", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });

interface QuotationConvertDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  quotation?: SalesQuotationWithRelations;
  onConfirm: (payload: {
    paymentMethod: string;
    notes?: string | null;
    items: Array<{
      productId: string;
      productName?: string | null;
      quantity: number;
      unitPrice: number;
      subtotal: number;
    }>;
    discount: number;
  }) => void | Promise<void>;
  isSubmitting?: boolean;
  customerSlug: string;
  isAdmin?: boolean;
  selectedBranchId?: string | null;
  userBranchId?: string | null;
}

export function QuotationConvertDialog({
  open,
  onOpenChange,
  quotation,
  onConfirm,
  isSubmitting = false,
  customerSlug,
  isAdmin = false,
  selectedBranchId,
  userBranchId,
}: QuotationConvertDialogProps) {
  const [paymentMethod, setPaymentMethod] = useState<string>("cash");
  const [notes, setNotes] = useState<string>("");
  const [products, setProducts] = useState<ProductOption[]>([]);
  const [isLoadingProducts, setIsLoadingProducts] = useState(false);
  const [items, setItems] = useState<LineItem[]>([]);
  const [discountValue, setDiscountValue] = useState<number>(0);
  const [codeInputs, setCodeInputs] = useState<Record<string, string>>({});
  const [isScanning, setIsScanning] = useState(false);
  const [videoStream, setVideoStream] = useState<MediaStream | null>(null);
  const readerRef = useRef<BrowserMultiFormatReader | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const lastScannedCodeRef = useRef<string | null>(null);

  useEffect(() => {
    if (!open) return;
    setPaymentMethod("cash");
    setNotes(quotation?.notes ?? "");
    setDiscountValue(Number(quotation?.discount ?? 0));

    const initialItems: LineItem[] = (quotation?.items ?? []).map((item) => {
      const quantity = Number(item.quantity ?? 1) || 1;
      const unitPrice = Number(item.unitPrice ?? item.product?.price ?? 0);
      const initialProductId = item.productId ?? EMPTY_PRODUCT_VALUE;
      const rawTrackingCodes = (item as any)?.trackingCodes;
      return {
        id: generateTempId(),
        productId: initialProductId,
        productName: item.product?.name ?? item.productName ?? "",
        quantity,
        unitPrice,
        codes:
          initialProductId === EMPTY_PRODUCT_VALUE
            ? []
            : Array.isArray(rawTrackingCodes)
                ? (rawTrackingCodes as unknown[])
                    .filter((code): code is string => typeof code === "string")
                    .map((code) => code.trim())
                    .filter((code) => code.length > 0)
                : [],
      };
    });

    setItems(initialItems);
    const inputState: Record<string, string> = {};
    initialItems.forEach((item) => {
      inputState[item.id] = "";
    });
    setCodeInputs(inputState);
  }, [open, quotation]);

  const loadProducts = useCallback(
    async (branchId?: string | null) => {
      setIsLoadingProducts(true);
      try {
        const branchQuery = branchId ? `&branchId=${branchId}` : "";
        const response = await fetch(
          `/api/${customerSlug}/productos?page=1&pageSize=1000${branchQuery}`
        );
        if (!response.ok) return;
        const data = await response.json();
        const options: ProductOption[] = (data.products || []).map(
          (product: any) => ({
            id: product.id,
            name: product.name ?? "Producto sin nombre",
            price: Number(product.price ?? 0),
            stock: Number(product.stock ?? 0),
          })
        );
        setProducts(options);
      } catch (error) {
        console.error("Error al cargar productos:", error);
      } finally {
        setIsLoadingProducts(false);
      }
    },
    [customerSlug]
  );

  useEffect(() => {
    if (!open || products.length === 0) return;
    setItems((prev) =>
      prev.map((item) => {
        if (
          item.productId === EMPTY_PRODUCT_VALUE ||
          (item.productName && item.productName.length > 0)
        ) {
          return item;
        }
        const product = products.find((prod) => prod.id === item.productId);
        if (!product) return item;
        const unitPrice = item.unitPrice > 0 ? item.unitPrice : product.price;
        return {
          ...item,
          productName: product?.name ?? "",
          unitPrice,
          codes: product ? item.codes : [],
        };
      })
    );
  }, [open, products]);

  useEffect(() => {
    if (!open) return;

    const initialBranch = isAdmin
      ? selectedBranchId ?? null
      : userBranchId ?? null;

    loadProducts(initialBranch);

  }, [open, customerSlug, isAdmin, selectedBranchId, userBranchId, loadProducts]);

  useEffect(() => {
    if (!open || !isAdmin) return;
    const branchToLoad = selectedBranchId ?? null;
    loadProducts(branchToLoad);
  }, [open, isAdmin, selectedBranchId]);

  const subtotal = useMemo(
    () =>
      items.reduce((sum, item) => {
        if (item.productId === EMPTY_PRODUCT_VALUE) return sum;
        return sum + item.quantity * item.unitPrice;
      }, 0),
    [items]
  );

  const validItems = useMemo(
    () => items.filter((item) => item.productId !== EMPTY_PRODUCT_VALUE),
    [items]
  );

  const rawTotal = subtotal - discountValue;
  const total = rawTotal >= 0 ? rawTotal : 0;

  const hasMissingProducts = items.some(
    (item) => item.productId === EMPTY_PRODUCT_VALUE
  );
  const hasInvalidValues = items.some(
    (item) => item.quantity <= 0 || item.unitPrice < 0
  );
  const hasInvalidCodes = items.some(
    (item) => item.codes.length > 0 && item.codes.length !== item.quantity
  );
  const alreadyConverted = quotation?.status === "converted";
  const statusLabel = useMemo(() => {
    const raw = quotation?.status ?? "";
    if (raw === "converted") return "Vendida";
    if (raw === "active") return "Activa";
    if (raw === "expired") return "Vencida";
    return raw ? raw.charAt(0).toUpperCase() + raw.slice(1) : "";
  }, [quotation?.status]);

  const statusBadgeClass = useMemo(() => {
    switch (quotation?.status) {
      case "converted":
        return "bg-purple-600 text-white dark:bg-purple-400 dark:text-black";
      case "active":
        return "bg-emerald-500 text-white dark:bg-emerald-400 dark:text-black";
      case "expired":
        return "bg-red-500 text-white dark:bg-red-400 dark:text-black";
      default:
        return "bg-gray-900 text-white dark:bg-gray-100 dark:text-gray-900";
    }
  }, [quotation?.status]);

  const disableConfirm =
    isSubmitting ||
    alreadyConverted ||
    validItems.length === 0 ||
    hasMissingProducts ||
    hasInvalidValues ||
    hasInvalidCodes ||
    rawTotal < 0;

  const conversionWarning = useMemo(() => {
    if (alreadyConverted) return "Esta cotización ya fue convertida en venta.";
    if (validItems.length === 0)
      return "Agrega al menos un producto antes de convertir la cotización.";
    if (hasMissingProducts)
      return "Todos los productos deben estar asociados a un producto del catálogo para convertir la cotización.";
    if (hasInvalidValues)
      return "Verifica las cantidades y los precios de cada producto.";
    if (hasInvalidCodes)
      return "La cantidad de códigos debe coincidir con las unidades vendidas en cada producto.";
    if (rawTotal < 0)
      return "El total no puede ser negativo. Ajusta el descuento.";
    return null;
  }, [
    alreadyConverted,
    validItems.length,
    hasMissingProducts,
    hasInvalidValues,
    rawTotal,
  ]);

  const handleAddItem = useCallback(() => {
    const id = generateTempId();
    setItems((prev) => [
      ...prev,
      {
        id,
        productId: EMPTY_PRODUCT_VALUE,
        productName: "",
        quantity: 1,
        unitPrice: 0,
        codes: [],
      },
    ]);
    setCodeInputs((prev) => ({ ...prev, [id]: "" }));
  }, [products]);

  const handleRemoveItem = useCallback((itemId: string) => {
    setItems((prev) => prev.filter((item) => item.id !== itemId));
    setCodeInputs((prev) => {
      const clone = { ...prev };
      delete clone[itemId];
      return clone;
    });
  }, []);

  const handleProductChange = useCallback(
    (itemId: string, productId: string) => {
      const product = products.find((prod) => prod.id === productId);
      setItems((prev) =>
        prev.map((item) =>
          item.id === itemId
            ? {
                ...item,
                productId: product ? product.id : EMPTY_PRODUCT_VALUE,
                productName: product?.name ?? "",
                unitPrice: product?.price ?? 0,
                codes: product ? item.codes : [],
              }
            : item
        )
      );
      if (!product) {
        setCodeInputs((prev) => ({ ...prev, [itemId]: "" }));
      }
    },
    [products]
  );

  const handleQuantityChange = useCallback(
    (itemId: string, quantity: number) => {
      const normalized = Number.isFinite(quantity) ? quantity : 0;
      setItems((prev) =>
        prev.map((item) =>
          item.id === itemId
            ? { ...item, quantity: Math.max(0, normalized) }
            : item
        )
      );
    },
    []
  );

  const handleUnitPriceChange = useCallback(
    (itemId: string, unitPrice: number) => {
      const normalized = Number.isFinite(unitPrice) ? unitPrice : 0;
      setItems((prev) =>
        prev.map((item) =>
          item.id === itemId
            ? { ...item, unitPrice: Math.max(0, normalized) }
            : item
        )
      );
    },
    []
  );

  const stopScanning = useCallback(() => {
    readerRef.current?.reset();
    setIsScanning(false);
    if (videoStream) {
      videoStream.getTracks().forEach((track) => track.stop());
    }
    setVideoStream(null);
    lastScannedCodeRef.current = null;
  }, [readerRef, videoStream]);

  const addCodeToItem = useCallback((itemId: string, value: string) => {
    const code = value.trim();
    if (!code) return;
    setItems((prev) =>
      prev.map((item) => {
        if (item.id !== itemId) return item;
        if (item.codes.includes(code)) {
          toast.info("Este código ya fue agregado");
          return item;
        }
        if (item.codes.length >= item.quantity) {
          toast.error(
            "La cantidad de códigos no puede superar la cantidad vendida"
          );
          return item;
        }
        return {
          ...item,
          codes: [...item.codes, code],
        };
      })
    );
    setCodeInputs((prev) => ({ ...prev, [itemId]: "" }));
  }, []);

  const removeCodeFromItem = useCallback((itemId: string, code: string) => {
    setItems((prev) =>
      prev.map((item) =>
        item.id === itemId
          ? {
              ...item,
              codes: item.codes.filter((existing) => existing !== code),
            }
          : item
      )
    );
  }, []);

  const handleManualCodeAdd = useCallback(
    (itemId: string) => {
      const value = codeInputs[itemId] ?? "";
      addCodeToItem(itemId, value);
    },
    [addCodeToItem, codeInputs]
  );

  const canAddCodes = useCallback(
    (item: LineItem) =>
      item.productId !== EMPTY_PRODUCT_VALUE &&
      item.quantity > 0 &&
      item.codes.length < item.quantity,
    []
  );

  const startScanning = useCallback(
    async (itemId: string) => {
      const targetItem = items.find((item) => item.id === itemId);
      if (!targetItem || !canAddCodes(targetItem)) return;
      try {
        stopScanning();
        const reader = new BrowserMultiFormatReader();
        readerRef.current = reader;
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "environment" },
        });
        readerRef.current = reader;
        setIsScanning(true);
        setVideoStream(stream);
        await new Promise((resolve) => setTimeout(resolve, 100));
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute("playsinline", "true");
          videoRef.current.setAttribute("muted", "true");
          await videoRef.current.play();
        }
        lastScannedCodeRef.current = null;
        reader.decodeFromVideoDevice(
          null,
          videoRef.current as HTMLVideoElement,
          (result, err) => {
            if (result) {
              const code = result.getText();
              if (lastScannedCodeRef.current === code) return;
              lastScannedCodeRef.current = code;
              addCodeToItem(itemId, code);
              toast.success("Código escaneado");
              stopScanning();
            }
            if (err && !(err as any).closed) {
              // Silenciar errores de lectura
            }
          }
        );
      } catch (error) {
        console.error("Error al acceder a la cámara", error);
        toast.error("No se pudo acceder a la cámara");
        stopScanning();
      }
    },
    [
      addCodeToItem,
      canAddCodes,
      items,
      lastScannedCodeRef,
      readerRef,
      stopScanning,
    ]
  );

  useEffect(() => {
    if (!open) {
      stopScanning();
    }
  }, [open, stopScanning]);

  const handleDiscountChange = (value: number) => {
    if (!Number.isFinite(value) || value < 0) {
      setDiscountValue(0);
      return;
    }
    setDiscountValue(value);
  };

  const handleConfirm = () => {
    if (disableConfirm) return;
    const saleItems = validItems.map((item) => ({
      productId: item.productId,
      productName: item.productName,
      quantity: item.quantity,
      unitPrice: item.unitPrice,
      subtotal: item.quantity * item.unitPrice,
      trackingCodes: item.codes,
    }));

    if (saleItems.length === 0) return;

    void onConfirm({
      paymentMethod,
      notes: notes.trim().length > 0 ? notes.trim() : null,
      items: saleItems,
      discount: discountValue,
    });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-3xl max-h-[92vh] flex flex-col overflow-hidden p-0">
        <DialogHeader className="px-6 py-5 border-b border-gray-200 dark:border-gray-800 bg-white/95 dark:bg-[#111111]/95 backdrop-blur">
          <DialogTitle className="text-lg font-semibold text-gray-900 dark:text-white">
            Convertir cotización a venta
          </DialogTitle>
          <DialogDescription className="text-sm text-gray-600 dark:text-gray-400">
            Revisa los datos de la cotización y selecciona el método de pago
            para generar la venta.
          </DialogDescription>
        </DialogHeader>

        <div className="flex flex-col flex-1 min-h-0">
          <div className="flex-1 overflow-y-auto px-6 py-6 space-y-6 bg-gray-50/60 dark:bg-[#0c0c0c]">
            <div className="space-y-6">
              <div className="grid gap-4 md:grid-cols-3">
                <div className="rounded-2xl border border-gray-200 dark:border-[#2a2a2a] p-4 bg-gray-50 dark:bg-[#111]">
                  <div className="flex items-center justify-between">
                    <p className="text-xs uppercase text-gray-500 dark:text-gray-400">
                      Cotización
                    </p>
                    {statusLabel && (
                      <Badge
                        className={`rounded-full text-xs  ${statusBadgeClass}`}
                      >
                        {statusLabel}
                      </Badge>
                    )}
                  </div>
                  <p className="mt-2 text-base font-semibold text-gray-900 dark:text-white">
                    {quotation?.quotationNumber ?? "--"}
                  </p>
                  <div className="mt-3 space-y-1 text-xs text-gray-500 dark:text-gray-400">
                    <p>Emitida: {formatDate(quotation?.createdAt)}</p>
                    <p>Vence: {formatDate(quotation?.expiresAt)}</p>
                  </div>
                </div>
                <div className="rounded-2xl border border-gray-200 dark:border-[#2a2a2a] p-4 bg-gray-50 dark:bg-[#111]">
                  <p className="text-xs uppercase text-gray-500 dark:text-gray-400">
                    Cliente
                  </p>
                  <p className="mt-2 text-base font-semibold text-gray-900 dark:text-white">
                    {(() => {
                      if (!quotation) return "--";
                      const fullName = `${quotation.customer?.name ?? ""} ${
                        quotation.customer?.lastName ?? ""
                      }`.trim();
                      return (
                        fullName ||
                        quotation.customerName ||
                        "Cliente sin registrar"
                      );
                    })()}
                  </p>
                  <div className="mt-3 space-y-1 text-xs text-gray-500 dark:text-gray-400">
                    {quotation?.customerPhone && (
                      <p>Teléfono: {quotation.customerPhone}</p>
                    )}
                    {quotation?.customer?.email && (
                      <p>Correo: {quotation.customer.email}</p>
                    )}
                  </div>
                </div>
                <div className="rounded-2xl border border-gray-200 dark:border-[#2a2a2a] p-4 bg-gray-50 dark:bg-[#111]">
                  <p className="text-xs uppercase text-gray-500 dark:text-gray-400">
                    Sucursal
                  </p>
                  <p className="mt-2 text-base font-semibold text-gray-900 dark:text-white">
                    {quotation?.branch?.name ?? "Sin sucursal"}
                  </p>
                  {quotation?.branch?.address && (
                    <p className="mt-3 text-xs text-gray-500 dark:text-gray-400">
                      {quotation.branch.address}
                    </p>
                  )}
                </div>
              </div>

              <div className="space-y-3">
                {items.length > 0 ? (
                  <div className="space-y-3">
                    {items.map((item, index) => {
                      const subtotalItem = item.quantity * item.unitPrice;
                      return (
                        <div
                          key={item.id}
                          className="rounded-3xl border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#0d0d0d] p-4 space-y-3"
                        >
                          <div className="grid gap-3 md:grid-cols-[1.5fr_1fr_1fr_auto]">
                            <div className="space-y-2">
                              <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                                Producto {index + 1}
                              </Label>
                              <Select
                                value={
                                  item.productId === EMPTY_PRODUCT_VALUE
                                    ? EMPTY_PRODUCT_VALUE
                                    : item.productId
                                }
                                onValueChange={(value) =>
                                  handleProductChange(item.id, value)
                                }
                                disabled={isLoadingProducts}
                              >
                                <SelectTrigger className="rounded-2xl">
                                  <SelectValue
                                    placeholder={
                                      item.productName ||
                                      "Selecciona un producto"
                                    }
                                  />
                                </SelectTrigger>
                                <SelectContent className="rounded-2xl">
                                  <SelectItem value={EMPTY_PRODUCT_VALUE}>
                                    Selecciona un producto
                                  </SelectItem>
                                  {products.map((product) => (
                                    <SelectItem
                                      key={product.id}
                                      value={product.id}
                                    >
                                      {product.name}
                                    </SelectItem>
                                  ))}
                                </SelectContent>
                              </Select>
                            </div>
                            <div className="space-y-2">
                              <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                                Cantidad
                              </Label>
                              <Input
                                type="number"
                                min={1}
                                value={item.quantity}
                                onChange={(event) =>
                                  handleQuantityChange(
                                    item.id,
                                    Number(event.target.value)
                                  )
                                }
                                className={`rounded-2xl ${(() => {
                                  const product = products.find((prod) => prod.id === item.productId)
                                  return product && item.quantity > product.stock ? 'border border-red-500 text-red-600' : ''
                                })()}`}
                              />
                            </div>
                            <div className="space-y-2">
                              <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                                Precio U.
                              </Label>
                              <Input
                                type="number"
                                min={0}
                                step="0.01"
                                value={item.unitPrice}
                                onChange={(event) =>
                                  handleUnitPriceChange(
                                    item.id,
                                    Number(event.target.value)
                                  )
                                }
                                className="rounded-2xl"
                              />
                            </div>
                            <div className="space-y-2">
                              <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                                Subtotal
                              </Label>
                              <div className="flex items-center gap-3">
                                <Input
                                  type="text"
                                  readOnly
                                  value={formatCurrency(subtotalItem)}
                                  className="w-24 rounded-2xl bg-gray-100 dark:bg-[#1a1a1a] text-right font-semibold"
                                />
                                <Button
                                  type="button"
                                  variant="ghost"
                                  size="icon"
                                  className="rounded-full text-red-500 hover:bg-red-500/10"
                                  onClick={() => handleRemoveItem(item.id)}
                                  disabled={items.length === 1}
                                >
                                  <Trash2 className="h-4 w-4" />
                                </Button>
                              </div>
                            </div>
                          </div>

                          <div className="grid gap-3 md:grid-cols-[1.5fr_auto] md:items-end">
                            <div className="space-y-2">
                              <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                                Códigos únicos
                              </Label>
                              <Input
                                placeholder="Código de barras o serie"
                                value={codeInputs[item.id] ?? ""}
                                onChange={(event) =>
                                  setCodeInputs((prev) => ({
                                    ...prev,
                                    [item.id]: event.target.value,
                                  }))
                                }
                                className="rounded-2xl"
                                disabled={!canAddCodes(item)}
                              />
                            </div>
                            <div className="flex flex-wrap items-end gap-2">
                              <Button
                                type="button"
                                variant="outline"
                                className="rounded-full"
                                onClick={() => handleManualCodeAdd(item.id)}
                                disabled={!canAddCodes(item)}
                              >
                                Agregar
                              </Button>
                              <Button
                                type="button"
                                variant="outline"
                                className="rounded-full"
                                onClick={() => startScanning(item.id)}
                                disabled={!canAddCodes(item)}
                              >
                                <QrCode className="h-4 w-4" />
                                Escanear
                              </Button>
                            </div>
                          </div>

                          <div className="space-y-2">
                            {item.codes.length > 0 && (
                              <div className="flex flex-wrap gap-2">
                                {item.codes.map((code) => (
                                  <span
                                    key={`${item.id}-${code}`}
                                    className="inline-flex items-center gap-1 rounded-full border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#0d0d0d] px-3 py-1 text-xs text-gray-600 dark:text-gray-300"
                                  >
                                    #{code}
                                    <button
                                      type="button"
                                      onClick={() =>
                                        removeCodeFromItem(item.id, code)
                                      }
                                      className="ml-1 text-gray-500 hover:text-rose-500 dark:text-gray-400 dark:hover:text-rose-400"
                                    >
                                      <Trash2 className="h-3 w-3" />
                                    </button>
                                  </span>
                                ))}
                              </div>
                            )}
                            {item.codes.length === 0 && (
                              <p className="text-xs text-gray-500 dark:text-gray-400">
                                Sin códigos registrados.
                              </p>
                            )}
                            {item.codes.length > 0 &&
                              item.codes.length < item.quantity && (
                                <p className="text-xs text-amber-600 dark:text-amber-400">
                                  Faltan {item.quantity - item.codes.length}{" "}
                                  códigos para coincidir con la cantidad
                                  vendida.
                                </p>
                              )}
                            {item.codes.length >= item.quantity &&
                              item.quantity > 0 && (
                                <p className="text-xs text-emerald-600 dark:text-emerald-400">
                                  Códigos completos para este producto.
                                </p>
                              )}
                            {(() => {
                              const product = products.find((prod) => prod.id === item.productId)
                              if (product && item.quantity > product.stock) {
                                return (
                                  <p className="text-xs text-red-500">
                                    Stock disponible: {product.stock}
                                  </p>
                                )
                              }
                              if (product) {
                                return (
                                  <p className="text-xs text-gray-500 dark:text-gray-400">
                                    Stock disponible: {product.stock}
                                  </p>
                                )
                              }
                              return null
                            })()}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    No hay productos registrados. Agrega al menos uno para
                    continuar.
                  </p>
                )}
                <div className="flex justify-center">
                  <Button
                    type="button"
                    variant="outline"
                    className="rounded-full"
                    onClick={handleAddItem}
                    disabled={isLoadingProducts || products.length === 0}
                  >
                    <Plus className="h-4 w-4" />
                    Agregar producto
                  </Button>
                </div>
              </div>

              {!!quotation?.notes && (
                <div className="space-y-2">
                  <Label>Notas de la cotización</Label>
                  <div className="rounded-2xl border border-dashed border-gray-300 dark:border-[#2a2a2a] bg-gray-50 dark:bg-[#111] px-4 py-3 text-sm text-gray-700 dark:text-gray-300">
                    {quotation.notes}
                  </div>
                </div>
              )}
            </div>

            <div className="rounded-2xl border border-gray-200 dark:border-[#2a2a2a] bg-gray-50 dark:bg-[#111] p-5">
              <p className="text-xs uppercase text-gray-500 dark:text-gray-400">
                Resumen
              </p>
              <div className="mt-4 space-y-4">
                <div className="flex flex-col gap-3 md:flex-row md:items-end md:gap-4">
                  <div className="space-y-2 md:flex-1">
                    <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                      Subtotal
                    </Label>
                    <Input
                      type="text"
                      readOnly
                      value={formatCurrency(subtotal)}
                      className="w-full rounded-2xl bg-gray-100 dark:bg-[#1a1a1a] text-left font-semibold"
                    />
                  </div>
                  <div className="space-y-2 md:flex-1">
                    <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                      Descuento
                    </Label>
                    <Input
                      type="number"
                      min={0}
                      step="0.01"
                      value={discountValue}
                      onChange={(event) =>
                        handleDiscountChange(Number(event.target.value))
                      }
                      className="w-full rounded-2xl"
                    />
                  </div>
                  <div className="space-y-2 md:flex-1">
                    <Label
                      htmlFor="quotation-payment-method"
                      className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400"
                    >
                      Método de pago
                    </Label>
                    <Select
                      value={paymentMethod}
                      onValueChange={setPaymentMethod}
                      disabled={alreadyConverted}
                    >
                      <SelectTrigger
                        id="quotation-payment-method"
                        className="w-full rounded-2xl"
                      >
                        <SelectValue placeholder="Selecciona el método de pago" />
                      </SelectTrigger>
                      <SelectContent>
                        {paymentOptions.map((option) => (
                          <SelectItem key={option.value} value={option.value}>
                            {option.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>
                <div className="flex items-center justify-between rounded-xl bg-black dark:bg-white px-4 py-3 text-sm text-white dark:text-black">
                  <span>Total</span>
                  <span className="text-lg font-semibold">
                    {formatCurrency(total)}
                  </span>
                </div>
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="quotation-convert-notes">
                Notas para la venta
              </Label>
              <Textarea
                id="quotation-convert-notes"
                placeholder="Notas adicionales para la venta (opcional)"
                className="h-28 w-full rounded-2xl"
                value={notes}
                onChange={(event) => setNotes(event.target.value)}
                disabled={isSubmitting}
              />
            </div>

            {conversionWarning && (
              <div className="rounded-xl border border-amber-400/40 bg-amber-50/80 px-4 py-3 text-sm text-amber-800 dark:border-amber-500/40 dark:bg-amber-500/10 dark:text-amber-200">
                {conversionWarning}
              </div>
            )}
          </div>
        </div>

        <DialogFooter className="flex w-full flex-col sm:flex-row sm:items-center sm:justify-center gap-3 border-t border-gray-200 dark:border-[#2a2a2a] px-6 py-4 bg-white/95 dark:bg-[#111111]/95 backdrop-blur">
          <Button
            variant="outline"
            className="w-full sm:w-auto rounded-full border border-gray-200 bg-white text-gray-700 hover:bg-gray-100 dark:border-[#2a2a2a] dark:bg-[#1a1a1a] dark:text-gray-200 dark:hover:bg-[#222]"
            onClick={() => onOpenChange(false)}
            disabled={isSubmitting}
          >
            Cancelar
          </Button>
          <Button
            variant="new"
            className="rounded-full"
            onClick={handleConfirm}
            disabled={disableConfirm}
          >
            {isSubmitting ? "Convirtiendo..." : "Convertir a venta"}
          </Button>
        </DialogFooter>

        {isScanning && (
          <div className="fixed inset-0 z-[120] flex items-center justify-center">
            <div
              className="absolute inset-0 bg-black/70"
              onClick={stopScanning}
            />
            <div className="relative z-[121] flex flex-col items-center gap-4">
              <video
                ref={videoRef}
                className="w-72 h-72 rounded-3xl border-4 border-white object-cover shadow-2xl"
                autoPlay
                muted
                playsInline
              />
              <Button
                type="button"
                variant="secondary"
                className="rounded-full"
                onClick={stopScanning}
              >
                Detener escaneo
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client"

import jsPDF from "jspdf"
import { ExternalLink, FileDown, MessageCircle } from "lucide-react"
import { useCallback, useEffect, useMemo, useState } from "react"
import { toast } from "sonner"

import { SalesQuotationWithRelations } from "@/components/sales/quotation/types"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"

const formatDateTime = (date?: string | Date | null) => {
  if (!date) return "—"
  const d = new Date(date)
  return d.toLocaleString("es-BO", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  })
}

const statusTokens: Record<string, { label: string; className: string }> = {
  active: {
    label: "Activa",
    className: "bg-green-100 text-green-700 dark:bg-green-900/20 dark:text-green-400 border-green-200 dark:border-green-800",
  },
  expired: {
    label: "Vencida",
    className: "bg-red-100 text-red-700 dark:bg-red-900/20 dark:text-red-400 border-red-200 dark:border-red-800",
  },
  converted: {
    label: "Convertida",
    className: "bg-blue-100 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400 border-blue-200 dark:border-blue-800",
  },
  pending: {
    label: "Pendiente",
    className: "bg-yellow-100 text-yellow-700 dark:bg-yellow-900/20 dark:text-yellow-300 border-yellow-200 dark:border-yellow-800",
  },
  approved: {
    label: "Aprobada",
    className: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400 border-emerald-200 dark:border-emerald-800",
  },
  rejected: {
    label: "Rechazada",
    className: "bg-gray-200 text-gray-700 dark:bg-gray-900/20 dark:text-gray-400 border-gray-200 dark:border-gray-800",
  },
}

const DEFAULT_CURRENCY = "BOB"

interface QuotationDetailsDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  quotation?: SalesQuotationWithRelations
  customerSlug: string
}

export function QuotationDetailsDialog({ open, onOpenChange, quotation, customerSlug }: QuotationDetailsDialogProps) {
  const [isExporting, setIsExporting] = useState(false)
  const [shareUrl, setShareUrl] = useState<string | null>(null)
  const [companyWhatsappNumber, setCompanyWhatsappNumber] = useState<string>("")
  const [companyName, setCompanyName] = useState<string>("")
  const [companyContactName, setCompanyContactName] = useState<string>("")
  const [companyEmail, setCompanyEmail] = useState<string>("")
  const [companyPhone, setCompanyPhone] = useState<string>("")
  const [companyAddress, setCompanyAddress] = useState<string>("")
  const [companyWebsite, setCompanyWebsite] = useState<string>("")
  const [companyLogo, setCompanyLogo] = useState<string>("")
  const [currencyCode, setCurrencyCode] = useState<string>(DEFAULT_CURRENCY)
  const [showBranchInfo, setShowBranchInfo] = useState<boolean>(true)

  const statusToken = useMemo(() => {
    if (!quotation) return statusTokens["active"]
    return statusTokens[quotation.status] ?? { label: quotation.status, className: "bg-gray-100 text-gray-700" }
  }, [quotation])

  const formatCurrency = useCallback(
    (value: number) => `${currencyCode} ${Number(value || 0).toLocaleString("es-BO", { minimumFractionDigits: 2 })}`,
    [currencyCode]
  )

  const customerName = useMemo(() => {
    if (!quotation) return "—"
    if (quotation.customer) {
      const fullName = `${quotation.customer.name ?? ""} ${quotation.customer.lastName ?? ""}`.trim()
      return fullName || quotation.customer.email || quotation.customerName || "Cliente sin registrar"
    }
    return quotation.customerName || "Cliente sin registrar"
  }, [quotation])

  const customerPhone = useMemo(() => {
    if (!quotation) return ""
    const base = quotation.customer?.phone || quotation.customerPhone || ""
    const digits = base.replace(/[^0-9]/g, "")
    if (!digits) return ""
    const prefixed = base.startsWith("+") ? base : `+${digits}`
    return prefixed
  }, [quotation])

  const items = quotation?.items ?? []
  const subtotal = Number(quotation?.subtotal ?? 0)
  const discount = Number(quotation?.discount ?? 0)
  const total = Number(quotation?.total ?? 0)

  useEffect(() => {
    if (!open) {
      setShareUrl(null)
    }
  }, [open])

  useEffect(() => {
    setShareUrl(null)
  }, [quotation?.id])

  const handleOpenShareUrl = useCallback(() => {
    if (!shareUrl) return
    if (typeof window !== "undefined") {
      window.open(shareUrl, "_blank", "noopener,noreferrer")
    }
  }, [shareUrl])

  useEffect(() => {
    if (typeof document === "undefined") return
    try {
      const raw = document.cookie
        .split("; ")
        .find((chunk) => chunk.startsWith(`sas-prefs-${customerSlug}=`))
        ?.split("=")[1]
      if (!raw) {
        setCompanyWhatsappNumber("")
        setCompanyName("")
        setCompanyContactName("")
        setCompanyEmail("")
        setCompanyPhone("")
        setCompanyAddress("")
        setCompanyWebsite("")
        setCompanyLogo("")
        setCurrencyCode(DEFAULT_CURRENCY)
        setShowBranchInfo(true)
        return
      }
      const parsed = JSON.parse(decodeURIComponent(raw))
      const value = typeof parsed.whatsappNumber === "string" ? parsed.whatsappNumber : ""
      setCompanyWhatsappNumber(value)
      setCompanyName(typeof parsed.companyName === "string" ? parsed.companyName : "")
      setCompanyContactName(typeof parsed.companyContactName === "string" ? parsed.companyContactName : "")
      setCompanyEmail(typeof parsed.companyEmail === "string" ? parsed.companyEmail : "")
      setCompanyPhone(typeof parsed.companyPhone === "string" ? parsed.companyPhone : "")
      setCompanyAddress(typeof parsed.companyAddress === "string" ? parsed.companyAddress : "")
      setCompanyWebsite(typeof parsed.companyWebsite === "string" ? parsed.companyWebsite : "")
      setCompanyLogo(typeof parsed.companyLogo === "string" ? parsed.companyLogo : "")
      setCurrencyCode(typeof parsed.currency === "string" && parsed.currency.trim() ? parsed.currency : DEFAULT_CURRENCY)
      const branchCount = typeof parsed.branchCount === 'number' ? parsed.branchCount : undefined
      setShowBranchInfo(branchCount === undefined || branchCount > 1)
    } catch {
      setCompanyWhatsappNumber("")
      setCompanyName("")
      setCompanyContactName("")
      setCompanyEmail("")
      setCompanyPhone("")
      setCompanyAddress("")
      setCompanyWebsite("")
      setCompanyLogo("")
      setCurrencyCode(DEFAULT_CURRENCY)
      setShowBranchInfo(true)
    }
  }, [customerSlug, open])
 
  const fetchImageAsDataUrl = useCallback(async (url: string): Promise<string | null> => {
    if (!url) return null
    try {
      const response = await fetch(url)
      if (!response.ok) return null
      const blob = await response.blob()
      return await new Promise<string | null>((resolve, reject) => {
        const reader = new FileReader()
        reader.onload = () => resolve(reader.result as string)
        reader.onerror = () => reject(new Error('No se pudo cargar la imagen'))
        reader.readAsDataURL(blob)
      })
    } catch (error) {
      console.error('No se pudo cargar el logo para el PDF:', error)
      return null
    }
  }, [])

  const handleExportPdf = useCallback(async () => {
    if (!quotation) return

    if (shareUrl) {
      handleOpenShareUrl()
      toast.success("Abriendo PDF existente")
      return
    }

    try {
      setIsExporting(true)
      setShareUrl(null)

      const getPrimaryColor = (): { r: number; g: number; b: number } => {
        const fallback = { r: 26, g: 120, b: 102 }
        if (typeof window === 'undefined') return fallback

        try {
          const dummy = document.createElement('span')
          dummy.style.position = 'fixed'
          dummy.style.opacity = '0'
          dummy.style.pointerEvents = 'none'
          dummy.style.color = 'var(--primary)'
          document.body.appendChild(dummy)
          const resolved = getComputedStyle(dummy).color
          document.body.removeChild(dummy)

          const rgbMatch = resolved.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/i)
          if (rgbMatch) {
            return {
              r: Number(rgbMatch[1]),
              g: Number(rgbMatch[2]),
              b: Number(rgbMatch[3])
            }
          }
        } catch {}

        return fallback
      }

      const primaryColor = getPrimaryColor()
      const doc = new jsPDF({ unit: 'mm', format: 'a4' })
      const pageWidth = doc.internal.pageSize.getWidth()
      const pageHeight = doc.internal.pageSize.getHeight()
      const margin = 16

      let cursorY = margin + 6

      const logoDataUrl = companyLogo ? await fetchImageAsDataUrl(companyLogo) : null

      const headerTitleY = margin
      doc.setFont('helvetica', 'bold')
      doc.setFontSize(18)
      doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b)
      doc.text('Detalle Cotizacion', pageWidth / 2, headerTitleY, { align: 'center' })
 
      const maxLogoHeight = 32
      const logoX = pageWidth - margin - maxLogoHeight
      let contactBlockTop = headerTitleY + 8
      if (logoDataUrl) {
        doc.addImage(logoDataUrl, 'PNG', logoX, headerTitleY - 6, maxLogoHeight, maxLogoHeight, undefined, 'FAST')
        contactBlockTop = headerTitleY - 6 + maxLogoHeight + 6
      }

      const headerLeftX = margin
      let headerLeftY = headerTitleY + 8
      doc.setFont('helvetica', 'bold')
      doc.setFontSize(13)
      doc.setTextColor(30, 30, 30)
      doc.text(companyName || 'Nombre de la empresa', headerLeftX, headerLeftY)
      headerLeftY += 5

      doc.setFont('helvetica', 'normal')
      doc.setFontSize(10)
      doc.setTextColor(60, 60, 60)
      if (companyAddress) {
        doc.text(companyAddress, headerLeftX, headerLeftY)
        headerLeftY += 5
      }
      if (companyEmail) {
        doc.text(companyEmail, headerLeftX, headerLeftY)
        headerLeftY += 5
      }
      const formattedNow = formatDateTime(new Date())
      doc.setFont('helvetica', 'bold')
      doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b)
      doc.text('Fecha y Hora :', headerLeftX, headerLeftY)
      doc.setFont('helvetica', 'normal')
      doc.setTextColor(60, 60, 60)
      doc.text(formattedNow, headerLeftX + 30, headerLeftY)
      headerLeftY += 8

      const contactName = companyContactName || companyName || '—'
      const contactPhone = companyPhone || companyWhatsappNumber || '—'
      let contactY = contactBlockTop
      doc.setFont('helvetica', 'bold')
      doc.setFontSize(11)
      doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b)
      doc.text(contactName, logoX + maxLogoHeight, contactY, { align: 'right' })
      contactY += 6
      doc.setFont('helvetica', 'normal')
      doc.setFontSize(10)
      doc.setTextColor(60, 60, 60)
      doc.text(`Contactos: ${contactPhone}`, logoX + maxLogoHeight, contactY, { align: 'right' })
      contactY += 6

      const headerBottom = Math.max(headerLeftY, contactY, headerTitleY + maxLogoHeight) + 4
      doc.setDrawColor(primaryColor.r, primaryColor.g, primaryColor.b)
      doc.setLineWidth(0.6)
      doc.line(margin, headerBottom, pageWidth - margin, headerBottom)
      cursorY = headerBottom + 6

      const infoLeftX = margin
      const infoRightX = pageWidth / 2 + 6
      const infoLabelColor = primaryColor
      cursorY = headerBottom + 6
      const rightInfoYStart = cursorY
      let rightCursorY = rightInfoYStart
 
      const columnGap = 8
      const leftColumnX = margin
      const rightColumnX = pageWidth / 2 + columnGap / 2

      const customerDetails: Array<[string, string]> = [
        ['Cliente', customerName],
        ['Teléfono', customerPhone || '—'],
        ['Correo', quotation.customer?.email || '—'],
        ['Dirección', quotation.customer?.address || '—'],
        ['Detalle de Cotización', quotation.notes || '—'],
      ]

      const quotationDetails: Array<[string, string]> = [
        ['Código', quotation.quotationNumber],
        ['Emitida', formatDateTime(quotation.createdAt)],
        ['Válido hasta', formatDateTime(quotation.expiresAt)],
      ]
      if (showBranchInfo) {
        quotationDetails.push(['Sucursal', quotation.branch?.name || '—'])
      }

      const drawDetailsColumn = (x: number, title: string, rows: Array<[string, string]>) => {
        let y = cursorY
        doc.setFont('helvetica', 'bold')
        doc.setFontSize(11)
        doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b)
        doc.text(title.toUpperCase(), x, y)
        y += 6
        doc.setFont('helvetica', 'normal')
        doc.setFontSize(10)
        doc.setTextColor(45, 45, 45)

        rows.forEach(([label, value]: [string, string]) => {
          doc.text(`${label}:`, x, y)
          const isDetail = label === 'Detalle de Cotización'
          const valueX = isDetail ? x + 2 : x + 32
          const width = pageWidth / 2 - columnGap - (isDetail ? 8 : 38)
          let startY = isDetail ? y + 5 : y
          const lines = doc.splitTextToSize(value || '—', width) as string[]
          lines.forEach((line: string, idx: number) => {
            doc.text(line, valueX, startY + idx * 5)
          })
          y = Math.max(y + 6, startY + Math.max(lines.length * 5, 6))
        })

        return y
      }

      const leftEnd = drawDetailsColumn(leftColumnX, 'Datos del cliente', customerDetails)
      const rightEnd = drawDetailsColumn(rightColumnX, 'Datos de la cotización', quotationDetails)
      cursorY = Math.max(leftEnd, rightEnd) + 6

      const tableTop = cursorY + 4
      const tableWidth = pageWidth - margin * 2
      const colProduct = margin + 2
      const colPrice = margin + tableWidth * 0.55
      const colQty = margin + tableWidth * 0.74
      const colSubtotal = margin + tableWidth - 2

      doc.setFillColor(primaryColor.r, primaryColor.g, primaryColor.b)
      doc.setTextColor(255, 255, 255)
      doc.setFont('helvetica', 'bold')
      doc.roundedRect(margin, tableTop, tableWidth, 9, 3, 3, 'F')
      doc.text('Nombre', colProduct, tableTop + 6)
      doc.text(`Precio ${currencyCode}`, colPrice, tableTop + 6)
      doc.text('Cantidad (U)', colQty, tableTop + 6)
      doc.text('Subtotal', colSubtotal, tableTop + 6, { align: 'right' })

      let rowY = tableTop + 11
      doc.setFont('helvetica', 'normal')
      doc.setFontSize(10)
      doc.setTextColor(45, 45, 45)

      if (items.length === 0) {
        doc.text('No hay productos registrados en esta cotización.', margin + 4, rowY + 4)
        rowY += 14
      } else {
        items.forEach((item, index) => {
          const displayName = item.product?.name || item.productName || 'Producto sin nombre'
          const descriptionLines = doc.splitTextToSize(displayName, tableWidth * 0.52) as string[]
          const rowHeight = Math.max(descriptionLines.length * 5, 7) + 4

          if (rowY + rowHeight > pageHeight - 40) {
            doc.addPage()
            rowY = margin
            doc.setFont('helvetica', 'bold')
            doc.setFontSize(10)
            doc.setFillColor(primaryColor.r, primaryColor.g, primaryColor.b)
            doc.setTextColor(255, 255, 255)
            doc.roundedRect(margin, rowY, tableWidth, 9, 3, 3, 'F')
            doc.text('Nombre', colProduct, rowY + 6)
            doc.text(`Precio ${currencyCode}`, colPrice, rowY + 6)
            doc.text('Cantidad (U)', colQty, rowY + 6)
            doc.text('Subtotal', colSubtotal, rowY + 6, { align: 'right' })
            rowY += 11
            doc.setFont('helvetica', 'normal')
            doc.setFontSize(10)
            doc.setTextColor(45, 45, 45)
          }

          if (index % 2 === 0) {
            doc.setFillColor(248, 249, 252)
            doc.rect(margin, rowY - 3, tableWidth, rowHeight, 'F')
          }

          descriptionLines.forEach((line: string, idx: number) => {
            doc.text(line, colProduct, rowY + idx * 5)
          })
          doc.text(formatCurrency(item.unitPrice), colPrice, rowY)
          doc.text(String(item.quantity), colQty, rowY)
          doc.text(formatCurrency(item.subtotal), colSubtotal, rowY, { align: 'right' })

          rowY += rowHeight
        })
      }

      doc.setDrawColor(230, 230, 230)
      const dividerY = tableTop - 4
      doc.line(margin, dividerY, pageWidth - margin, dividerY)
      cursorY = rowY + 12

      const summaryRows: Array<[string, string]> = [
        ['SUB TOTAL', formatCurrency(subtotal)],
        ['DESCUENTO', formatCurrency(discount)],
        ['TOTAL', formatCurrency(total)],
      ]
 
      doc.setFont('helvetica', 'bold')
      doc.setFontSize(11)
      doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b)
      doc.text('Resumen de Totales', pageWidth - margin, cursorY, { align: 'right' })
      cursorY += 6
      doc.setFont('helvetica', 'normal')
      doc.setFontSize(10)
      doc.setTextColor(45, 45, 45)

      summaryRows.forEach(([label, value]) => {
        doc.text(label, pageWidth - margin - 70, cursorY)
        doc.text(value, pageWidth - margin, cursorY, { align: 'right' })
        cursorY += 6
      })
 
      const fileBaseName = quotation.id ? `cotizacion-${quotation.id}` : `cotizacion-${quotation.quotationNumber}`
      doc.save(`${fileBaseName}.pdf`)

      const dataUri = doc.output('datauristring')
      const base64 = dataUri.split(',')[1]

      if (base64) {
        try {
          const response = await fetch(`/api/${customerSlug}/cotizaciones/export`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              fileName: fileBaseName,
              pdfBase64: base64,
            }),
          })

          if (response.ok) {
            const payload = await response.json()
            const relativeUrl = payload?.url as string | undefined
            if (relativeUrl) {
              const absoluteUrl = relativeUrl.startsWith('http')
                ? relativeUrl
                : `${typeof window !== 'undefined' ? window.location.origin : ''}${relativeUrl}`
              setShareUrl(absoluteUrl)
              toast.success('PDF listo y enlace generado')
            } else {
              toast.success('PDF generado correctamente')
            }
          } else {
            const errorData = await response.json().catch(() => ({}))
            toast.error(errorData?.error || 'PDF descargado, pero no se pudo guardar el enlace')
          }
        } catch (uploadError) {
          console.error('Error subiendo PDF de cotización:', uploadError)
          toast.error('PDF descargado, pero no se pudo guardar el enlace')
        }
      }
    } catch (error) {
      console.error('Error al exportar la cotización:', error)
      toast.error('No se pudo generar el PDF')
    } finally {
      setIsExporting(false)
    }
  }, [
    quotation,
    shareUrl,
    handleOpenShareUrl,
    companyLogo,
    customerSlug,
    subtotal,
    discount,
    total,
    formatCurrency,
    fetchImageAsDataUrl,
    companyName,
    companyAddress,
    companyEmail,
    companyPhone,
    companyWebsite,
    companyWhatsappNumber,
    companyContactName,
    showBranchInfo,
  ])

  useEffect(() => {
    if (!open || !quotation || shareUrl || typeof window === "undefined") return
    const candidates = [
      quotation.id ? `/uploads/quotations/${customerSlug}/cotizacion-${quotation.id}.pdf` : null,
      quotation.quotationNumber ? `/uploads/quotations/${customerSlug}/cotizacion-${quotation.quotationNumber}.pdf` : null,
    ].filter(Boolean) as string[]

    const checkExisting = async () => {
      for (const relativeUrl of candidates) {
        try {
          const res = await fetch(relativeUrl, { method: 'HEAD' })
          if (res.ok) {
            const absolute = new URL(relativeUrl, window.location.origin).toString()
            setShareUrl(absolute)
            break
          }
        } catch {
          // ignore
        }
      }
    }

    checkExisting()
  }, [open, quotation, customerSlug, shareUrl])

  const sanitizedCompanyWhatsapp = useMemo(
    () => companyWhatsappNumber.replace(/[^0-9]/g, ""),
    [companyWhatsappNumber]
  )

  const customerWhatsapp = useMemo(() => {
    return customerPhone.replace(/[^0-9]/g, '')
  }, [customerPhone])
 
  const customerWhatsappLink = useMemo(() => {
    if (!shareUrl || !customerWhatsapp) return null
    const messageParts = [
      `Hola ${customerName || ""}, te comparto la cotización ${quotation?.quotationNumber ?? ""}.`,
      shareUrl,
    ]
    if (sanitizedCompanyWhatsapp) {
      messageParts.push(`Puedes responder a este número: +${sanitizedCompanyWhatsapp}`)
    }
    const message = encodeURIComponent(messageParts.filter(Boolean).join("\n"))
    return `https://wa.me/${customerWhatsapp}?text=${message}`
  }, [shareUrl, customerWhatsapp, sanitizedCompanyWhatsapp, quotation?.quotationNumber, customerName])

  const handleSendWhatsapp = useCallback(() => {
    if (!customerWhatsappLink) {
      if (!customerWhatsapp) {
        toast.error("Agrega un teléfono al cliente para enviar la cotización por WhatsApp")
      } else {
        toast.error("Configura un número de WhatsApp en Configuración")
      }
      return
    }
    if (typeof window !== "undefined") {
      window.open(customerWhatsappLink, "_blank", "noopener,noreferrer")
    }
  }, [customerWhatsapp, customerWhatsappLink])

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[700px] max-h-[90vh] flex flex-col overflow-hidden p-0">
        <div className="px-6 py-4 border-b border-gray-200 dark:border-[#2a2a2a] bg-white/90 dark:bg-[#111111]/90 backdrop-blur">
          <DialogHeader className="p-0">
            <DialogTitle>Detalles de la cotización</DialogTitle>
            <DialogDescription>
              Visualiza toda la información relacionada a la cotización seleccionada.
            </DialogDescription>
          </DialogHeader>
        </div>

        {quotation ? (
          <div className="flex-1 overflow-y-auto px-6 py-6 space-y-6">
            <div className="flex flex-col md:flex-row md:items-start md:justify-between gap-4">
              <div className="space-y-1">
                <p className="text-sm text-gray-500 dark:text-gray-400 uppercase">Número</p>
                <p className="text-xl font-semibold text-gray-900 dark:text-white">{quotation.quotationNumber}</p>
              </div>
              <Badge className={`${statusToken.className} rounded-full px-4 py-1.5 text-xs font-semibold self-start`}>{statusToken.label}</Badge>
            </div>

            <div className="grid gap-4 md:grid-cols-2">
              <div className="space-y-2 rounded-2xl border border-gray-200 dark:border-[#2a2a2a] bg-gray-50/70 dark:bg-[#151515] p-4">
                <p className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">Cliente</p>
                <p className="font-semibold text-gray-900 dark:text-white">{customerName}</p>
                {(quotation.customer?.email || quotation.customer?.ruc) && (
                  <div className="flex flex-col text-xs text-gray-500 dark:text-gray-400">
                    {quotation.customer?.email && <span>{quotation.customer.email}</span>}
                    {quotation.customer?.ruc && <span>CI: {quotation.customer.ruc}</span>}
                  </div>
                )}
                <div className="flex flex-col gap-1 text-xs text-gray-500 dark:text-gray-400">
                  {customerPhone && <span>Tel: {customerPhone}</span>}
                  {quotation.customer?.address && <span>Dir: {quotation.customer.address}</span>}
                </div>
              </div>
              <div className="grid gap-3 p-4 rounded-2xl border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#151515] text-sm text-gray-700 dark:text-gray-300">
                <div className="flex items-center justify-between">
                  <span>Creada:</span>
                  <span className="font-medium text-gray-900 dark:text-white">{formatDateTime(quotation.createdAt)}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span>Vencimiento:</span>
                  <span className="font-medium text-gray-900 dark:text-white">{formatDateTime(quotation.expiresAt)}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span>Actualizada:</span>
                  <span className="font-medium text-gray-900 dark:text-white">{formatDateTime(quotation.updatedAt)}</span>
                </div>
              </div>
            </div>

            {showBranchInfo && quotation.branch && (
              <div className="rounded-2xl border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#151515] p-4 text-sm text-gray-700 dark:text-gray-300">
                <p className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">Sucursal</p>
                <p className="font-semibold text-gray-900 dark:text-white">{quotation.branch.name ?? 'Sin sucursal'}</p>
                {quotation.branch.address ? (
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">{quotation.branch.address}</p>
                ) : (
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">Sin dirección registrada</p>
                )}
              </div>
            )}

            <div className="rounded-2xl border border-gray-200 dark:border-[#2a2a2a] overflow-hidden">
              <Table>
                <TableHeader>
                  <TableRow className="bg-gray-50 dark:bg-[#1f1f1f]">
                    <TableHead className="text-gray-700 dark:text-gray-300">Producto</TableHead>
                    <TableHead className="text-gray-700 dark:text-gray-300 w-[90px]">Cant.</TableHead>
                    <TableHead className="text-gray-700 dark:text-gray-300 w-[120px]">Precio</TableHead>
                    <TableHead className="text-gray-700 dark:text-gray-300 w-[120px] text-right">Subtotal</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {items.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={4} className="text-center py-6 text-gray-500 dark:text-gray-400">
                        No hay productos registrados en esta cotización.
                      </TableCell>
                    </TableRow>
                  ) : (
                    items.map((item) => {
                      const displayName = item.product?.name || item.productName || "Producto sin nombre"
                      return (
                        <TableRow key={item.id || item.productId || displayName}>
                          <TableCell>
                            <div className="flex flex-col">
                              <span className="font-medium text-gray-900 dark:text-white">{displayName}</span>
                              {item.productId && (
                                <span className="text-xs text-gray-500 dark:text-gray-400">ID: {item.productId}</span>
                              )}
                            </div>
                          </TableCell>
                          <TableCell>{item.quantity}</TableCell>
                          <TableCell>${Number(item.unitPrice).toLocaleString("es-BO", { minimumFractionDigits: 2 })}</TableCell>
                          <TableCell className="text-right font-semibold text-gray-900 dark:text-white">
                            ${Number(item.subtotal).toLocaleString("es-BO", { minimumFractionDigits: 2 })}
                          </TableCell>
                        </TableRow>
                      )
                    })
                  )}
                </TableBody>
              </Table>
            </div>

            <div className="grid gap-3 sm:grid-cols-3">
              <div className="space-y-1 rounded-2xl bg-gray-100 dark:bg-[#252525] px-4 py-3">
                <p className="text-xs uppercase text-gray-500 dark:text-gray-400">Subtotal</p>
                <p className="text-lg font-semibold text-gray-900 dark:text-white">
                  ${subtotal.toLocaleString("es-BO", { minimumFractionDigits: 2 })}
                </p>
              </div>
              <div className="space-y-1 rounded-2xl bg-gray-100 dark:bg-[#252525] px-4 py-3">
                <p className="text-xs uppercase text-gray-500 dark:text-gray-400">Descuento</p>
                <p className="text-lg font-semibold text-gray-900 dark:text-white">
                  ${discount.toLocaleString("es-BO", { minimumFractionDigits: 2 })}
                </p>
              </div>
              <div className="space-y-1 rounded-2xl bg-black text-white dark:bg-white dark:text-black px-4 py-3">
                <p className="text-xs uppercase text-white/70 dark:text-gray-600">Total</p>
                <p className="text-lg font-semibold">
                  ${total.toLocaleString("es-BO", { minimumFractionDigits: 2 })}
                </p>
              </div>
            </div>

            {quotation.notes && (
              <div className="space-y-2">
                <p className="text-xs uppercase text-gray-500 dark:text-gray-400">Notas</p>
                <p className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap bg-gray-50 dark:bg-[#151515] rounded-2xl border border-gray-200 dark:border-[#2a2a2a] px-4 py-3">
                  {quotation.notes}
                </p>
              </div>
            )}

            {shareUrl && (
              <div className="space-y-3 rounded-2xl border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#151515] p-4">
                <p className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">Enlace para compartir</p>
                <div className="flex flex-col gap-2 sm:flex-row sm:items-center">
                  <Input
                    value={shareUrl}
                    readOnly
                    className="rounded-full text-sm"
                    title={shareUrl}
                  />
                  <div className="flex gap-2">
                    <Button
                      type="button"
                      variant="new"
                      className="rounded-full"
                      onClick={handleSendWhatsapp}
                      disabled={!customerWhatsappLink}
                    >
                      <MessageCircle className="mr-2 h-4 w-4" /> Enviar WhatsApp
                    </Button>
                    <Button
                      type="button"
                      variant="ghost"
                      className="rounded-full"
                      onClick={handleOpenShareUrl}
                    >
                      <ExternalLink className="mr-2 h-4 w-4" /> Abrir
                    </Button>
                  </div>
                </div>
                {!customerWhatsappLink && (
                  <p className="text-xs text-amber-600 dark:text-amber-400">
                    Agrega un número de teléfono al cliente para habilitar el envío por WhatsApp.
                  </p>
                )}
                {customerWhatsappLink && !sanitizedCompanyWhatsapp && (
                  <p className="text-xs text-amber-600 dark:text-amber-400">
                    Tip: define el número de la empresa en Configuración para incluirlo en el mensaje.
                  </p>
                )}
              </div>
            )}
          </div>
        ) : (
          <p className="py-6 text-center text-sm text-gray-500 dark:text-gray-400">
            Selecciona una cotización para ver sus detalles.
          </p>
        )}

        <DialogFooter className="border-t border-gray-200 dark:border-[#2a2a2a] bg-white/90 dark:bg-[#111111]/90 backdrop-blur px-6 py-4 flex flex-col sm:flex-row items-center justify-center sm:justify-center gap-3 sm:space-x-3 sm:space-y-0 space-y-2">
          <Button
            variant="new"
            className="rounded-full"
            onClick={handleExportPdf}
            disabled={!quotation || isExporting}
          >
            <FileDown className="mr-2 h-4 w-4" />
            {shareUrl ? "Ver PDF" : isExporting ? "Generando..." : "Exportar PDF"}
          </Button>
          <Button variant="outline" className="rounded-full" onClick={() => onOpenChange(false)}>
            Cerrar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { SalesCustomer, SalesProduct } from "@prisma/client"
import { Check, ChevronsUpDown, ChevronDown, Package2, Plus, X } from "lucide-react"
import { useEffect, useMemo, useRef, useState } from "react"
import { toast } from "sonner"

import { SalesQuotationWithRelations } from "./types"

import { Button } from "@/components/ui/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"

const capitalizeWords = (value: string) =>
  value
    .toLowerCase()
    .replace(/\b\p{L}/gu, (char) => char.toUpperCase())

interface BranchOption {
  id: string
  name: string | null
}

interface QuotationFormDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  quotation?: SalesQuotationWithRelations | null
  organizationId: string
  customerSlug: string
  onSave: (data: any) => void
  isBusy?: boolean
  branches?: BranchOption[]
  isAdmin?: boolean
  currentUserBranchId?: string | null
}

interface QuotationItemRow {
  id: string
  productId: string
  productName: string
  productInput: string
  quantity: number
  unitPrice: number
  subtotal: number
}

const createEmptyItem = (): QuotationItemRow => ({
  id: `${Date.now()}-${Math.random()}`,
  productId: "none",
  productName: "",
  productInput: "",
  quantity: 1,
  unitPrice: 0,
  subtotal: 0,
})

const formatDateForInput = (value: string | Date): string => {
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return ""
  const tzOffset = date.getTimezoneOffset() * 60000
  const localISO = new Date(date.getTime() - tzOffset).toISOString()
  return localISO.split("T")[0]
}

const getTodayInputValue = () => formatDateForInput(new Date())

const toEndOfDayISO = (dateString: string): string => {
  const [year, month, day] = dateString.split("-").map(Number)
  const date = new Date(year, (month ?? 1) - 1, day ?? 1, 23, 59, 59, 999)
  return date.toISOString()
}

export function QuotationFormDialog({
  open,
  onOpenChange,
  quotation,
  organizationId: _organizationId,
  customerSlug,
  onSave,
  isBusy = false,
  branches = [],
  isAdmin = false,
  currentUserBranchId = null,
}: QuotationFormDialogProps) {
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null)
  const [customerInputValue, setCustomerInputValue] = useState("")
  const [customerPhoneInput, setCustomerPhoneInput] = useState("")
  const [isCustomerDropdownOpen, setIsCustomerDropdownOpen] = useState(false)
  const [highlightedCustomerIndex, setHighlightedCustomerIndex] = useState(0)
  const customerContainerRef = useRef<HTMLDivElement>(null)
  const customerInputRef = useRef<HTMLInputElement>(null)
  const PLACEHOLDER_BRANCH_VALUE = "__placeholder__"
  const [selectedBranchId, setSelectedBranchId] = useState<string>(PLACEHOLDER_BRANCH_VALUE)

  const [customers, setCustomers] = useState<(SalesCustomer & { lastName?: string | null })[]>([])
  const [products, setProducts] = useState<SalesProduct[]>([])
  const [items, setItems] = useState<QuotationItemRow[]>([])
  const [openProductPopoverId, setOpenProductPopoverId] = useState<string | null>(null)
  const quantityInputRefs = useRef<Map<string, HTMLInputElement>>(new Map())
  const [discount, setDiscount] = useState(0)
  const [expiresAt, setExpiresAt] = useState("")
  const [notes, setNotes] = useState("")
  const [isLoading, setIsLoading] = useState(false)
  const [isLoadingData, setIsLoadingData] = useState(false)
  const todayInputValue = useMemo(() => getTodayInputValue(), [])
  const branchOptions = useMemo<BranchOption[]>(() => {
    return (branches ?? []).map((branch) => ({
      id: branch.id,
      name: branch.name ?? "Sin sucursal",
    }))
  }, [branches])
  const normalizedSelectedBranchId =
    selectedBranchId === PLACEHOLDER_BRANCH_VALUE ? "" : selectedBranchId
  const renderCustomerInput = (wrapperClassName: string) => (
    <div className={cn("w-full", wrapperClassName)}>
      <Label htmlFor="customer" className="text-sm font-semibold text-gray-700 dark:text-gray-200 uppercase tracking-wide">Cliente</Label>
      <div className="relative mt-2">
        <input
          ref={customerInputRef}
          type="text"
          value={customerInputValue}
          onChange={(e) => {
            const formatted = e.target.value.length === 0 ? "" : capitalizeWords(e.target.value)
            setCustomerInputValue(formatted)
            setIsCustomerDropdownOpen(true)
            setHighlightedCustomerIndex(0)
            setSelectedCustomerId(null)
          }}
          onFocus={() => setIsCustomerDropdownOpen(true)}
          onKeyDown={handleCustomerKeyDown}
          onBlur={() => {
            // No cerrar inmediatamente para permitir clics en el dropdown
            setTimeout(() => setIsCustomerDropdownOpen(false), 200)
          }}
          placeholder="Escribe el nombre del cliente (puede no estar registrado)..."
          disabled={isFormLocked}
          className="w-full px-5 py-3 pr-20 border border-gray-200 dark:border-[#2a2a2a] rounded-2xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[color-mix(in_oklch,var(--primary)_50%,white)] bg-white dark:bg-[#161616] text-gray-900 dark:text-white shadow-sm"
        />
        <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-2">
          {customerInputValue && (
            <button
              onClick={clearCustomer}
              className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"
              type="button"
              disabled={isFormLocked}
            >
              <X size={16} className="text-gray-500" />
            </button>
          )}

          <button
            onClick={() => setIsCustomerDropdownOpen(!isCustomerDropdownOpen)}
            className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"
            type="button"
            disabled={isFormLocked}
          >
            <ChevronDown
              size={16}
              className={`text-gray-500 transition-transform ${isCustomerDropdownOpen ? 'rotate-180' : ''}`}
            />
          </button>
        </div>

        {isCustomerDropdownOpen && (
          <div className="absolute left-0 right-0 mt-2 z-20 bg-white dark:bg-[#161616] border border-gray-200 dark:border-[#2a2a2a] rounded-2xl shadow-xl overflow-hidden">
            <div className="max-h-64 overflow-y-auto">
              {filteredCustomers.length > 0 ? (
                filteredCustomers.map((customer, index) => (
                  <button
                    key={customer.id}
                    type="button"
                    onClick={() => selectCustomer(customer)}
                    onMouseEnter={() => setHighlightedCustomerIndex(index)}
                    className={`w-full text-left px-5 py-3 transition-colors ${index === highlightedCustomerIndex
                        ? 'bg-[color-mix(in_oklch,var(--primary)_18%,white)] text-gray-900 dark:bg-white/10 dark:text-white'
                        : 'text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-white/10'
                      }`}
                  >
                    <div className="font-semibold">{capitalizeWords(`${customer.name ?? ""} ${customer.lastName ?? ""}`.trim())}</div>
                    {customer.email && (
                      <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">{customer.email}</div>
                    )}
                  </button>
                ))
              ) : (
                <div className="px-5 py-6 text-center">
                  {customerInputValue.trim() ? (
                    <div className="space-y-2">
                      <p className="text-sm font-medium text-gray-900 dark:text-white">
                        Usar cliente: <span className="font-semibold">"{capitalizeWords(customerInputValue.trim())}"</span>
                      </p>
                      <p className="text-xs text-gray-500 dark:text-gray-400">
                        Presiona Enter o haz clic aquí para usar este cliente sin registrarlo
                      </p>
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        className="mt-2 rounded-full"
                        onClick={() => handleManualCustomer(customerInputValue.trim())}
                      >
                        Usar este cliente
                      </Button>
                    </div>
                  ) : (
                    <div className="space-y-2">
                      <p className="text-sm text-gray-500 dark:text-gray-400">No se encontraron clientes registrados</p>
                      <p className="text-xs text-gray-400 dark:text-gray-500">
                        Nombre del cliente para crearlo automáticamente en la cotización
                      </p>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  )

  const renderPhoneInput = (wrapperClassName: string) => (
    <div className={cn("w-full", wrapperClassName)}>
      <Label htmlFor="customerPhone" className="text-sm font-semibold text-gray-700 dark:text-gray-200 uppercase tracking-wide">Teléfono</Label>
      <div className="mt-2 relative">
        <Input
          id="customerPhone"
          type="tel"
          value={customerPhoneInput}
          onChange={(e) => setCustomerPhoneInput(e.target.value)}
          placeholder="Teléfono del cliente"
          disabled={isFormLocked}
          className="rounded-2xl"
        />
      </div>
    </div>
  )

  // Filtrar clientes basados en el input
  const filteredCustomers = useMemo(() => {
    if (!customerInputValue.trim()) return customers
    const search = customerInputValue.trim().toLowerCase()
    return customers.filter(customer => {
      const combined = `${customer.name ?? ""} ${customer.lastName ?? ""}`.trim().toLowerCase()
      return combined.includes(search)
    })
  }, [customers, customerInputValue])

  // Cerrar dropdown al hacer click fuera
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (customerContainerRef.current && !customerContainerRef.current.contains(event.target as Node)) {
        setIsCustomerDropdownOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  // Cargar clientes y productos
  useEffect(() => {
    if (open) {
      loadCustomers()
      const initialBranchId = isAdmin
        ? selectedBranchId
        : currentUserBranchId
      loadProducts(initialBranchId)
    }
  }, [open, customerSlug, isAdmin, selectedBranchId, currentUserBranchId])

  useEffect(() => {
    if (!open || !isAdmin) return
    loadProducts(selectedBranchId)
  }, [open, isAdmin, selectedBranchId])

  // Cargar datos de la cotización si existe
  useEffect(() => {
    if (quotation && open) {
      const initialName = quotation.customer?.name || quotation.customerName || ""
      setSelectedCustomerId(quotation.customerId ?? null)
      const combinedName = `${quotation.customer?.name ?? ""} ${(quotation.customer as any)?.lastName ?? ""}`.trim()
      setCustomerInputValue(capitalizeWords(combinedName || initialName))
      const phoneValue = (quotation.customer?.phone as string | undefined) ?? (quotation as any)?.customerPhone ?? ""
      setCustomerPhoneInput(phoneValue ?? "")
      const branchIdFromQuotation =
        (quotation as any)?.branchId ??
        quotation.branchId ??
        quotation.branch?.id ??
        null
      setSelectedBranchId(branchIdFromQuotation ?? currentUserBranchId ?? PLACEHOLDER_BRANCH_VALUE)
      setDiscount(Number(quotation.discount) || 0)
      if (quotation.expiresAt) {
        const formatted = formatDateForInput(quotation.expiresAt)
        setExpiresAt(formatted < todayInputValue ? todayInputValue : formatted)
      } else {
        setExpiresAt("")
      }
      setNotes(quotation.notes || "")
      if (quotation.items) {
        const mapped = quotation.items.map((item: any) => {
          const baseName = item.product?.name || item.productName || ""
          const formattedName = baseName ? capitalizeWords(baseName) : ""
          return {
            id: item.id || `${item.productId ?? 'manual'}-${Math.random()}`,
            productId: item.productId ?? "none",
            productName: formattedName,
            productInput: formattedName,
            quantity: Number(item.quantity || 1),
            unitPrice: Number(item.unitPrice || 0),
            subtotal: Number(item.subtotal || 0),
          }
        })
        setItems(mapped.length > 0 ? mapped : [createEmptyItem()])
      }
    } else if (!quotation && open) {
      setSelectedCustomerId(null)
      setCustomerInputValue("")
      setCustomerPhoneInput("")
      if (isAdmin) {
        setSelectedBranchId(currentUserBranchId ?? PLACEHOLDER_BRANCH_VALUE)
      } else {
        setSelectedBranchId(currentUserBranchId ?? PLACEHOLDER_BRANCH_VALUE)
      }
      setDiscount(0)
      setExpiresAt("")
      setNotes("")
      setItems([createEmptyItem()])
    }
  }, [branchOptions, currentUserBranchId, isAdmin, open, quotation])

  const loadCustomers = async () => {
    try {
      setIsLoadingData(true)
      const response = await fetch(`/api/${customerSlug}/clientes?page=1&pageSize=1000`, {
        cache: "no-store",
      })
      if (response.ok) {
        const data = await response.json()
        const normalized = (data.customers || []).map((customer: any) => ({
          ...customer,
          lastName: customer.lastName ?? customer.apellido ?? null,
        }))
        setCustomers(normalized)
      }
    } catch (error) {
      console.error('Error al cargar clientes:', error)
    } finally {
      setIsLoadingData(false)
    }
  }

  const loadProducts = async (branchIdOverride?: string | null) => {
    try {
      setIsLoadingData(true)
      const effectiveBranchId = isAdmin
        ? branchIdOverride && branchIdOverride !== PLACEHOLDER_BRANCH_VALUE
          ? branchIdOverride
          : null
        : currentUserBranchId ?? null

      const branchQuery = effectiveBranchId ? `&branchId=${effectiveBranchId}` : ""

      const response = await fetch(`/api/${customerSlug}/productos?page=1&pageSize=1000${branchQuery}`, {
        cache: "no-store",
      })
      if (response.ok) {
        const data = await response.json()
        setProducts(data.products || [])
      }
    } catch (error) {
      console.error('Error al cargar productos:', error)
    } finally {
      setIsLoadingData(false)
    }
  }

  const handleCustomerKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!isCustomerDropdownOpen && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
      setIsCustomerDropdownOpen(true)
      return
    }

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightedCustomerIndex(prev =>
          prev < filteredCustomers.length - 1 ? prev + 1 : prev
        )
        break
      case 'ArrowUp':
        e.preventDefault()
        setHighlightedCustomerIndex(prev => prev > 0 ? prev - 1 : prev)
        break
      case 'Enter':
        e.preventDefault()
        const trimmed = customerInputValue.trim()
        if (isCustomerDropdownOpen && filteredCustomers[highlightedCustomerIndex]) {
          selectCustomer(filteredCustomers[highlightedCustomerIndex])
        } else if (trimmed.length > 0) {
          handleManualCustomer(trimmed)
        } else {
          setIsCustomerDropdownOpen(false)
        }
        break
      case 'Escape':
        setIsCustomerDropdownOpen(false)
        break
    }
  }

  const selectCustomer = (customer: SalesCustomer & { lastName?: string | null }) => {
    setSelectedCustomerId(customer.id)
    const fullName = `${customer.name ?? ""} ${customer.lastName ?? ""}`.trim()
    setCustomerInputValue(capitalizeWords(fullName))
    setIsCustomerDropdownOpen(false)
    setHighlightedCustomerIndex(0)
    setCustomerPhoneInput(customer.phone ?? "")
  }

  const clearCustomer = () => {
    setSelectedCustomerId(null)
    setCustomerInputValue("")
    customerInputRef.current?.focus()
    setHighlightedCustomerIndex(0)
    setCustomerPhoneInput("")
  }

  const handleManualCustomer = (value: string) => {
    const trimmed = value.trim()
    if (trimmed.length === 0) return
    setSelectedCustomerId(null)
    const formatted = capitalizeWords(trimmed)
    setCustomerInputValue(formatted)
    setIsCustomerDropdownOpen(false)
    setHighlightedCustomerIndex(0)
    setCustomerPhoneInput("")
  }

  const addItem = () => {
    setItems((prev) => [...prev, createEmptyItem()])
  }

  const removeItem = (id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id))
  }

  const normalizeNumber = (value: string | number, fallback = 0) => {
    if (typeof value === "number" && !Number.isNaN(value)) return value
    const parsed = parseFloat(value as string)
    return Number.isNaN(parsed) ? fallback : parsed
  }

  const updateItem = (id: string, field: keyof QuotationItemRow, rawValue: any) => {
    setItems((prev) => {
      return prev.map((item) => {
        if (item.id !== id) return item

        const updated: QuotationItemRow = { ...item }

        if (field === "productId") {
          if (rawValue === "none") {
            updated.productId = "none"
            return updated
          }
          const product = products.find((p) => p.id === rawValue)
          updated.productId = rawValue
          if (product) {
            const unitPrice = Number(product.price || 0)
            const formattedName = capitalizeWords(product.name || "")
            updated.productName = formattedName
            updated.productInput = formattedName
            updated.unitPrice = unitPrice
            updated.subtotal = unitPrice * updated.quantity
          }
        } else if (field === "quantity") {
          const quantity = Math.max(1, Math.floor(normalizeNumber(rawValue, 1)))
          updated.quantity = quantity
          updated.subtotal = quantity * updated.unitPrice
        } else if (field === "unitPrice") {
          const unitPrice = Math.max(0, normalizeNumber(rawValue, 0))
          updated.unitPrice = unitPrice
          updated.subtotal = unitPrice * updated.quantity
        }

        return updated
      })
    })
  }

  const handleProductPopoverChange = (id: string, open: boolean) => {
    if (open) {
      setOpenProductPopoverId(id)
      setItems((prev) =>
        prev.map((item) =>
          item.id === id
            ? {
              ...item,
              productInput: item.productName,
            }
            : item,
        ),
      )
    } else {
      setOpenProductPopoverId((prev) => (prev === id ? null : prev))
    }
  }

  const focusQuantityInput = (itemId: string) => {
    requestAnimationFrame(() => {
      const quantityInput = quantityInputRefs.current.get(itemId)
      if (quantityInput) {
        quantityInput.focus()
        quantityInput.select()
      }
    })
  }

  const handleProductInputChange = (id: string, value: string) => {
    const formatted = value.length === 0 ? "" : capitalizeWords(value)
    setItems((prev) =>
      prev.map((item) =>
        item.id === id
          ? {
            ...item,
            productId: "none",
            productInput: formatted,
            productName: formatted,
          }
          : item,
      ),
    )
  }

  const handleProductInputKeyDown = (itemId: string, event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter") {
      event.preventDefault()
      const current = items.find((item) => item.id === itemId)
      const trimmed = current?.productInput.trim() ?? ""

      if (trimmed.length === 0) {
        setOpenProductPopoverId(null)
        return
      }

      const matchingProduct = products.find(
        (product) => product.name?.toLowerCase() === trimmed.toLowerCase(),
      )

      if (matchingProduct) {
        handleProductSelect(itemId, matchingProduct)
      } else {
        handleProductManualSelection(itemId, trimmed)
      }
    } else if (event.key === "Escape") {
      setOpenProductPopoverId(null)
    }
  }

  const handleProductSelect = (itemId: string, product: SalesProduct) => {
    const formattedName = capitalizeWords(product.name || "")
    setItems((prev) =>
      prev.map((item) =>
        item.id === itemId
          ? {
            ...item,
            productId: product.id,
            productName: formattedName,
            productInput: formattedName,
            unitPrice: Number(product.price || 0),
            subtotal: Number(product.price || 0) * item.quantity,
          }
          : item,
      ),
    )
    setOpenProductPopoverId(null)
    focusQuantityInput(itemId)
  }

  const handleProductManualSelection = (itemId: string, value: string) => {
    const trimmed = value.trim()
    if (trimmed.length === 0) {
      setOpenProductPopoverId(null)
      return
    }
    const formatted = capitalizeWords(trimmed)
    setItems((prev) =>
      prev.map((item) =>
        item.id === itemId
          ? {
            ...item,
            productId: "none",
            productName: formatted,
            productInput: formatted,
          }
          : item,
      ),
    )
    setOpenProductPopoverId(null)
    focusQuantityInput(itemId)
  }

  const totals = useMemo(() => {
    const subtotal = items.reduce((sum, item) => sum + Number(item.subtotal || 0), 0)
    const total = Math.max(0, subtotal - Number(discount || 0))
    return { subtotal, total }
  }, [items, discount])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    const trimmedCustomerName = customerInputValue.trim()

    if (!selectedCustomerId && trimmedCustomerName.length === 0) {
      toast.error("Debe ingresar el nombre del cliente")
      return
    }

    const branchIdForSubmit = isAdmin
      ? (normalizedSelectedBranchId || null)
      : currentUserBranchId ?? (normalizedSelectedBranchId || null)

    const preparedItems = items
      .filter((item) => (item.productId !== "none") || item.productName.trim().length > 0)
      .map(({ productId, productName, quantity, unitPrice, subtotal }) => ({
        productId: productId !== "none" ? productId : null,
        productName: productName.trim().length > 0 ? capitalizeWords(productName.trim()) : undefined,
        quantity,
        unitPrice,
        subtotal,
      }))

    if (preparedItems.length === 0) {
      toast.error("Debe agregar al menos un producto")
      return
    }

    setIsLoading(true)
    try {
      const expiresAtIso = expiresAt ? toEndOfDayISO(expiresAt) : undefined
      const normalizedCustomerPhone = customerPhoneInput.trim() || undefined

      await onSave({
        customerId: selectedCustomerId,
        customerName: selectedCustomerId ? undefined : trimmedCustomerName,
        customerPhone: normalizedCustomerPhone,
        branchId: branchIdForSubmit,
        subtotal: totals.subtotal,
        discount,
        total: totals.total,
        expiresAt: expiresAtIso,
        notes,
        items: preparedItems
      })
    } finally {
      setIsLoading(false)
    }
  }

  const hasValidItems = items.some((item) => (item.productId !== "none") || item.productName.trim().length > 0)
  const isBranchInvalid =
    isAdmin && (!normalizedSelectedBranchId || normalizedSelectedBranchId.trim().length === 0)
  const isSubmitDisabled =
    customerInputValue.trim().length === 0 ||
    !hasValidItems ||
    isBranchInvalid ||
    isLoading ||
    isLoadingData ||
    isBusy
  const isFormLocked = isLoading || isLoadingData || isBusy

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[900px] max-h-[92vh] flex flex-col overflow-hidden p-0">
        <div className="px-6 py-5 border-b border-gray-200 dark:border-[#2a2a2a] bg-white/95 dark:bg-[#111111]/95 backdrop-blur">
          <DialogHeader className="px-0 py-0 space-y-2">
            <DialogTitle>
              {quotation ? "Editar Cotización" : "Nueva Cotización"}
            </DialogTitle>
            <DialogDescription>
              {quotation
                ? "Modifica los datos de la cotización"
                : "Completa los datos para crear una nueva cotización"}
            </DialogDescription>
          </DialogHeader>
        </div>
        <form onSubmit={handleSubmit} className="flex flex-col flex-1 min-h-0">
          <div className="flex-1 overflow-y-auto px-6 py-6 space-y-8 bg-gray-50/60 dark:bg-[#0c0c0c]">
            <div className="space-y-6">
              {/* Cliente con ComboBox */}
              <div className="space-y-5" ref={customerContainerRef}>
                {isAdmin ? (
                  <>
                    {renderCustomerInput("")}
                    <div className="flex flex-col md:flex-row md:items-end md:gap-4 gap-4">
                      <div className="md:flex-1">
                        <Label htmlFor="quotation-branch" className="text-sm font-semibold text-gray-700 dark:text-gray-200 uppercase tracking-wide">
                          Sucursal
                        </Label>
                        <Select
                          value={selectedBranchId}
                          onValueChange={(value) => {
                            setSelectedBranchId(value)
                          }}
                          disabled={isFormLocked}
                        >
                          <SelectTrigger id="quotation-branch" className="mt-2 w-full rounded-2xl">
                            <SelectValue placeholder="Selecciona una sucursal" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value={PLACEHOLDER_BRANCH_VALUE}>Selecciona una sucursal</SelectItem>
                            {branchOptions.map((branch) => (
                              <SelectItem key={branch.id} value={branch.id}>
                                {branch.name ?? "Sin sucursal"}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                      {renderPhoneInput("md:flex-1")}
                    </div>
                  </>
                ) : (
                  <div className="flex flex-col md:flex-row md:items-end md:gap-4 gap-4">
                    {renderCustomerInput("md:flex-1")}
                    {renderPhoneInput("md:w-[320px]")}
                  </div>
                )}
              </div>
              {/* Items */}
              <div className="space-y-4">
                <Label className="text-sm font-semibold text-gray-700 dark:text-gray-200 uppercase tracking-wide">Productos</Label>

                {items.length === 0 ? (
                  <div className="flex flex-col items-center justify-center gap-3 py-12 text-gray-500 dark:text-gray-400 border-2 border-dashed border-gray-300 dark:border-[#2a2a2a] rounded-3xl">
                    <Package2 className="h-10 w-10" />
                    <p className="text-sm">No hay productos agregados</p>
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      className="rounded-full"
                      onClick={addItem}
                      disabled={isFormLocked}
                    >
                      <Plus className="h-4 w-4 mr-1" /> Agregar Producto
                    </Button>
                  </div>
                ) : (
                  <div className="space-y-3">
                    {items.map((item) => {
                      const productTriggerId = `quotation-product-${item.id}`
                      const quantityInputId = `quotation-quantity-${item.id}`
                      const priceInputId = `quotation-price-${item.id}`

                      return (
                        <div
                          key={item.id}
                          className="grid gap-2 lg:gap-4 lg:grid-cols-[minmax(0,1.2fr)_repeat(3,minmax(0,0.7fr))_auto] items-start border border-gray-200 dark:border-[#2f2f2f] rounded-2xl bg-white dark:bg-[#181818] px-4 py-4 shadow-sm"
                        >
                          <div className="space-y-1">
                            <Label className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">Producto</Label>
                            <Popover
                              open={openProductPopoverId === item.id}
                              onOpenChange={(open) => handleProductPopoverChange(item.id, open)}
                            >
                              <PopoverTrigger asChild>
                                <Button
                                  id={productTriggerId}
                                  variant="outline"
                                  role="combobox"
                                  className="w-full justify-between rounded-xl text-left h-[44px] border border-gray-200 dark:border-[#2f2f2f] bg-white dark:bg-[#1f1f1f]"
                                  disabled={isFormLocked}
                                  aria-haspopup="listbox"
                                  aria-expanded={openProductPopoverId === item.id}
                                >
                                  <span className="truncate text-gray-900 dark:text-white">
                                    {item.productName.trim().length > 0
                                      ? capitalizeWords(item.productName)
                                      : "Seleccionar o escribir producto"}
                                  </span>
                                  <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                                </Button>
                              </PopoverTrigger>
                              <PopoverContent className="w-full p-0" align="start" sideOffset={6}>
                                <Command>
                                  <CommandInput
                                    placeholder="Buscar o escribir producto..."
                                    value={item.productInput}
                                    onValueChange={(value) => handleProductInputChange(item.id, value)}
                                    onKeyDown={(event) => handleProductInputKeyDown(item.id, event)}
                                    autoFocus
                                  />
                                  <CommandList>
                                    <CommandEmpty>
                                      {item.productInput.trim().length > 0
                                        ? `Presiona Enter para usar "${capitalizeWords(item.productInput.trim())}"`
                                        : "No se encontraron productos"}
                                    </CommandEmpty>
                                    <CommandGroup>
                                      {products
                                        .filter((product) => {
                                          const isAlreadySelected = items.some(
                                            (otherItem) =>
                                              otherItem.id !== item.id && otherItem.productId === product.id,
                                          )

                                          if (isAlreadySelected) {
                                            return false
                                          }

                                          if (item.productInput.trim().length === 0) {
                                            return true
                                          }

                                          return product.name
                                            ?.toLowerCase()
                                            .includes(item.productInput.toLowerCase())
                                        })
                                        .map((product) => (
                                          <CommandItem
                                            key={product.id}
                                            value={product.name || ""}
                                            onSelect={() => handleProductSelect(item.id, product)}
                                          >
                                            <Check
                                              className={cn(
                                                "mr-2 h-4 w-4",
                                                item.productId === product.id ? "opacity-100" : "opacity-0",
                                              )}
                                            />
                                            <span className="truncate">
                                              {product.name} · ${Number(product.price).toFixed(2)}
                                            </span>
                                          </CommandItem>
                                        ))}
                                    </CommandGroup>
                                  </CommandList>
                                </Command>
                              </PopoverContent>
                            </Popover>
                          </div>

                          <div className="space-y-1">
                            <Label htmlFor={quantityInputId} className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">
                              Cantidad
                            </Label>
                            <Input
                              id={quantityInputId}
                              type="number"
                              placeholder="Cant."
                              value={item.quantity}
                              onChange={(e) => updateItem(item.id, "quantity", e.target.value)}
                              ref={(element) => {
                                const map = quantityInputRefs.current
                                if (element) {
                                  map.set(item.id, element)
                                } else {
                                  map.delete(item.id)
                                }
                              }}
                              className="rounded-xl h-11"
                              min="1"
                              disabled={isFormLocked}
                            />
                          </div>

                          <div className="space-y-1">
                            <Label htmlFor={priceInputId} className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">
                              Precio
                            </Label>
                            <Input
                              id={priceInputId}
                              type="number"
                              placeholder="Precio"
                              value={item.unitPrice}
                              onChange={(e) => updateItem(item.id, "unitPrice", e.target.value)}
                              className="rounded-xl h-11"
                              step="0.01"
                              min="0"
                              disabled={isFormLocked}
                            />
                          </div>

                          <div className="space-y-1">
                            <Label className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">
                              Subtotal
                            </Label>
                            <div className="flex items-center justify-center rounded-xl bg-gray-100 dark:bg-[#242424] px-4 py-2 h-11">
                              <span className="font-semibold text-gray-900 dark:text-white">${item.subtotal.toFixed(2)}</span>
                            </div>
                          </div>

                          <div className="flex items-end justify-end">
                            <Button
                              type="button"
                              variant="ghost"
                              size="icon"
                              className="rounded-full h-10 w-10 text-red-500 hover:bg-red-100 dark:hover:bg-red-900/20"
                              onClick={() => removeItem(item.id)}
                              disabled={isFormLocked || items.length === 1}
                              aria-label="Eliminar producto"
                            >
                              <X className="h-4 w-4" />
                            </Button>
                          </div>
                        </div>
                      )
                    })}
                    <div className="flex justify-center pt-3">
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        className="rounded-full"
                        onClick={addItem}
                        disabled={isFormLocked}
                      >
                        <Plus className="h-4 w-4 mr-1" /> Agregar Producto
                      </Button>
                    </div>
                  </div>
                )}
              </div>
              {/* Totales y extras */}
              <div className="space-y-6">
                <div className="grid gap-4 lg:grid-cols-2">
                  <div className="space-y-2">
                    <Label className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">Subtotal</Label>
                    <Input
                      type="text"
                      value={`$${totals.subtotal.toFixed(2)}`}
                      readOnly
                      className="rounded-2xl font-semibold text-right bg-[color-mix(in_oklch,var(--primary)_8%,white)] dark:bg-[color-mix(in_oklch,var(--primary)_18%,black)] text-gray-900 dark:text-white border border-transparent"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="discount" className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">Descuento</Label>
                    <Input
                      id="discount"
                      type="number"
                      value={discount}
                      onChange={(e) => setDiscount(normalizeNumber(e.target.value, 0))}
                      onFocus={(e) => {
                        if (e.target.value === "0" || e.target.value === "0.0" || e.target.value === "0.00") {
                          setDiscount(0)
                          e.target.value = ""
                        } else {
                          e.target.select()
                        }
                      }}
                      className="rounded-2xl"
                      step="0.01"
                      min="0"
                      disabled={isFormLocked}
                    />
                  </div>
                </div>

                <div className="grid gap-4 lg:grid-cols-2">
                  <div className="space-y-2">
                    <Label htmlFor="expiresAt" className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">Fecha de Expiración</Label>
                    <Input
                      id="expiresAt"
                      type="date"
                      value={expiresAt}
                      min={todayInputValue}
                      onChange={(e) => {
                        const value = e.target.value
                        if (!value) {
                          setExpiresAt("")
                          return
                        }
                        setExpiresAt(value < todayInputValue ? todayInputValue : value)
                      }}
                      className="rounded-2xl"
                      disabled={isFormLocked}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="total" className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">Total</Label>
                    <Input
                      id="total"
                      type="text"
                      value={`$${totals.total.toFixed(2)}`}
                      readOnly
                      className="rounded-2xl font-semibold text-right bg-[color-mix(in_oklch,var(--primary)_12%,white)] dark:bg-[color-mix(in_oklch,var(--primary)_24%,black)] text-gray-900 dark:text-white border border-transparent"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="notes" className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">Notas</Label>
                  <Textarea
                    id="notes"
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    placeholder="Notas adicionales..."
                    disabled={isFormLocked}
                    rows={4}
                    className="rounded-2xl"
                  />
                </div>
              </div>
            </div>
          </div>
          <DialogFooter className="flex w-full justify-center sm:justify-center items-center gap-3 border-t border-gray-200 dark:border-[#2a2a2a] px-6 py-4 bg-white/95 dark:bg-[#111111]/95 backdrop-blur">
            <Button
              type="button"
              variant="outline"
              className="rounded-full"
              onClick={() => onOpenChange(false)}
              disabled={isFormLocked}
            >
              Cancelar
            </Button>
            <Button
              type="submit"
              variant="new"
              className="rounded-full px-6"
              disabled={isSubmitDisabled}
            >
              {isLoading ? "Guardando..." : quotation ? "Actualizar" : "Agregar"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { FC, useMemo, useState, useEffect } from "react"

import { QuotationsFilters } from "./quotations-filters"
import { QuotationsPagination } from "./quotations-pagination"
import { QuotationsStats } from "./quotations-stats"
import { QuotationsTable } from "./quotations-table"

import { SalesQuotationWithRelations } from "@/components/sales/quotation/types"
import { Card, CardContent } from "@/components/ui/card"

const QuotationsTableComponent = QuotationsTable as unknown as FC<any>

export interface QuotationsContainerProps {
  quotations: SalesQuotationWithRelations[]
  isLoading?: boolean
  organizationId: string
  onEdit?: (quotation: SalesQuotationWithRelations) => void
  onDelete?: (quotation: SalesQuotationWithRelations) => void
  onViewDetails?: (quotation: SalesQuotationWithRelations) => void
  onConvert?: (quotation: SalesQuotationWithRelations) => void | Promise<void>
  showBranchColumn?: boolean
  branches?: { id: string; name: string | null }[]
  allowBranchFilter?: boolean
  onBranchFilterChange?: (branchId: string | null) => void
  selectedBranchFilter?: string | null
}

export const QuotationsContainer: FC<QuotationsContainerProps> = ({
  quotations,
  isLoading = false,
  organizationId: _organizationId,
  onEdit,
  onDelete,
  onViewDetails,
  onConvert,
  showBranchColumn = false,
  branches = [],
  allowBranchFilter = false,
  onBranchFilterChange,
  selectedBranchFilter,
}) => {
  const [pageSize, setPageSize] = useState(10)
  const [currentPage, setCurrentPage] = useState(1)
  const [searchTerm, setSearchTerm] = useState("")
  const [statusFilter, setStatusFilter] = useState<string>("all")
  const [branchFilter, setBranchFilter] = useState<string | null>(selectedBranchFilter ?? null)

  useEffect(() => {
    setBranchFilter(selectedBranchFilter ?? null)
  }, [selectedBranchFilter])

  const branchOptions = useMemo(() => {
    const unique = new Map<string, { id: string; name: string | null }>()
    let includeUnassigned = false

    branches.forEach((branch) => {
      if (!branch?.id) {
        return
      }
      if (!unique.has(branch.id)) {
        unique.set(branch.id, { id: branch.id, name: branch.name ?? "Sin sucursal" })
      }
    })

    quotations.forEach((quotation) => {
      const branchId = quotation.branchId ?? quotation.branch?.id ?? undefined
      const branchName =
        quotation.branch?.name ??
        unique.get(branchId ?? "")?.name ??
        "Sin sucursal"

      if (branchId) {
        if (!unique.has(branchId)) {
          unique.set(branchId, { id: branchId, name: branchName })
        }
      } else {
        includeUnassigned = true
      }
    })

    const options = Array.from(unique.values())

    if (includeUnassigned) {
      options.push({ id: "none", name: "Sin sucursal" })
    }

    return options
  }, [branches, quotations])

  // Filtrar cotizaciones por búsqueda y estado
  const filteredQuotations = useMemo(() => {
    return quotations.filter((quotation) => {
      const matchesStatus = statusFilter === "all" || quotation.status === statusFilter
      const normalizedQuotationBranchId = quotation.branchId ?? quotation.branch?.id ?? null
      const matchesBranch =
        !allowBranchFilter ||
        branchFilter === null ||
        (branchFilter === "none"
          ? !normalizedQuotationBranchId
          : normalizedQuotationBranchId === branchFilter)

      if (searchTerm.trim() !== "") {
        const searchLower = searchTerm.toLowerCase()
        const matchesSearch =
          quotation.quotationNumber?.toLowerCase().includes(searchLower) ||
          `${quotation.customer?.name ?? ""} ${quotation.customer?.lastName ?? ""}`.trim().toLowerCase().includes(searchLower) ||
          quotation.customerName?.toLowerCase().includes(searchLower) ||
          quotation.notes?.toLowerCase().includes(searchLower)

        return matchesSearch && matchesStatus && matchesBranch
      }

      return matchesStatus && matchesBranch
    })
  }, [branchFilter, quotations, searchTerm, showBranchColumn, statusFilter])

  const handleSearchChange = (term: string) => {
    setSearchTerm(term)
    setCurrentPage(1)
  }

  const handleStatusChange = (status: string) => {
    setStatusFilter(status)
    setCurrentPage(1)
  }

  const handleBranchChange = (branchId: string | null) => {
    setBranchFilter(branchId)
    setCurrentPage(1)
    if (onBranchFilterChange) {
      onBranchFilterChange(branchId)
    }
  }

  // Calcular cotizaciones para la página actual
  const startIndex = (currentPage - 1) * pageSize
  const endIndex = startIndex + pageSize
  const currentQuotations = filteredQuotations.slice(startIndex, endIndex)

  const handlePageSizeChange = (size: number) => {
    setPageSize(size)
    setCurrentPage(1)
  }

  const handlePageChange = (page: number) => {
    setCurrentPage(page)
  }

  return (
    <div className="space-y-6">
      <QuotationsStats quotations={quotations as any} isLoading={isLoading} />

      <Card className="bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a]">
        <CardContent className="pt-6">
          <QuotationsFilters 
            onPageSizeChange={handlePageSizeChange}
            onSearchChange={handleSearchChange}
            onStatusChange={handleStatusChange}
            statusValue={statusFilter}
            branches={branchOptions}
            selectedBranchId={branchFilter}
            onBranchChange={allowBranchFilter ? handleBranchChange : undefined}
            showBranchFilter={allowBranchFilter}
          />
        </CardContent>
      </Card>

      <div className="rounded-md border border-gray-200 bg-white dark:border-[#2a2a2a] dark:bg-[#1a1a1a] shadow-sm">
        <QuotationsTableComponent
          quotations={currentQuotations as any}
          isLoading={isLoading}
          onEditClick={onEdit as any}
          onDeleteClick={onDelete as any}
          onViewDetails={onViewDetails as any}
          onConvertClick={onConvert}
          showBranchColumn={showBranchColumn}
        />
      </div>

      <div className="flex justify-center">
        <QuotationsPagination
          currentPage={currentPage}
          totalPages={Math.ceil(filteredQuotations.length / pageSize)}
          pageSize={pageSize}
          onPageChange={handlePageChange}
          onPageSizeChange={handlePageSizeChange}
        />
      </div>
    </div>
  )
}

"use client"

import { ChevronLeft, ChevronRight } from "lucide-react"

import { Button } from "@/components/ui/button"

interface RolesSasPaginationProps {
  currentPage: number
  totalPages: number
  pageSize: number
  onPageChange: (page: number) => void
  onPageSizeChange: (size: number) => void
}

export function RolesSasPagination({
  currentPage,
  totalPages,
  pageSize,
  onPageChange,
  onPageSizeChange
}: RolesSasPaginationProps) {
  const handlePrevious = () => {
    if (currentPage > 1) {
      onPageChange(currentPage - 1)
    }
  }

  const handleNext = () => {
    if (currentPage < totalPages) {
      onPageChange(currentPage + 1)
    }
  }

  if (totalPages <= 1) return null

  return (
    <div className="flex items-center justify-center gap-4 py-4">
      <div className="text-sm text-gray-600 dark:text-gray-400">
        Página {currentPage} de {totalPages}
      </div>
      <div className="flex gap-2">
        <Button
          variant="outline"
          size="sm"
          onClick={handlePrevious}
          disabled={currentPage === 1}
          className="rounded-full"
        >
          <ChevronLeft className="h-4 w-4" />
          Anterior
        </Button>
        <Button
          variant="outline"
          size="sm"
          onClick={handleNext}
          disabled={currentPage === totalPages}
          className="rounded-full"
        >
          Siguiente
          <ChevronRight className="h-4 w-4" />
        </Button>
      </div>
    </div>
  )
}

"use client"

import { BrowserMultiFormatReader } from "@zxing/library"
import { ScanLine, X, Check, AlertCircle } from "lucide-react"
import { useState, useEffect, useCallback, useMemo, useRef } from "react"
import { toast } from "sonner"

import { SalesSaleWithRelations } from "./types"

import { Alert, AlertDescription } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"




interface SaleCancelDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  sale: SalesSaleWithRelations | null
  onCancel: () => Promise<void>
}

export function SaleCancelDialog({ open, onOpenChange, sale, onCancel }: SaleCancelDialogProps) {
  const [isCancelling, setIsCancelling] = useState(false)
  const [isScanning, setIsScanning] = useState(false)
  const [scanningProductId, setScanningProductId] = useState<string | null>(null)
  const [scannedCodes, setScannedCodes] = useState<Record<string, Set<string>>>({})
  const [codeReaderRef, setCodeReaderRef] = useState<BrowserMultiFormatReader | null>(null)
  const [videoStream, setVideoStream] = useState<MediaStream | null>(null)
  const [scannerVideoRef, setScannerVideoRef] = useState<HTMLVideoElement | null>(null)
  const [isLoadingData, setIsLoadingData] = useState(false)

  const stopScanning = useCallback(() => {
    if (codeReaderRef) {
      try {
        codeReaderRef.reset()
      } catch (error) {
        console.error('Error stopping scan:', error)
      }
    }
    if (videoStream) {
      videoStream.getTracks().forEach(track => track.stop())
      setVideoStream(null)
    }
    setIsScanning(false)
    setScanningProductId(null)
  }, [codeReaderRef, videoStream])

  const saleIdRef = useRef<string | null>(null)
  const itemsWithCodes = useMemo(() => {
    return sale?.items.filter(item => item.trackingCodes && item.trackingCodes.length > 0) || []
  }, [sale?.items?.map(item => `${item.id}-${item.trackingCodes?.length || 0}`).join(',')])

  useEffect(() => {
    if (!open || !sale) {
      setScannedCodes({})
      stopScanning()
      saleIdRef.current = null
      return
    }

    // Solo inicializar si es una nueva venta
    if (saleIdRef.current === sale.id) {
      return
    }

    saleIdRef.current = sale.id

    // Inicializar los códigos escaneados
    const initialCodes: Record<string, Set<string>> = {}
    itemsWithCodes.forEach(item => {
      if (item.productId) {
        initialCodes[item.productId] = new Set()
      }
    })
    setScannedCodes(initialCodes)
  }, [open, sale, itemsWithCodes, stopScanning])

  const validateCode = useCallback((productId: string, code: string): boolean => {
    if (!sale) return false
    const item = itemsWithCodes.find(item => item.productId === productId)
    if (!item || !item.trackingCodes) return false
    return item.trackingCodes.includes(code)
  }, [sale, itemsWithCodes])

  const startScanning = useCallback(async (productId: string) => {
    try {
      stopScanning()
      setIsScanning(true)
      
      const reader = new BrowserMultiFormatReader()
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment' },
      })
      setCodeReaderRef(reader)
      setVideoStream(stream)
      setScanningProductId(productId)
      
      await new Promise((resolve) => setTimeout(resolve, 100))

      const video = document.getElementById('scanner-video') as HTMLVideoElement
      if (video) {
        video.srcObject = stream
        video.setAttribute('playsinline', 'true')
        video.setAttribute('muted', 'true')
        await video.play()
      }

      reader.decodeFromVideoDevice(null, video as HTMLVideoElement, (result, err) => {
        if (result) {
          const scannedCode = result.getText()
          
          // Validar el código antes de agregarlo
          if (!validateCode(productId, scannedCode)) {
            toast.error(`El código "${scannedCode}" no pertenece a este producto`)
            stopScanning()
            return
          }
          
          setScannedCodes(prev => {
            const newCodes = { ...prev }
            if (!newCodes[productId]) {
              newCodes[productId] = new Set()
            }
            // Verificar si ya existe
            if (newCodes[productId].has(scannedCode)) {
              return newCodes
            }
            newCodes[productId] = new Set(newCodes[productId]).add(scannedCode)
            return newCodes
          })
          stopScanning()
          toast.success(`Código escaneado: ${scannedCode}`)
        }
        if (err && !(err as any).closed) {
          if (!err.message || !err.message.toLowerCase().includes('no multiformat readers')) {
            // Silenciar errores esperados
          }
        }
      })
    } catch (error) {
      console.error('Error al acceder a la cámara:', error)
      toast.error('No se pudo acceder a la cámara')
      stopScanning()
    }
  }, [stopScanning, validateCode])

  useEffect(() => {
    return () => {
      stopScanning()
    }
  }, [stopScanning])

  const addManualCode = useCallback((productId: string, code: string) => {
    const trimmedCode = code.trim()
    if (!trimmedCode) return

    // Validar el código antes de agregarlo
    if (!validateCode(productId, trimmedCode)) {
      toast.error(`El código "${trimmedCode}" no pertenece a este producto`)
      return
    }

    setScannedCodes(prev => {
      const newCodes = { ...prev }
      if (!newCodes[productId]) {
        newCodes[productId] = new Set()
      }
      // Verificar si ya existe
      if (newCodes[productId].has(trimmedCode)) {
        toast.warning(`El código "${trimmedCode}" ya fue agregado`)
        return newCodes
      }
      newCodes[productId] = new Set(newCodes[productId]).add(trimmedCode)
      toast.success(`Código agregado: ${trimmedCode}`)
      return newCodes
    })
  }, [validateCode])

  const removeCode = useCallback((productId: string, code: string) => {
    setScannedCodes(prev => {
      const newCodes = { ...prev }
      if (newCodes[productId]) {
        const newSet = new Set(newCodes[productId])
        newSet.delete(code)
        newCodes[productId] = newSet
      }
      return newCodes
    })
  }, [])

  const handleCancel = async () => {
    if (!sale) return

    // Verificar que todos los códigos requeridos estén escaneados
    for (const item of itemsWithCodes) {
      if (!item.productId) continue
      const expectedCodes = item.trackingCodes || []
      const scannedCount = scannedCodes[item.productId]?.size || 0
      
      if (scannedCount !== expectedCodes.length) {
        toast.error(`Faltan códigos para ${item.product?.name || 'producto'}. Se requiere ${expectedCodes.length}, se han escaneado ${scannedCount}.`)
        return
      }

      // Verificar que cada código escaneado coincida con uno de los esperados
      const scannedSet = scannedCodes[item.productId] || new Set()
      const expectedSet = new Set(expectedCodes)
      const hasValidCodes = Array.from(scannedSet).every(code => expectedSet.has(code))
      
      if (!hasValidCodes) {
        toast.error(`Algunos códigos para ${item.product?.name || 'producto'} no coinciden con los de la venta.`)
        return
      }
    }

    setIsCancelling(true)
    try {
      await onCancel()
      onOpenChange(false)
    } finally {
      setIsCancelling(false)
    }
  }

  const isCodeComplete = (productId: string, expectedCount: number) => {
    return (scannedCodes[productId]?.size || 0) === expectedCount
  }

  if (!sale) return null

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[700px] max-h-[90vh] overflow-hidden p-0">
        <DialogHeader className="px-6 py-5 border-b border-gray-200 dark:border-gray-800">
          <DialogTitle className="text-2xl font-semibold text-gray-900 dark:text-white">Anular Venta</DialogTitle>
          <DialogDescription className="text-gray-600 dark:text-gray-400">
            Verifica los códigos únicos de los productos para anular esta venta.
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
          {itemsWithCodes.length === 0 ? (
            <Alert>
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>
                Esta venta no tiene códigos únicos registrados. ¿Estás seguro de que deseas anularla?
              </AlertDescription>
            </Alert>
          ) : (
            <div className="space-y-4">
              {itemsWithCodes.map((item) => {
                const expectedCodes = item.trackingCodes || []
                const scannedSet = scannedCodes[item.productId] || new Set()
                const isComplete = isCodeComplete(item.productId || '', expectedCodes.length)
                const inputKey = `code-input-${item.productId}`

                return (
                  <div
                    key={item.productId}
                    className="rounded-3xl border border-gray-200 dark:border-gray-800 bg-gray-50/70 dark:bg-white/5 p-4 space-y-3"
                  >
                    <div className="flex items-center justify-between">
                      <div>
                        <h3 className="font-semibold text-gray-900 dark:text-white">{item.product?.name || 'Producto desconocido'}</h3>
                        <p className="text-sm text-gray-600 dark:text-gray-400">
                          Cantidad: {item.quantity} | Requiere: {expectedCodes.length} códigos
                        </p>
                      </div>
                      {isComplete && (
                        <Badge className="bg-green-100 text-green-700 dark:bg-green-900/20 dark:text-green-400 border-green-200 dark:border-green-800">
                          <Check className="h-3 w-3 mr-1" />
                          Completo
                        </Badge>
                      )}
                    </div>

                    <div className="flex gap-2">
                      <Input
                        key={inputKey}
                        placeholder="Ingresa o escanea código"
                        className="rounded-full flex-1"
                        onKeyDown={(e) => {
                          if (e.key === 'Enter') {
                            addManualCode(item.productId || '', e.currentTarget.value)
                            e.currentTarget.value = ''
                          }
                        }}
                      />
                      <Button
                        type="button"
                        variant="outline"
                        size="icon"
                        className="rounded-full"
                        onClick={() => startScanning(item.productId || '')}
                        disabled={isLoadingData || isComplete}
                      >
                        <ScanLine className="h-4 w-4" />
                      </Button>
                    </div>

                    {scannedSet.size > 0 && (
                      <div className="flex flex-wrap gap-2">
                        {Array.from(scannedSet).map((code) => (
                          <Badge
                            key={code}
                            variant="secondary"
                            className="inline-flex items-center gap-1 bg-gray-100 dark:bg-white/10 text-gray-700 dark:text-gray-200 border-0"
                          >
                            #{code}
                            <button
                              type="button"
                              onClick={() => removeCode(item.productId || '', code)}
                              className="ml-1 text-gray-500 hover:text-rose-500 dark:text-gray-400 dark:hover:text-rose-400"
                            >
                              <X className="h-3 w-3" />
                            </button>
                          </Badge>
                        ))}
                      </div>
                    )}

                    {!isComplete && expectedCodes.length > 0 && (
                      <p className="text-xs text-amber-600 dark:text-amber-400">
                        Faltan {expectedCodes.length - scannedSet.size} código(s)
                      </p>
                    )}
                  </div>
                )
              })}
            </div>
          )}
        </div>

        <DialogFooter className="border-t border-gray-200 dark:border-[#2a2a2a] px-6 py-4">
          <Button variant="outline" className="rounded-full" onClick={() => onOpenChange(false)} disabled={isCancelling}>
            Cancelar
          </Button>
          <Button
            variant="destructive"
            className="rounded-full"
            onClick={handleCancel}
            disabled={isCancelling}
          >
            {isCancelling ? 'Anulando...' : 'Anular Venta'}
          </Button>
        </DialogFooter>

        {isScanning && (
          <div className="fixed inset-0 z-[120] flex items-center justify-center">
            <div className="absolute inset-0 bg-black/70" onClick={stopScanning} />
            <div className="relative z-[121] flex flex-col items-center gap-4">
              <video
                id="scanner-video"
                className="w-72 h-72 rounded-3xl border-4 border-white object-cover shadow-2xl"
                autoPlay
                muted
                playsInline
              />
              <Button type="button" variant="secondary" className="rounded-full" onClick={stopScanning}>
                Detener escaneo
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  )
}

"use client"

import jsPDF from "jspdf"
import { FileDown, Printer } from "lucide-react"
import { useCallback, useEffect, useMemo, useState } from "react"
import { toast } from "sonner"

import { SalesSaleWithRelations } from "./types"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { formatDateTime } from "@/lib/utils/date"
import { generateSalePdfAndPrint } from "@/lib/utils/pdf-sale-print"

interface SaleDetailsDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  sale: SalesSaleWithRelations | null
  customerSlug: string
}

const statusTokens: Record<string, { label: string; className: string }> = {
  completed: {
    label: "Completada",
    className: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400 border-emerald-200 dark:border-emerald-800",
  },
  pending: {
    label: "Pendiente",
    className: "bg-amber-100 text-amber-700 dark:bg-amber-900/20 dark:text-amber-400 border-amber-200 dark:border-amber-800",
  },
  cancelled: {
    label: "Cancelada",
    className: "bg-rose-100 text-rose-700 dark:bg-rose-900/20 dark:text-rose-400 border-rose-200 dark:border-rose-800",
  },
}

const paymentTokens: Record<string, string> = {
  cash: "Efectivo",
  card: "Tarjeta",
  transfer: "Transferencia",
  qr: "QR / Billetera",
}

const DEFAULT_CURRENCY = "BOB"

export function SaleDetailsDialog({ open, onOpenChange, sale, customerSlug }: SaleDetailsDialogProps) {
  const [isExporting, setIsExporting] = useState(false)
  const [shareUrl, setShareUrl] = useState<string | null>(null)
  const [companyName, setCompanyName] = useState<string>("")
  const [companyContactName, setCompanyContactName] = useState<string>("")
  const [companyEmail, setCompanyEmail] = useState<string>("")
  const [companyPhone, setCompanyPhone] = useState<string>("")
  const [companyAddress, setCompanyAddress] = useState<string>("")
  const [companyWebsite, setCompanyWebsite] = useState<string>("")
  const [companyLogo, setCompanyLogo] = useState<string>("")
  const [companyWhatsappNumber, setCompanyWhatsappNumber] = useState<string>("")
  const [currencyCode, setCurrencyCode] = useState<string>(DEFAULT_CURRENCY)
  const [showBranchInfo, setShowBranchInfo] = useState<boolean>(true)

  useEffect(() => {
    if (!open) {
      setShareUrl(null)
    }
  }, [open])

  useEffect(() => {
    setShareUrl(null)
  }, [sale?.id])

  const handleOpenShareUrl = useCallback(() => {
    if (!shareUrl) return
    if (typeof window !== "undefined") {
      window.open(shareUrl, "_blank", "noopener,noreferrer")
    }
  }, [shareUrl])

  useEffect(() => {
    if (typeof document === "undefined") return
    try {
      const raw = document.cookie
        .split("; ")
        .find((chunk) => chunk.startsWith(`sas-prefs-${customerSlug}=`))
        ?.split("=")[1]
      if (!raw) {
        setCompanyWhatsappNumber("")
        setCompanyName("")
        setCompanyContactName("")
        setCompanyEmail("")
        setCompanyPhone("")
        setCompanyAddress("")
        setCompanyWebsite("")
        setCompanyLogo("")
        setCurrencyCode(DEFAULT_CURRENCY)
        setShowBranchInfo(true)
        return
      }
      const parsed = JSON.parse(decodeURIComponent(raw))
      const value = typeof parsed.whatsappNumber === "string" ? parsed.whatsappNumber : ""
      setCompanyWhatsappNumber(value)
      setCompanyName(typeof parsed.companyName === "string" ? parsed.companyName : "")
      setCompanyContactName(typeof parsed.companyContactName === "string" ? parsed.companyContactName : "")
      setCompanyEmail(typeof parsed.companyEmail === "string" ? parsed.companyEmail : "")
      setCompanyPhone(typeof parsed.companyPhone === "string" ? parsed.companyPhone : "")
      setCompanyAddress(typeof parsed.companyAddress === "string" ? parsed.companyAddress : "")
      setCompanyWebsite(typeof parsed.companyWebsite === "string" ? parsed.companyWebsite : "")
      setCompanyLogo(typeof parsed.companyLogo === "string" ? parsed.companyLogo : "")
      setCurrencyCode(typeof parsed.currency === "string" && parsed.currency.trim() ? parsed.currency : DEFAULT_CURRENCY)
      const branchCount = typeof parsed.branchCount === 'number' ? parsed.branchCount : undefined
      setShowBranchInfo(branchCount === undefined || branchCount > 1)
    } catch {
      setCompanyWhatsappNumber("")
      setCompanyName("")
      setCompanyContactName("")
      setCompanyEmail("")
      setCompanyPhone("")
      setCompanyAddress("")
      setCompanyWebsite("")
      setCompanyLogo("")
      setCurrencyCode(DEFAULT_CURRENCY)
      setShowBranchInfo(true)
    }
  }, [customerSlug, open])

  const fetchImageAsDataUrl = useCallback(async (url: string): Promise<string | null> => {
    if (!url) return null
    try {
      const response = await fetch(url)
      if (!response.ok) return null
      const blob = await response.blob()
      return await new Promise<string | null>((resolve, reject) => {
        const reader = new FileReader()
        reader.onload = () => resolve(reader.result as string)
        reader.onerror = () => reject(new Error('No se pudo cargar la imagen'))
        reader.readAsDataURL(blob)
      })
    } catch (error) {
      console.error('No se pudo cargar el logo para el PDF:', error)
      return null
    }
  }, [])

  const formatCurrency = useCallback(
    (value: number) => `${currencyCode} ${Number(value || 0).toLocaleString("es-BO", { minimumFractionDigits: 2 })}`,
    [currencyCode]
  )

  const customerName = useMemo(() => {
    if (!sale) return "—"
    if (sale.customer) {
      const fullName = `${sale.customer.name ?? ""} ${sale.customer.lastName ?? ""}`.trim()
      return fullName || sale.customer.email || sale.customerName || "Cliente sin registrar"
    }
    return sale.customerName || "Cliente sin registrar"
  }, [sale])

  const items = sale?.items ?? []
  const subtotal = Number(sale?.subtotal ?? 0)
  const discount = Number(sale?.discount ?? 0)
  const total = Number(sale?.total ?? 0)

  const statusToken = sale ? (statusTokens[sale.status] || statusTokens.completed) : statusTokens.completed
  const paymentLabel = sale ? (paymentTokens[sale.paymentMethod] || sale.paymentMethod) : ""

  const handleExportPdf = useCallback(async () => {
    if (!sale) return

    if (shareUrl) {
      handleOpenShareUrl()
      toast.success("Abriendo PDF existente")
      return
    }

    try {
      setIsExporting(true)
      setShareUrl(null)

      const getPrimaryColor = (): { r: number; g: number; b: number } => {
        const fallback = { r: 26, g: 120, b: 102 }
        if (typeof window === 'undefined') return fallback

        try {
          const dummy = document.createElement('span')
          dummy.style.position = 'fixed'
          dummy.style.opacity = '0'
          dummy.style.pointerEvents = 'none'
          dummy.style.color = 'var(--primary)'
          document.body.appendChild(dummy)
          const resolved = getComputedStyle(dummy).color
          document.body.removeChild(dummy)

          const rgbMatch = resolved.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/i)
          if (rgbMatch) {
            return {
              r: Number(rgbMatch[1]),
              g: Number(rgbMatch[2]),
              b: Number(rgbMatch[3])
            }
          }
        } catch {}

        return fallback
      }

      const primaryColor = getPrimaryColor()
      const doc = new jsPDF({ unit: 'mm', format: 'a4' })
      const pageWidth = doc.internal.pageSize.getWidth()
      const pageHeight = doc.internal.pageSize.getHeight()
      const margin = 16

      let cursorY = margin + 6

      const logoDataUrl = companyLogo ? await fetchImageAsDataUrl(companyLogo) : null

      const headerTitleY = margin
      doc.setFont('helvetica', 'bold')
      doc.setFontSize(18)
      doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b)
      doc.text('Detalle de Venta', pageWidth / 2, headerTitleY, { align: 'center' })

      const maxLogoHeight = 32
      const logoX = pageWidth - margin - maxLogoHeight
      let contactBlockTop = headerTitleY + 8
      if (logoDataUrl) {
        doc.addImage(logoDataUrl, 'PNG', logoX, headerTitleY - 6, maxLogoHeight, maxLogoHeight, undefined, 'FAST')
        contactBlockTop = headerTitleY - 6 + maxLogoHeight + 6
      }

      const headerLeftX = margin
      let headerLeftY = headerTitleY + 8
      doc.setFont('helvetica', 'bold')
      doc.setFontSize(13)
      doc.setTextColor(30, 30, 30)
      doc.text(companyName || 'Nombre de la empresa', headerLeftX, headerLeftY)
      headerLeftY += 5

      doc.setFont('helvetica', 'normal')
      doc.setFontSize(10)
      doc.setTextColor(60, 60, 60)
      if (companyAddress) {
        doc.text(companyAddress, headerLeftX, headerLeftY)
        headerLeftY += 5
      }
      if (companyEmail) {
        doc.text(companyEmail, headerLeftX, headerLeftY)
        headerLeftY += 5
      }
      const formattedNow = formatDateTime(new Date())
      doc.setFont('helvetica', 'bold')
      doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b)
      doc.text('Fecha y Hora :', headerLeftX, headerLeftY)
      doc.setFont('helvetica', 'normal')
      doc.setTextColor(60, 60, 60)
      doc.text(formattedNow, headerLeftX + 30, headerLeftY)
      headerLeftY += 8

      const contactName = companyContactName || companyName || '—'
      const contactPhone = companyPhone || companyWhatsappNumber || '—'
      let contactY = contactBlockTop
      doc.setFont('helvetica', 'bold')
      doc.setFontSize(11)
      doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b)
      doc.text(contactName, logoX + maxLogoHeight, contactY, { align: 'right' })
      contactY += 6
      doc.setFont('helvetica', 'normal')
      doc.setFontSize(10)
      doc.setTextColor(60, 60, 60)
      doc.text(`Contactos: ${contactPhone}`, logoX + maxLogoHeight, contactY, { align: 'right' })
      contactY += 6

      const headerBottom = Math.max(headerLeftY, contactY, headerTitleY + maxLogoHeight) + 4
      doc.setDrawColor(primaryColor.r, primaryColor.g, primaryColor.b)
      doc.setLineWidth(0.6)
      doc.line(margin, headerBottom, pageWidth - margin, headerBottom)
      cursorY = headerBottom + 6

      const columnGap = 8
      const leftColumnX = margin
      const rightColumnX = pageWidth / 2 + columnGap / 2

      const customerDetails: Array<[string, string]> = [
        ['Cliente', customerName],
        ['Teléfono', sale.customer?.phone || '—'],
        ['Correo', sale.customer?.email || '—'],
      ]

      const saleDetails: Array<[string, string]> = [
        ['Código', sale.saleNumber],
        ['Fecha', sale.createdAt ? formatDateTime(sale.createdAt) : 'Sin fecha'],
        ['Método de Pago', paymentLabel],
      ]

      const drawDetailsColumn = (x: number, title: string, rows: Array<[string, string]>) => {
        let y = cursorY
        doc.setFont('helvetica', 'bold')
        doc.setFontSize(11)
        doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b)
        doc.text(title.toUpperCase(), x, y)
        y += 6
        doc.setFont('helvetica', 'normal')
        doc.setFontSize(10)
        doc.setTextColor(45, 45, 45)

        rows.forEach(([label, value]: [string, string]) => {
          doc.text(`${label}:`, x, y)
          const valueX = x + 32
          const width = pageWidth / 2 - columnGap - 38
          const lines = doc.splitTextToSize(value || '—', width) as string[]
          lines.forEach((line: string, idx: number) => {
            doc.text(line, valueX, y + idx * 5)
          })
          y = y + Math.max(lines.length * 5, 6)
        })

        return y
      }

      const leftEnd = drawDetailsColumn(leftColumnX, 'Datos del cliente', customerDetails)
      const rightEnd = drawDetailsColumn(rightColumnX, 'Datos de la venta', saleDetails)
      cursorY = Math.max(leftEnd, rightEnd) + 6

      const tableTop = cursorY + 4
      const tableWidth = pageWidth - margin * 2
      const colProduct = margin + 2
      const colPrice = margin + tableWidth * 0.55
      const colQty = margin + tableWidth * 0.74
      const colSubtotal = margin + tableWidth - 2

      doc.setFillColor(primaryColor.r, primaryColor.g, primaryColor.b)
      doc.setTextColor(255, 255, 255)
      doc.setFont('helvetica', 'bold')
      doc.roundedRect(margin, tableTop, tableWidth, 9, 3, 3, 'F')
      doc.text('Producto', colProduct, tableTop + 6)
      doc.text(`Precio ${currencyCode}`, colPrice, tableTop + 6)
      doc.text('Cantidad', colQty, tableTop + 6)
      doc.text('Subtotal', colSubtotal, tableTop + 6, { align: 'right' })

      let rowY = tableTop + 11
      doc.setFont('helvetica', 'normal')
      doc.setFontSize(10)
      doc.setTextColor(45, 45, 45)

      if (items.length === 0) {
        doc.text('No hay productos registrados en esta venta.', margin + 4, rowY + 4)
        rowY += 14
      } else {
        items.forEach((item, index) => {
          const displayName = item.product?.name || 'Producto sin nombre'
          const descriptionLines = doc.splitTextToSize(displayName, tableWidth * 0.52) as string[]
          const rowHeight = Math.max(descriptionLines.length * 5, 7) + 4

          if (rowY + rowHeight > pageHeight - 40) {
            doc.addPage()
            rowY = margin
            doc.setFont('helvetica', 'bold')
            doc.setFontSize(10)
            doc.setFillColor(primaryColor.r, primaryColor.g, primaryColor.b)
            doc.setTextColor(255, 255, 255)
            doc.roundedRect(margin, rowY, tableWidth, 9, 3, 3, 'F')
            doc.text('Producto', colProduct, rowY + 6)
            doc.text(`Precio ${currencyCode}`, colPrice, rowY + 6)
            doc.text('Cantidad', colQty, rowY + 6)
            doc.text('Subtotal', colSubtotal, rowY + 6, { align: 'right' })
            rowY += 11
            doc.setFont('helvetica', 'normal')
            doc.setFontSize(10)
            doc.setTextColor(45, 45, 45)
          }

          if (index % 2 === 0) {
            doc.setFillColor(248, 249, 252)
            doc.rect(margin, rowY - 3, tableWidth, rowHeight, 'F')
          }

          descriptionLines.forEach((line: string, idx: number) => {
            doc.text(line, colProduct, rowY + idx * 5)
          })
          doc.text(formatCurrency(item.unitPrice), colPrice, rowY)
          doc.text(String(item.quantity), colQty, rowY)
          doc.text(formatCurrency(item.subtotal), colSubtotal, rowY, { align: 'right' })

          rowY += rowHeight
        })
      }

      doc.setDrawColor(230, 230, 230)
      const dividerY = tableTop - 4
      doc.line(margin, dividerY, pageWidth - margin, dividerY)
      cursorY = rowY + 12

      const summaryRows: Array<[string, string]> = [
        ['SUB TOTAL', formatCurrency(subtotal)],
        ['DESCUENTO', formatCurrency(discount)],
        ['TOTAL', formatCurrency(total)],
      ]

      doc.setFont('helvetica', 'bold')
      doc.setFontSize(11)
      doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b)
      doc.text('Resumen de Totales', pageWidth - margin, cursorY, { align: 'right' })
      cursorY += 6
      doc.setFont('helvetica', 'normal')
      doc.setFontSize(10)
      doc.setTextColor(45, 45, 45)

      summaryRows.forEach(([label, value]) => {
        doc.text(label, pageWidth - margin - 70, cursorY)
        doc.text(value, pageWidth - margin, cursorY, { align: 'right' })
        cursorY += 6
      })

      // Agregar notas si existen
      if (sale.notes && sale.notes.trim()) {
        cursorY += 8
        doc.setFont('helvetica', 'bold')
        doc.setFontSize(11)
        doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b)
        doc.text('NOTAS:', margin, cursorY)
        cursorY += 6
        doc.setFont('helvetica', 'normal')
        doc.setFontSize(10)
        doc.setTextColor(45, 45, 45)
        const notesLines = doc.splitTextToSize(sale.notes.trim(), pageWidth - margin * 2 - 4) as string[]
        notesLines.forEach((line: string, idx: number) => {
          doc.text(line, margin + 2, cursorY + idx * 5)
        })
        cursorY += notesLines.length * 5 + 6
      }

      const fileBaseName = sale.id ? `venta-${sale.id}` : `venta-${sale.saleNumber}`
      doc.save(`${fileBaseName}.pdf`)

      const dataUri = doc.output('datauristring')
      const base64 = dataUri.split(',')[1]

      if (base64) {
        try {
          const response = await fetch(`/api/${customerSlug}/ventas/export`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              fileName: fileBaseName,
              pdfBase64: base64,
            }),
          })

          if (response.ok) {
            const payload = await response.json()
            const relativeUrl = payload?.url as string | undefined
            if (relativeUrl) {
              const absoluteUrl = relativeUrl.startsWith('http')
                ? relativeUrl
                : `${typeof window !== 'undefined' ? window.location.origin : ''}${relativeUrl}`
              setShareUrl(absoluteUrl)
              toast.success('PDF listo y enlace generado')
            } else {
              toast.success('PDF generado correctamente')
            }
          } else {
            const errorData = await response.json().catch(() => ({}))
            toast.error(errorData?.error || 'PDF descargado, pero no se pudo guardar el enlace')
          }
        } catch (uploadError) {
          console.error('Error subiendo PDF de venta:', uploadError)
          toast.error('PDF descargado, pero no se pudo guardar el enlace')
        }
      }
    } catch (error) {
      console.error('Error al exportar la venta:', error)
      toast.error('No se pudo generar el PDF')
    } finally {
      setIsExporting(false)
    }
  }, [
    sale,
    shareUrl,
    handleOpenShareUrl,
    companyLogo,
    customerSlug,
    subtotal,
    discount,
    total,
    formatCurrency,
    fetchImageAsDataUrl,
    companyName,
    companyAddress,
    companyEmail,
    companyPhone,
    companyWebsite,
    companyWhatsappNumber,
    companyContactName,
    showBranchInfo,
    customerName,
    paymentLabel,
    currencyCode,
    items,
  ])

  const handlePrint = useCallback(async () => {
    if (!sale || typeof window === 'undefined') return
    await generateSalePdfAndPrint(sale, customerSlug)
  }, [sale, customerSlug])

  useEffect(() => {
    if (!open || !sale || shareUrl || typeof window === "undefined") return
    const candidates = [
      sale.id ? `/uploads/sales/${customerSlug}/venta-${sale.id}.pdf` : null,
      sale.saleNumber ? `/uploads/sales/${customerSlug}/venta-${sale.saleNumber}.pdf` : null,
    ].filter(Boolean) as string[]

    const checkExisting = async () => {
      for (const relativeUrl of candidates) {
        try {
          const res = await fetch(relativeUrl, { method: 'HEAD' })
          if (res.ok) {
            const absolute = new URL(relativeUrl, window.location.origin).toString()
            setShareUrl(absolute)
            break
          }
        } catch {
          // ignore
        }
      }
    }

    checkExisting()
  }, [open, sale, customerSlug, shareUrl])

  if (!sale) {
    return <Dialog open={open} onOpenChange={onOpenChange} />
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-3xl sm:max-w-4xl h-[85vh] flex flex-col overflow-hidden p-0">
        <DialogHeader className="sticky top-0 z-10 backdrop-blur bg-white/80 dark:bg-[#101010]/80 border-b border-gray-200 dark:border-gray-800 px-6 py-4">
          <DialogTitle className="text-2xl font-semibold text-gray-900 dark:text-white">Venta {sale.saleNumber}</DialogTitle>
          <DialogDescription className="text-gray-600 dark:text-gray-400">
            Registrada el {sale.createdAt ? formatDateTime(sale.createdAt) : 'Sin fecha'} · {paymentLabel}
          </DialogDescription>
          <div className="mt-2 flex flex-wrap gap-2">
            <Badge variant="outline" className={`border ${statusToken.className}`}>
              {statusToken.label}
            </Badge>
            <Badge variant="secondary" className="bg-indigo-100 dark:bg-indigo-900/20 text-indigo-700 dark:text-indigo-300 border-0">
              Total: BOB {Number(sale?.total || 0).toLocaleString('es-BO', { minimumFractionDigits: 2 })}
            </Badge>
          </div>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-6 py-4">
          <div className="space-y-6">
            <section className="grid gap-4 sm:grid-cols-2">
              <div>
                <h3 className="text-sm font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">Cliente</h3>
                <p className="mt-2 text-base font-medium text-gray-900 dark:text-white">
                  {sale.customer
                    ? `${sale.customer.name ?? ''} ${sale.customer.lastName ?? ''}`.trim() || 'Cliente sin registrar'
                    : 'Cliente sin registrar'}
                </p>
                {sale.customer?.email && (
                  <p className="text-sm text-gray-500 dark:text-gray-400">{sale.customer.email}</p>
                )}
                {sale.customer?.phone && (
                  <p className="text-sm text-gray-500 dark:text-gray-400">{sale.customer.phone}</p>
                )}
              </div>
              <div>
                <h3 className="text-sm font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">Atendido por</h3>
                <p className="mt-2 text-base font-medium text-gray-900 dark:text-white">
                  {sale.user?.fullName ?? 'Usuario no asignado'}
                </p>
                {sale.user?.email && (
                  <p className="text-sm text-gray-500 dark:text-gray-400">{sale.user.email}</p>
                )}
              </div>
            </section>

            <section className="overflow-hidden">
              <header className="px-4 py-3">
                <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 uppercase tracking-wide">Detalle de productos</h3>
              </header>
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow className="bg-gray-50 dark:bg-[#161616]">
                      <TableHead className="text-gray-600 dark:text-gray-300">Producto</TableHead>
                      <TableHead className="text-gray-600 dark:text-gray-300">Cantidad</TableHead>
                      <TableHead className="text-gray-600 dark:text-gray-300">Precio</TableHead>
                      <TableHead className="text-gray-600 dark:text-gray-300 text-right">Subtotal</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {sale.items.map((item) => (
                      <TableRow key={item.id || `${item.productId}-${item.quantity}`} className="border-gray-200 dark:border-gray-800">
                        <TableCell className="text-sm text-gray-900 dark:text-white">
                          {item.product?.name ?? 'Producto eliminado'}
                          {item.trackingCodes && item.trackingCodes.length > 0 && (
                            <div className="mt-2 flex flex-wrap gap-2">
                              {item.trackingCodes.map((code) => (
                                <Badge key={code} variant="secondary" className="bg-gray-100 dark:bg-white/10 text-gray-700 dark:text-gray-200 border-0">
                                  #{code}
                                </Badge>
                              ))}
                            </div>
                          )}
                        </TableCell>
                        <TableCell className="text-sm text-gray-700 dark:text-gray-300">
                          {item.quantity}
                        </TableCell>
                        <TableCell className="text-sm text-gray-700 dark:text-gray-300">
                          BOB {Number(item.unitPrice || 0).toLocaleString('es-BO', { minimumFractionDigits: 2 })}
                        </TableCell>
                        <TableCell className="text-sm text-gray-900 dark:text-white text-right font-semibold">
                          BOB {Number(item.subtotal || 0).toLocaleString('es-BO', { minimumFractionDigits: 2 })}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </section>

            <section className="flex flex-col gap-2">
              <div className="flex justify-between text-sm text-gray-600 dark:text-gray-400">
                <span>Subtotal</span>
                <span className="font-medium text-gray-900 dark:text-white">
                  BOB {Number(sale.subtotal || 0).toLocaleString('es-BO', { minimumFractionDigits: 2 })}
                </span>
              </div>
              <div className="flex justify-between text-sm text-gray-600 dark:text-gray-400">
                <span>Descuento</span>
                <span className="font-medium text-gray-900 dark:text-white">
                  BOB {Number(sale.discount || 0).toLocaleString('es-BO', { minimumFractionDigits: 2 })}
                </span>
              </div>
              <div className="flex justify-between text-base font-semibold text-gray-900 dark:text-white border-t border-dashed border-gray-300 dark:border-gray-700 pt-3">
                <span>Total</span>
                <span>
                  BOB {Number(sale.total || 0).toLocaleString('es-BO', { minimumFractionDigits: 2 })}
                </span>
              </div>
              {sale.notes && (
                <div className="mt-3 text-sm text-gray-600 dark:text-gray-400">
                  <h4 className="font-semibold uppercase tracking-wide text-xs text-gray-500 dark:text-gray-400 mb-1">Notas</h4>
                  <p>{sale.notes}</p>
                </div>
              )}
            </section>
          </div>
        </div>

        <DialogFooter className="sticky bottom-0 z-10 backdrop-blur bg-white/80 dark:bg-[#101010]/80 border-t border-gray-200 dark:border-gray-800 px-6 py-4 flex flex-col sm:flex-row items-center justify-center sm:justify-center gap-3">
          <Button
            variant="new"
            className="rounded-full"
            onClick={handleExportPdf}
            disabled={!sale || isExporting}
          >
            <FileDown className="mr-2 h-4 w-4" />
            {shareUrl ? "Ver PDF" : isExporting ? "Generando..." : "Exportar PDF"}
          </Button>
          <Button
            variant="outline"
            className="rounded-full"
            onClick={handlePrint}
          >
            <Printer className="mr-2 h-4 w-4" />
            Imprimir
          </Button>
          <Button variant="outline" className="rounded-full" onClick={() => onOpenChange(false)}>
            Cerrar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { BrowserMultiFormatReader } from "@zxing/library"
import { Check, ChevronsUpDown, Plus, Trash2, ScanLine, X, ChevronDown } from "lucide-react"
import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { toast } from "sonner"

import { SalesSaleWithRelations, SaleCustomerSummary, SaleProductSummary } from "./types"

import { Button } from "@/components/ui/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"
import { generateSalePdfAndPrint } from "@/lib/utils/pdf-sale-print"

const capitalizeWords = (value: string) =>
  value
    .toLowerCase()
    .replace(/\b\p{L}/gu, (char) => char.toUpperCase())

const DEFAULT_PHONE_PREFIX = "+591"
const DEFAULT_PHONE_PREFIX_DIGITS = DEFAULT_PHONE_PREFIX.replace(/\D/g, '')

const normalizePhoneForState = (value?: string | null) => {
  if (!value) return DEFAULT_PHONE_PREFIX
  const trimmed = value.trim()
  if (!trimmed) return DEFAULT_PHONE_PREFIX
  const digitsOnly = trimmed.replace(/\D/g, '')
  const localDigits = digitsOnly.startsWith(DEFAULT_PHONE_PREFIX_DIGITS)
    ? digitsOnly.slice(DEFAULT_PHONE_PREFIX_DIGITS.length)
    : digitsOnly
  if (!localDigits) return DEFAULT_PHONE_PREFIX
  return `${DEFAULT_PHONE_PREFIX}${localDigits}`
}

interface SaleFormDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  sale?: SalesSaleWithRelations
  customerSlug: string
  currentUser?: {
    id: string
    sucursalId?: string | null
  } | null
  onSave: (data: any) => Promise<any>
}

interface SaleItemForm {
  id: string
  productId: string
  product?: SaleProductSummary | null
  quantity: number
  unitPrice: number
  subtotal: number
  codes: string[]
}

const generateTempId = () =>
  typeof crypto !== "undefined" && crypto.randomUUID
    ? crypto.randomUUID()
    : Math.random().toString(36).slice(2)

const statusOptions = [
  { value: 'completed', label: 'Completada' },
  { value: 'pending', label: 'Pendiente' },
  { value: 'cancelled', label: 'Cancelada' },
]

const paymentOptions = [
  { value: 'cash', label: 'Efectivo' },
  { value: 'card', label: 'Tarjeta' },
  { value: 'transfer', label: 'Transferencia' },
  { value: 'qr', label: 'QR / Billetera' },
]

const createEmptyItem = (): SaleItemForm => ({
  id: generateTempId(),
  productId: '',
  product: undefined,
  quantity: 1,
  unitPrice: 0,
  subtotal: 0,
  codes: [],
})

export function SaleFormDialog({ open, onOpenChange, sale, customerSlug, onSave }: SaleFormDialogProps) {
  const [customers, setCustomers] = useState<SaleCustomerSummary[]>([])
  const [products, setProducts] = useState<SaleProductSummary[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [isLoadingData, setIsLoadingData] = useState(false)

  const [customerId, setCustomerId] = useState<string>('')
  const [customerInputValue, setCustomerInputValue] = useState<string>('')
  const [customerPhoneInput, setCustomerPhoneInput] = useState<string>(DEFAULT_PHONE_PREFIX)
  const [isCustomerDropdownOpen, setIsCustomerDropdownOpen] = useState(false)
  const [highlightedCustomerIndex, setHighlightedCustomerIndex] = useState(0)
  const customerContainerRef = useRef<HTMLDivElement>(null)
  const customerInputRef = useRef<HTMLInputElement>(null)
  const [paymentMethod, setPaymentMethod] = useState<string>('cash')
  const [items, setItems] = useState<SaleItemForm[]>([createEmptyItem()])
  const [discount, setDiscount] = useState<string>('0')
  const [notes, setNotes] = useState<string>('')
  const [codeInputs, setCodeInputs] = useState<Record<string, string>>({})
  const [isScanning, setIsScanning] = useState(false)
  const [scanningItemId, setScanningItemId] = useState<string | null>(null)
  const [videoStream, setVideoStream] = useState<MediaStream | null>(null)
  const codeReaderRef = useRef<BrowserMultiFormatReader | null>(null)
  const scannerVideoRef = useRef<HTMLVideoElement | null>(null)
  const lastScannedCode = useRef<string | null>(null)

  const fetchCustomers = useCallback(async () => {
    try {
      const response = await fetch(`/api/${customerSlug}/clientes?page=1&pageSize=1000`)
      if (!response.ok) return
      const data = await response.json()
      const mapped: SaleCustomerSummary[] = (data.customers || []).map((customer: any) => ({
        id: customer.id,
        name: customer.name ?? null,
        lastName: customer.lastName ?? null,
        email: customer.email ?? null,
        phone: customer.phone ?? null,
      }))
      setCustomers(mapped)
    } catch (error) {
      console.error('Error al cargar clientes:', error)
    }
  }, [customerSlug])

  const fetchProducts = useCallback(async () => {
    try {
      const response = await fetch(`/api/${customerSlug}/productos?page=1&pageSize=1000`)
      if (!response.ok) return
      const data = await response.json()
      const mapped: SaleProductSummary[] = (data.products || []).map((product: any) => ({
        id: product.id,
        name: product.name,
        price: Number(product.price ?? 0),
        imageUrl: product.imageUrl ?? null,
      }))
      setProducts(mapped)
    } catch (error) {
      console.error('Error al cargar productos:', error)
    }
  }, [customerSlug])

  // Filtrar clientes basados en el input
  const filteredCustomers = useMemo(() => {
    if (!customerInputValue.trim()) return customers
    const search = customerInputValue.trim().toLowerCase()
    return customers.filter((customer) => {
      const combined = `${customer.name ?? ''} ${customer.lastName ?? ''}`.trim().toLowerCase()
      return combined.includes(search)
    })
  }, [customers, customerInputValue])

  // Cerrar dropdown al hacer click fuera
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (customerContainerRef.current && !customerContainerRef.current.contains(event.target as Node)) {
        setIsCustomerDropdownOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  useEffect(() => {
    if (!open) return
    setIsLoadingData(true)
    Promise.all([fetchCustomers(), fetchProducts()]).finally(() => setIsLoadingData(false))
  }, [open, fetchCustomers, fetchProducts])

  useEffect(() => {
    if (!open) return

    if (sale) {
      setCustomerId(sale.customerId ?? '')
      const combinedName = `${sale.customer?.name ?? ''} ${sale.customer?.lastName ?? ''}`.trim()
      setCustomerInputValue(combinedName || (sale as any).customerName || '')
      setCustomerPhoneInput(normalizePhoneForState(sale.customer?.phone))
      setPaymentMethod(sale.paymentMethod ?? 'cash')
      setDiscount(Number(sale.discount ?? 0).toString())
      setNotes(sale.notes ?? '')
      const mappedItems =
        sale.items.map((item) => ({
          id: generateTempId(),
          productId: item.productId,
          product: item.product ?? undefined,
          quantity: Number(item.quantity ?? 0) || 1,
          unitPrice: Number(item.unitPrice ?? 0),
          subtotal: Number(item.subtotal ?? 0),
          codes: Array.isArray(item.trackingCodes)
            ? item.trackingCodes.filter((code) => typeof code === 'string').map((code) => code.trim())
            : [],
        })) || [createEmptyItem()]
      setItems(mappedItems)
      const inputs: Record<string, string> = {}
      mappedItems.forEach((item) => {
        inputs[item.id] = ''
      })
      setCodeInputs(inputs)
    } else {
      const empty = createEmptyItem()
      setCustomerId('')
      setCustomerInputValue('')
      setCustomerPhoneInput(DEFAULT_PHONE_PREFIX)
      setPaymentMethod('cash')
      setDiscount('0')
      setNotes('')
      setItems([empty])
      setCodeInputs({ [empty.id]: '' })
    }
  }, [sale, open])

  const stopScanning = useCallback(() => {
    if (codeReaderRef.current) {
      codeReaderRef.current.reset()
      codeReaderRef.current = null
    }
    if (videoStream) {
      videoStream.getTracks().forEach((track) => track.stop())
    }
    setVideoStream(null)
    setIsScanning(false)
    setScanningItemId(null)
    lastScannedCode.current = null
  }, [videoStream])

  useEffect(() => {
    return () => {
      stopScanning()
    }
  }, [stopScanning])

  useEffect(() => {
    if (!open) {
      stopScanning()
      setCodeInputs({})
    }
  }, [open, stopScanning])

  const subtotal = useMemo(() => {
    return items.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0)
  }, [items])

  const total = useMemo(() => {
    const numericDiscount = parseFloat(discount || '0')
    return subtotal - (Number.isNaN(numericDiscount) ? 0 : numericDiscount)
  }, [subtotal, discount])

  const handleCustomerKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!isCustomerDropdownOpen && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
      setIsCustomerDropdownOpen(true)
      return
    }

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightedCustomerIndex((prev) =>
          prev < filteredCustomers.length - 1 ? prev + 1 : prev
        )
        break
      case 'ArrowUp':
        e.preventDefault()
        setHighlightedCustomerIndex((prev) => (prev > 0 ? prev - 1 : prev))
        break
      case 'Enter':
        e.preventDefault()
        const trimmed = customerInputValue.trim()
        if (isCustomerDropdownOpen && filteredCustomers[highlightedCustomerIndex]) {
          selectCustomer(filteredCustomers[highlightedCustomerIndex])
        } else if (trimmed.length > 0) {
          handleManualCustomer(trimmed)
        } else {
          setIsCustomerDropdownOpen(false)
        }
        break
      case 'Escape':
        setIsCustomerDropdownOpen(false)
        break
    }
  }

  const selectCustomer = (customer: SaleCustomerSummary) => {
    setCustomerId(customer.id)
    const fullName = `${customer.name ?? ''} ${customer.lastName ?? ''}`.trim()
    setCustomerInputValue(capitalizeWords(fullName))
    setIsCustomerDropdownOpen(false)
    setHighlightedCustomerIndex(0)
    setCustomerPhoneInput(normalizePhoneForState(customer.phone))
  }

  const clearCustomer = () => {
    setCustomerId('')
    setCustomerInputValue('')
    customerInputRef.current?.focus()
    setHighlightedCustomerIndex(0)
    setCustomerPhoneInput(DEFAULT_PHONE_PREFIX)
  }

  const handleManualCustomer = (value: string) => {
    const trimmed = value.trim()
    if (trimmed.length === 0) return
    setCustomerId('')
    const formatted = capitalizeWords(trimmed)
    setCustomerInputValue(formatted)
    setIsCustomerDropdownOpen(false)
    setHighlightedCustomerIndex(0)
    setCustomerPhoneInput(DEFAULT_PHONE_PREFIX)
  }

  const handleAddItem = () => {
    const newItem = createEmptyItem()
    setItems((prev) => [...prev, newItem])
    setCodeInputs((prev) => ({ ...prev, [newItem.id]: '' }))
  }

  const handleRemoveItem = (id: string) => {
    setItems((prev) => (prev.length > 1 ? prev.filter((item) => item.id !== id) : prev))
    setCodeInputs((prev) => {
      if (prev[id] === undefined) return prev
      const updated = { ...prev }
      delete updated[id]
      return updated
    })
    if (scanningItemId === id) {
      stopScanning()
    }
  }

  const handleProductSelect = (rowId: string, productId: string) => {
    setItems((prev) =>
      prev.map((item) => {
        if (item.id !== rowId) return item
        const product = products.find((prod) => prod.id === productId)
        const unitPrice = product ? product.price : 0
        return {
          ...item,
          productId,
          product: product ?? undefined,
          unitPrice,
          subtotal: unitPrice * item.quantity,
        }
      }),
    )
  }

  const handleQuantityChange = (rowId: string, value: number) => {
    setItems((prev) =>
      prev.map((item) =>
        item.id === rowId
          ? {
              ...item,
              quantity: value,
              subtotal: value * item.unitPrice,
              codes: item.codes.slice(0, value),
            }
          : item,
      ),
    )
  }

  const handleUnitPriceChange = (rowId: string, value: number) => {
    setItems((prev) =>
      prev.map((item) =>
        item.id === rowId
          ? {
              ...item,
              unitPrice: value,
              subtotal: value * item.quantity,
            }
          : item,
      ),
    )
  }

  const addCodeToItem = (rowId: string, code: string, fromScanner = false) => {
    const trimmed = code.trim()
    if (!trimmed) {
      toast.error('Ingresa un código válido')
      return
    }

    let added = false
    setItems((prev) =>
      prev.map((item) => {
        if (item.id !== rowId) return item
        if (item.codes.includes(trimmed)) {
          toast.info('Este código ya se agregó al producto')
          return item
        }
        if (item.codes.length >= item.quantity) {
          toast.error('La cantidad de códigos no puede superar las unidades vendidas')
          return item
        }
        added = true
        return {
          ...item,
          codes: [...item.codes, trimmed],
        }
      }),
    )

    if (added) {
      setCodeInputs((prev) => ({ ...prev, [rowId]: '' }))
      if (fromScanner) {
        toast.success('Código escaneado y agregado')
        stopScanning()
      }
    }
  }

  const removeCodeFromItem = (rowId: string, code: string) => {
    setItems((prev) =>
      prev.map((item) =>
        item.id === rowId
          ? {
              ...item,
              codes: item.codes.filter((existing) => existing !== code),
            }
          : item,
      ),
    )
  }

  const handleManualCodeAdd = (rowId: string) => {
    const value = codeInputs[rowId] ?? ''
    addCodeToItem(rowId, value, false)
  }

  const startScanningForItem = async (rowId: string) => {
    try {
      stopScanning()
      setIsScanning(true)
      setScanningItemId(rowId)
      
      const reader = new BrowserMultiFormatReader()
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment' },
      })
      codeReaderRef.current = reader
      setVideoStream(stream)
      lastScannedCode.current = null

      // Esperar un momento para que el DOM se actualice y el video esté disponible
      await new Promise((resolve) => setTimeout(resolve, 100))

      if (scannerVideoRef.current) {
        scannerVideoRef.current.srcObject = stream
        scannerVideoRef.current.setAttribute('playsinline', 'true')
        scannerVideoRef.current.setAttribute('muted', 'true')
        await scannerVideoRef.current.play()
      }

      reader.decodeFromVideoDevice(null, scannerVideoRef.current as HTMLVideoElement, (result, err) => {
        if (result) {
          const scannedCode = result.getText()
          if (lastScannedCode.current === scannedCode) {
            return
          }
          lastScannedCode.current = scannedCode
          addCodeToItem(rowId, scannedCode, true)
        }
        if (err && !(err as any).closed) {
          if (!err.message || !err.message.toLowerCase().includes('no multiformat readers')) {
            // Silenciar errores esperados de escaneo
          }
        }
      })
    } catch (error) {
      console.error('Error al acceder a la cámara:', error)
      toast.error('No se pudo acceder a la cámara')
      stopScanning()
    }
  }

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()

    if (items.some((item) => !item.productId)) {
      toast.error('Selecciona un producto para cada ítem')
      return
    }

    if (items.some((item) => item.quantity <= 0 || Number.isNaN(item.quantity))) {
      toast.error('La cantidad debe ser mayor a 0')
      return
    }

    if (items.some((item) => item.unitPrice <= 0 || Number.isNaN(item.unitPrice))) {
      toast.error('El precio debe ser mayor a 0')
      return
    }

    if (items.some((item) => item.codes.length > 0 && item.codes.length !== item.quantity)) {
      toast.error('La cantidad de códigos únicos debe coincidir con la cantidad vendida en cada producto')
      return
    }

    stopScanning()

    setIsLoading(true)
    try {
      const savedSale = await onSave({
        customerId: customerId || null,
        customerName: !customerId && customerInputValue.trim() ? customerInputValue.trim() : null,
        status: 'completed',
        paymentMethod,
        subtotal,
        discount: Number(discount || 0),
        total,
        notes: notes.trim() || null,
        items: items.map((item) => ({
          productId: item.productId,
          quantity: item.quantity,
          unitPrice: item.unitPrice,
          subtotal: item.quantity * item.unitPrice,
          trackingCodes: item.codes,
        })),
      })

      // Solo imprimir si es una nueva venta (no edición)
      if (!sale && savedSale && typeof window !== 'undefined') {
        setTimeout(async () => {
          await generateSalePdfAndPrint(savedSale, customerSlug)
        }, 500)
      }
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[900px] max-h-[92vh] flex flex-col overflow-hidden p-0">
        <DialogHeader className="px-6 py-5 border-b border-gray-200 dark:border-gray-800 bg-white/95 dark:bg-[#111111]/95 backdrop-blur">
          <DialogTitle className="text-2xl font-semibold text-gray-900 dark:text-white">
            {sale ? 'Editar Venta' : 'Registrar Venta'}
          </DialogTitle>
          <DialogDescription className="text-gray-600 dark:text-gray-400">
            Completa la información de la venta y agrega los productos vendidos.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="flex flex-col flex-1 min-h-0">
          <div className="flex-1 overflow-y-auto px-6 py-6 space-y-6 bg-gray-50/60 dark:bg-[#0c0c0c]">
            <section className="space-y-3" ref={customerContainerRef}>
              <div className="space-y-2">
                <Label>Cliente</Label>
                <div className="relative">
                  <input
                    ref={customerInputRef}
                    type="text"
                    value={customerInputValue}
                    onChange={(e) => {
                      const formatted = e.target.value.length === 0 ? '' : capitalizeWords(e.target.value)
                      setCustomerInputValue(formatted)
                      setIsCustomerDropdownOpen(true)
                      setHighlightedCustomerIndex(0)
                      setCustomerId('')
                    }}
                    onFocus={() => setIsCustomerDropdownOpen(true)}
                    onKeyDown={handleCustomerKeyDown}
                    placeholder="Selecciona o escribe el nombre del cliente..."
                    disabled={isLoadingData}
                    className="w-full px-5 py-3 pr-20 border border-gray-200 dark:border-[#2a2a2a] rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[color-mix(in_oklch,var(--primary)_50%,white)] bg-white dark:bg-[#161616] text-gray-900 dark:text-white shadow-sm"
                  />
                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-2">
                    {customerInputValue && (
                      <button
                        onClick={clearCustomer}
                        className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"
                        type="button"
                        disabled={isLoadingData}
                      >
                        <X size={16} className="text-gray-500" />
                      </button>
                    )}
                    <button
                      onClick={() => setIsCustomerDropdownOpen(!isCustomerDropdownOpen)}
                      className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"
                      type="button"
                      disabled={isLoadingData}
                    >
                      <ChevronDown
                        size={16}
                        className={`text-gray-500 transition-transform ${isCustomerDropdownOpen ? 'rotate-180' : ''}`}
                      />
                    </button>
                  </div>

                  {isCustomerDropdownOpen && (
                    <div className="absolute left-0 right-0 mt-2 z-20 bg-white dark:bg-[#161616] border border-gray-200 dark:border-[#2a2a2a] rounded-2xl shadow-xl overflow-hidden">
                      <div className="max-h-64 overflow-y-auto">
                        {filteredCustomers.length > 0 ? (
                          filteredCustomers.map((customer, index) => (
                            <button
                              key={customer.id}
                              type="button"
                              onClick={() => selectCustomer(customer)}
                              onMouseEnter={() => setHighlightedCustomerIndex(index)}
                              className={`w-full text-left px-5 py-3 transition-colors ${
                                index === highlightedCustomerIndex
                                  ? 'bg-[color-mix(in_oklch,var(--primary)_18%,white)] text-gray-900 dark:text-white'
                                  : 'hover:bg-gray-100 dark:hover:bg-[#1f1f1f] text-gray-700 dark:text-gray-200'
                              }`}
                            >
                              <div className="font-semibold">{capitalizeWords(`${customer.name ?? ''} ${customer.lastName ?? ''}`.trim())}</div>
                              {customer.email && <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">{customer.email}</div>}
                            </button>
                          ))
                        ) : (
                          <div className="px-5 py-6 text-center text-gray-500 dark:text-gray-400">
                            {customerInputValue.trim()
                              ? `Presiona Enter para usar "${capitalizeWords(customerInputValue.trim())}"`
                              : 'No se encontraron clientes'}
                          </div>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </section>

            <section className="space-y-3">
              <div className="flex items-center justify-between">
                <h3 className="text-sm font-semibold uppercase tracking-wide text-gray-500 dark:text-gray-400">
                  Productos vendidos
                </h3>
                <Button type="button" variant="outline" size="sm" className="rounded-full" onClick={handleAddItem}>
                  <Plus className="h-4 w-4" />
                  Agregar producto
                </Button>
              </div>

              <div className="space-y-3">
                {items.map((item) => {
                  const selectedProduct = products.find((product) => product.id === item.productId)
                  return (
                    <div
                      key={item.id}
                      className="rounded-3xl border border-gray-200 dark:border-gray-800 bg-white dark:bg-[#111]/60 p-4 space-y-3"
                    >
                      <div className="grid gap-3 grid-cols-3">
                        <div className="space-y-2">
                          <Label>Producto</Label>
                          <Popover>
                            <PopoverTrigger asChild>
                              <Button
                                type="button"
                                variant="outline"
                                role="combobox"
                                className="w-full justify-between rounded-full"
                              >
                                {selectedProduct ? selectedProduct.name : 'Seleccionar producto'}
                                <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                              </Button>
                            </PopoverTrigger>
                            <PopoverContent className="w-[320px] p-0">
                              <Command>
                                <CommandInput placeholder="Buscar producto" />
                                <CommandList>
                                  <CommandEmpty>No se encontraron productos</CommandEmpty>
                                  <CommandGroup>
                                    {products.map((product) => (
                                      <CommandItem
                                        key={product.id}
                                        value={product.name}
                                        onSelect={() => handleProductSelect(item.id, product.id)}
                                      >
                                        <Check
                                          className={cn(
                                            'mr-2 h-4 w-4',
                                            product.id === item.productId ? 'opacity-100' : 'opacity-0',
                                          )}
                                        />
                                        <div className="flex flex-col">
                                          <span>{product.name}</span>
                                          <span className="text-xs text-gray-500">
                                            BOB {Number(product.price || 0).toLocaleString('es-BO', { minimumFractionDigits: 2 })}
                                          </span>
                                        </div>
                                      </CommandItem>
                                    ))}
                                  </CommandGroup>
                                </CommandList>
                              </Command>
                            </PopoverContent>
                          </Popover>
                        </div>

                        <div className="space-y-2">
                          <Label>Cantidad</Label>
                          <Input
                            type="number"
                            min="1"
                            value={item.quantity}
                            onChange={(e) => handleQuantityChange(item.id, Number(e.target.value) || 0)}
                            className="rounded-full"
                          />
                        </div>

                        <div className="space-y-2">
                          <Label>Precio unitario</Label>
                          <Input
                            type="number"
                            min="0"
                            step="0.01"
                            value={item.unitPrice}
                            onChange={(e) => handleUnitPriceChange(item.id, Number(e.target.value) || 0)}
                            className="rounded-full"
                          />
                        </div>
                      </div>

                      <div className="grid gap-3 grid-cols-3">
                        <div className="space-y-2">
                          <Label>Subtotal</Label>
                          <div className="text-sm font-semibold text-gray-900 dark:text-white">
                            BOB {(item.quantity * item.unitPrice).toLocaleString('es-BO', { minimumFractionDigits: 2 })}
                          </div>
                        </div>

                        <div className="space-y-2">
                          <Label>Códigos únicos</Label>
                          <Input
                            placeholder="Código o escaneo"
                            value={codeInputs[item.id] ?? ''}
                            onChange={(e) =>
                              setCodeInputs((prev) => ({
                                ...prev,
                                [item.id]: e.target.value,
                              }))
                            }
                            className="rounded-full"
                          />
                        </div>

                        <div className="flex items-end gap-2">
                          <Button
                            type="button"
                            variant="outline"
                            className="rounded-full"
                            onClick={() => handleManualCodeAdd(item.id)}
                            disabled={item.codes.length >= item.quantity}
                          >
                            Agregar
                          </Button>
                          <Button
                            type="button"
                            variant="outline"
                            className="rounded-full"
                            onClick={() => startScanningForItem(item.id)}
                            disabled={isLoadingData || item.codes.length >= item.quantity}
                          >
                            <ScanLine className="h-4 w-4" />
                            Escanear
                          </Button>
                          <Button
                            type="button"
                            variant="ghost"
                            size="icon"
                            className="rounded-full text-rose-600 hover:text-rose-700"
                            onClick={() => handleRemoveItem(item.id)}
                            disabled={items.length === 1}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>
                      {item.codes.length > 0 && (
                        <div className="flex flex-wrap gap-2">
                          {item.codes.map((code) => (
                            <span
                              key={`${item.id}-${code}`}
                              className="inline-flex items-center gap-1 rounded-full border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-white/10 px-3 py-1 text-xs font-medium text-gray-700 dark:text-gray-200"
                            >
                              #{code}
                              <button
                                type="button"
                                onClick={() => removeCodeFromItem(item.id, code)}
                                className="ml-1 text-gray-500 hover:text-rose-500 dark:text-gray-400 dark:hover:text-rose-400"
                              >
                                <X className="h-3 w-3" />
                              </button>
                            </span>
                          ))}
                        </div>
                      )}
                      {item.codes.length === 0 && (
                        <p className="text-xs text-gray-500 dark:text-gray-400">Sin códigos registrados.</p>
                      )}
                      {item.codes.length > 0 && item.codes.length < item.quantity && (
                        <p className="text-xs text-amber-600 dark:text-amber-400">
                          Faltan {item.quantity - item.codes.length} códigos para coincidir con la cantidad vendida.
                        </p>
                      )}
                    </div>
                  )
                })}
              </div>
            </section>

            <section className="grid gap-4 grid-cols-4">
              <div className="space-y-2">
                <Label>Subtotal</Label>
                <Input value={`BOB ${subtotal.toLocaleString('es-BO', { minimumFractionDigits: 2 })}`} readOnly className="rounded-full" />
              </div>
              <div className="space-y-2">
                <Label>Descuento</Label>
                <Input
                  type="number"
                  min="0"
                  step="0.01"
                  value={discount}
                  onFocus={() => {
                    if (discount === '0' || discount === '0.00') {
                      setDiscount('')
                    }
                  }}
                  onChange={(e) => setDiscount(e.target.value)}
                  className="rounded-full"
                />
              </div>
              <div className="space-y-2">
                <Label>Total</Label>
                <Input value={`BOB ${total.toLocaleString('es-BO', { minimumFractionDigits: 2 })}`} readOnly className="rounded-full" />
              </div>
              <div className="space-y-2">
                <Label>Método de pago</Label>
                <Select value={paymentMethod} onValueChange={setPaymentMethod}>
                  <SelectTrigger className="rounded-full w-full">
                    <SelectValue placeholder="Seleccionar" />
                  </SelectTrigger>
                  <SelectContent className="rounded-2xl">
                    {paymentOptions.map((option) => (
                      <SelectItem key={option.value} value={option.value}>
                        {option.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </section>

            <section className="grid gap-4">
              <div className="space-y-2">
                <Label>Notas</Label>
                <Textarea
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  placeholder="Comentarios adicionales, condiciones, etc."
                  className="min-h-[110px] rounded-3xl resize-none"
                />
              </div>
            </section>
          </div>

          <DialogFooter className="flex w-full justify-center sm:justify-center items-center gap-3 border-t border-gray-200 dark:border-[#2a2a2a] px-6 py-4 bg-white/95 dark:bg-[#111111]/95 backdrop-blur">
            <Button type="button" variant="outline" className="rounded-full" onClick={() => onOpenChange(false)} disabled={isLoading}>
              Cancelar
            </Button>
            <Button
              type="submit"
              variant="new"
              className="rounded-full"
              disabled={
                isLoading ||
                items.some((item) => !item.productId) ||
                subtotal <= 0 ||
                total < 0 ||
                items.some((item) => item.codes.length > 0 && item.codes.length !== item.quantity) ||
                isLoadingData
              }
            >
              {isLoading ? 'Guardando...' : sale ? 'Actualizar venta' : 'Registrar venta'}
            </Button>
          </DialogFooter>
        </form>

        {isScanning && (
          <div className="fixed inset-0 z-[120] flex items-center justify-center">
            <div className="absolute inset-0 bg-black/70" onClick={stopScanning} />
            <div className="relative z-[121] flex flex-col items-center gap-4">
              <video
                ref={scannerVideoRef}
                className="w-72 h-72 rounded-3xl border-4 border-white object-cover shadow-2xl"
                autoPlay
                muted
                playsInline
              />
              <Button type="button" variant="secondary" className="rounded-full" onClick={stopScanning}>
                Detener escaneo
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { FileText, CheckCircle2, Clock, DollarSign, Sparkles, ArrowUpRight, ArrowDownRight } from "lucide-react"

import { SalesSaleWithRelations } from "./types"

import { Badge } from "@/components/ui/badge"
import { Card, CardContent } from "@/components/ui/card"

interface SalesStatsProps {
  sales: SalesSaleWithRelations[]
  isLoading?: boolean
}

interface StatCardConfig {
  key: keyof ReturnType<typeof getStats>["values"]
  label: string
  icon: React.ComponentType<React.SVGProps<SVGSVGElement>>
  accentColor: string
  bgGradient: string
  iconBg: string
}

const statCards: StatCardConfig[] = [
  {
    key: "total",
    label: "Total Ventas",
    icon: FileText,
    accentColor: "text-blue-600 dark:text-blue-400",
    bgGradient: "from-blue-50/50 to-blue-100/30 dark:from-blue-950/20 dark:to-blue-900/10",
    iconBg: "bg-gradient-to-br from-blue-500 to-blue-600 dark:from-blue-600 dark:to-blue-700",
  },
  {
    key: "completed",
    label: "Completadas",
    icon: CheckCircle2,
    accentColor: "text-emerald-600 dark:text-emerald-400",
    bgGradient: "from-emerald-50/50 to-emerald-100/30 dark:from-emerald-950/20 dark:to-emerald-900/10",
    iconBg: "bg-gradient-to-br from-emerald-500 to-emerald-600 dark:from-emerald-600 dark:to-emerald-700",
  },
  {
    key: "cancelled",
    label: "Anuladas",
    icon: Clock,
    accentColor: "text-rose-600 dark:text-rose-400",
    bgGradient: "from-rose-50/50 to-rose-100/30 dark:from-rose-950/20 dark:to-rose-900/10",
    iconBg: "bg-gradient-to-br from-rose-500 to-rose-600 dark:from-rose-600 dark:to-rose-700",
  },
  {
    key: "totalAmount",
    label: "Monto Total",
    icon: DollarSign,
    accentColor: "text-violet-600 dark:text-violet-400",
    bgGradient: "from-violet-50/50 to-violet-100/30 dark:from-violet-950/20 dark:to-violet-900/10",
    iconBg: "bg-gradient-to-br from-violet-500 to-violet-600 dark:from-violet-600 dark:to-violet-700",
  },
]

const getStats = (sales: SalesSaleWithRelations[]) => {
  const total = sales.length
  
  // Calcular montos por estado
  const completedSales = sales.filter((sale) => sale.status === 'completed')
  const cancelledSales = sales.filter((sale) => sale.status === 'cancelled')
  
  const completed = completedSales.length
  const cancelled = cancelledSales.length
  
  const completedAmount = completedSales.reduce((sum, sale) => sum + Number(sale.total || 0), 0)
  const cancelledAmount = cancelledSales.reduce((sum, sale) => sum + Number(sale.total || 0), 0)
  const netAmount = completedAmount - cancelledAmount // Diferencia entre completadas y anuladas

  const now = new Date()
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1)
  const monthSales = sales.filter((sale) => (sale.createdAt ? new Date(sale.createdAt) >= startOfMonth : false))
  const monthAmount = monthSales.reduce((sum, sale) => sum + Number(sale.total || 0), 0)

  const completedRate = total === 0 ? 0 : (completed / total) * 100
  const cancelledRate = total === 0 ? 0 : (cancelled / total) * 100

  return {
    total,
    values: {
      total: {
        value: total,
        helper: `${monthSales.length} registradas este mes` ,
        trend: total === 0 ? 0 : (monthSales.length / total) * 100,
        isPositive: true,
      },
      completed: {
        value: completed,
        amount: completedAmount,
        helper: `${completedRate.toFixed(1)}% del total`,
        trend: completedRate,
        isPositive: true,
      },
      cancelled: {
        value: cancelled,
        amount: cancelledAmount,
        helper: `${cancelledRate.toFixed(1)}% del total`,
        trend: cancelledRate,
        isPositive: cancelled === 0,
      },
      totalAmount: {
        value: netAmount,
        helper: `Mes: BOB ${monthAmount.toLocaleString('es-BO', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`,
        trend: monthAmount,
        isPositive: true,
      },
    },
  }
}

export function SalesStats({ sales, isLoading = false }: SalesStatsProps) {
  const stats = getStats(sales)

  return (
    <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
      {statCards.map(({ key, label, icon: Icon, accentColor, bgGradient, iconBg }) => {
        const stat = stats.values[key]
        
        // Determinar el valor a mostrar
        let displayValue: string | number = stat.value
        let showCurrency = false
        
        if (key === 'totalAmount') {
          displayValue = `${Number(stat.value || 0).toLocaleString('es-BO', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
          showCurrency = true
        } else if (key === 'completed' || key === 'cancelled') {
          // Mostrar cantidad + monto
          const amount = (stat as any).amount || 0
          displayValue = stat.value
        }

        const TrendIcon = stat.isPositive ? ArrowUpRight : ArrowDownRight
        const trendColor = stat.isPositive
          ? "text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/30"
          : "text-rose-600 dark:text-rose-400 bg-rose-50 dark:bg-rose-950/30"

        const showAmount = (key === 'completed' || key === 'cancelled') && (stat as any).amount !== undefined

        return (
          <Card
            key={key}
            className={`relative overflow-hidden border border-gray-200/60 dark:border-gray-800/60
              bg-gradient-to-br ${bgGradient} backdrop-blur-sm
              hover:shadow-lg hover:shadow-gray-900/5 dark:hover:shadow-black/20
              transition-all duration-300 hover:-translate-y-0.5`}
          >
            <CardContent className="relative p-4 sm:p-5 space-y-3">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <p className="text-[11px] font-semibold uppercase tracking-wider text-gray-600 dark:text-gray-400">
                    {label}
                  </p>
                  {key === 'total' && (
                    <Badge
                      variant="secondary"
                      className="mt-1 text-[9px] font-medium px-2 py-0.5 bg-white/60 dark:bg-white/10 border-0"
                    >
                      <Sparkles className="h-2.5 w-2.5 mr-1" />
                      Panorama General
                    </Badge>
                  )}
                </div>
                <div className={`${iconBg} w-10 h-10 rounded-xl shadow-lg flex items-center justify-center`}>
                  <Icon className="h-4.5 w-4.5 text-white" strokeWidth={2.3} />
                </div>
              </div>

              <div>
                <div className={`text-2xl sm:text-3xl font-bold ${accentColor} tracking-tight flex items-baseline gap-1.5`}>
                  {isLoading ? (
                    <span className="text-gray-400">--</span>
                  ) : (
                    <>
                      {showCurrency && (
                        <span className="text-sm font-semibold">BOB</span>
                      )}
                      {displayValue}
                    </>
                  )}
                </div>
                {showAmount && (
                  <div className="text-sm font-semibold text-gray-600 dark:text-gray-400 mt-1">
                    BOB {Number((stat as any).amount || 0).toLocaleString('es-BO', { minimumFractionDigits: 2 })}
                  </div>
                )}
              </div>

              <div className="flex items-center justify-between">
                <p className="text-[11px] text-gray-600 dark:text-gray-400 font-medium">
                  {isLoading ? 'Calculando...' : stat.helper}
                </p>
                {!isLoading && Number(stat.trend || 0) > 0 && (
                  <div className={`flex items-center gap-1 px-2 py-0.5 rounded-md ${trendColor} text-[10px] font-semibold`}>
                    <TrendIcon className="h-3 w-3" strokeWidth={3} />
                    {typeof stat.trend === 'number' ? stat.trend.toFixed(1) : stat.trend}
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        )
      })}
    </div>
  )
}

"use client"

import { ChevronLeft, ChevronRight } from "lucide-react"

import { Button } from "@/components/ui/button"

interface UsuariosSasPaginationProps {
  currentPage: number
  totalPages: number
  pageSize: number
  onPageChange: (page: number) => void
  onPageSizeChange: (size: number) => void
}

export function UsuariosSasPagination({
  currentPage,
  totalPages,
  pageSize,
  onPageChange,
  onPageSizeChange
}: UsuariosSasPaginationProps) {
  const handlePrevious = () => {
    if (currentPage > 1) {
      onPageChange(currentPage - 1)
    }
  }

  const handleNext = () => {
    if (currentPage < totalPages) {
      onPageChange(currentPage + 1)
    }
  }

  if (totalPages <= 1) return null

  return (
    <div className="flex items-center justify-center gap-4 py-4">
      <div className="text-sm text-gray-600 dark:text-gray-400">
        Página {currentPage} de {totalPages}
      </div>
      <div className="flex gap-2">
        <Button
          variant="outline"
          size="sm"
          onClick={handlePrevious}
          disabled={currentPage === 1}
          className="rounded-full"
        >
          <ChevronLeft className="h-4 w-4" />
          Anterior
        </Button>
        <Button
          variant="outline"
          size="sm"
          onClick={handleNext}
          disabled={currentPage === totalPages}
          className="rounded-full"
        >
          Siguiente
          <ChevronRight className="h-4 w-4" />
        </Button>
      </div>
    </div>
  )
}

"use client"

import { AlertTriangle, Trash2, Info } from 'lucide-react'
import * as React from 'react'

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'

interface ConfirmDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onConfirm: () => void
  title: string
  description: string
  confirmText?: string
  cancelText?: string
  variant?: 'default' | 'destructive' | 'warning'
  isLoading?: boolean
}

export function ConfirmDialog({
  open,
  onOpenChange,
  onConfirm,
  title,
  description,
  confirmText = 'Confirmar',
  cancelText = 'Cancelar',
  variant = 'default',
  isLoading = false,
}: ConfirmDialogProps) {
  const Icon = variant === 'destructive' ? Trash2 : variant === 'warning' ? AlertTriangle : Info

  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <div className="flex items-center gap-2">
            <Icon
              className={`h-5 w-5 ${
                variant === 'destructive'
                  ? 'text-destructive'
                  : variant === 'warning'
                  ? 'text-yellow-500'
                  : 'text-primary'
              }`}
            />
            <AlertDialogTitle>{title}</AlertDialogTitle>
          </div>
          <AlertDialogDescription>{description}</AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={isLoading}>{cancelText}</AlertDialogCancel>
          <AlertDialogAction
            onClick={onConfirm}
            disabled={isLoading}
            className={
              variant === 'destructive'
                ? 'bg-destructive hover:bg-destructive/90'
                : variant === 'warning'
                ? 'bg-yellow-500 hover:bg-yellow-600'
                : ''
            }
          >
            {isLoading ? 'Procesando...' : confirmText}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

// Hook para usar confirmaciones fácilmente
export function useConfirm() {
  const [state, setState] = React.useState<{
    open: boolean
    title: string
    description: string
    onConfirm: (() => void) | null
    variant?: 'default' | 'destructive' | 'warning'
  }>({
    open: false,
    title: '',
    description: '',
    onConfirm: null,
    variant: 'default',
  })

  const confirm = React.useCallback(
    (
      title: string,
      description: string,
      onConfirm: () => void | Promise<void>,
      variant: 'default' | 'destructive' | 'warning' = 'default'
    ) => {
      setState({
        open: true,
        title,
        description,
        onConfirm: () => {
          Promise.resolve(onConfirm()).then(() => {
            setState((prev) => ({ ...prev, open: false, onConfirm: null }))
          })
        },
        variant,
      })
    },
    []
  )

  const handleConfirm = React.useCallback(() => {
    state.onConfirm?.()
  }, [state.onConfirm])

  const Dialog = React.useMemo(
    () => (
      <ConfirmDialog
        open={state.open}
        onOpenChange={(open) => setState((prev) => ({ ...prev, open }))}
        onConfirm={handleConfirm}
        title={state.title}
        description={state.description}
        variant={state.variant}
      />
    ),
    [state, handleConfirm]
  )

  return { confirm, Dialog }
}

