'use client'

// Inspired by react-hot-toast library
import * as React from 'react'

import type { ToastActionElement, ToastProps } from '@/components/ui/toast'

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: 'ADD_TOAST',
  UPDATE_TOAST: 'UPDATE_TOAST',
  DISMISS_TOAST: 'DISMISS_TOAST',
  REMOVE_TOAST: 'REMOVE_TOAST',
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType['ADD_TOAST']
      toast: ToasterToast
    }
  | {
      type: ActionType['UPDATE_TOAST']
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType['DISMISS_TOAST']
      toastId?: ToasterToast['id']
    }
  | {
      type: ActionType['REMOVE_TOAST']
      toastId?: ToasterToast['id']
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: 'REMOVE_TOAST',
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case 'ADD_TOAST':
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case 'UPDATE_TOAST':
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t,
        ),
      }

    case 'DISMISS_TOAST': {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t,
        ),
      }
    }
    case 'REMOVE_TOAST':
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, 'id'>

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: 'UPDATE_TOAST',
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: 'DISMISS_TOAST', toastId: id })

  dispatch({
    type: 'ADD_TOAST',
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: 'DISMISS_TOAST', toastId }),
  }
}

export { useToast, toast }

"use client"

import { createContext, useContext, useState, useEffect, ReactNode } from 'react'

interface PermissionsContextType {
  permissions: string[]
  isSuperAdmin: boolean
  isLoading: boolean
  refreshPermissions: () => Promise<void>
}

const PermissionsContext = createContext<PermissionsContextType>({
  permissions: [],
  isSuperAdmin: false,
  isLoading: true,
  refreshPermissions: async () => {},
})

const PERMISSIONS_CACHE_KEY = 'admin-permissions-cache'
const PERMISSIONS_CACHE_TIMESTAMP_KEY = 'admin-permissions-cache-timestamp'
const CACHE_DURATION = 5 * 60 * 1000 // 5 minutos

interface PermissionsCache {
  permissions: string[]
  isSuperAdmin: boolean
  timestamp: number
}

export function PermissionsProvider({ children }: { children: ReactNode }) {
  const [permissions, setPermissions] = useState<string[]>([])
  const [isSuperAdmin, setIsSuperAdmin] = useState(false)
  const [isLoading, setIsLoading] = useState(true)

  const loadPermissionsFromCache = (): PermissionsCache | null => {
    if (typeof window === 'undefined') return null
    
    try {
      const cached = sessionStorage.getItem(PERMISSIONS_CACHE_KEY)
      const timestamp = sessionStorage.getItem(PERMISSIONS_CACHE_TIMESTAMP_KEY)
      
      if (cached && timestamp) {
        const cacheData: PermissionsCache = JSON.parse(cached)
        const cacheTime = parseInt(timestamp, 10)
        const now = Date.now()
        
        // Si el caché es válido (menos de 5 minutos)
        if (now - cacheTime < CACHE_DURATION) {
          return cacheData
        }
      }
    } catch (error) {
      console.error('Error loading permissions from cache:', error)
    }
    
    return null
  }

  const savePermissionsToCache = (data: PermissionsCache) => {
    if (typeof window === 'undefined') return
    
    try {
      sessionStorage.setItem(PERMISSIONS_CACHE_KEY, JSON.stringify(data))
      sessionStorage.setItem(PERMISSIONS_CACHE_TIMESTAMP_KEY, Date.now().toString())
    } catch (error) {
      console.error('Error saving permissions to cache:', error)
    }
  }

  const clearPermissionsCache = () => {
    if (typeof window === 'undefined') return
    
    try {
      sessionStorage.removeItem(PERMISSIONS_CACHE_KEY)
      sessionStorage.removeItem(PERMISSIONS_CACHE_TIMESTAMP_KEY)
    } catch (error) {
      console.error('Error clearing permissions cache:', error)
    }
  }

  const fetchPermissions = async () => {
    try {
      const response = await fetch('/api/administracion/auth/permissions', {
        credentials: 'include',
      })
      
      if (response.ok) {
        const data = await response.json()
        const permissionsData = {
          permissions: data.permissions || [],
          isSuperAdmin: data.isSuperAdmin || false,
          timestamp: Date.now(),
        }
        
        setPermissions(permissionsData.permissions)
        setIsSuperAdmin(permissionsData.isSuperAdmin)
        savePermissionsToCache(permissionsData)
      } else {
        // Si no hay sesión, limpiar caché
        clearPermissionsCache()
        setPermissions([])
        setIsSuperAdmin(false)
      }
    } catch (error) {
      console.error('Error fetching permissions:', error)
      // En caso de error, intentar usar caché
      const cached = loadPermissionsFromCache()
      if (cached) {
        setPermissions(cached.permissions)
        setIsSuperAdmin(cached.isSuperAdmin)
      } else {
        setPermissions([])
        setIsSuperAdmin(false)
      }
    } finally {
      setIsLoading(false)
    }
  }

  const refreshPermissions = async () => {
    clearPermissionsCache()
    setIsLoading(true)
    await fetchPermissions()
  }

  useEffect(() => {
    // Primero intentar cargar desde caché para mostrar inmediatamente
    const cached = loadPermissionsFromCache()
    if (cached) {
      setPermissions(cached.permissions)
      setIsSuperAdmin(cached.isSuperAdmin)
      setIsLoading(false)
    }
    
    // Luego hacer fetch para actualizar
    fetchPermissions()
  }, [])

  return (
    <PermissionsContext.Provider
      value={{
        permissions,
        isSuperAdmin,
        isLoading,
        refreshPermissions,
      }}
    >
      {children}
    </PermissionsContext.Provider>
  )
}

export function usePermissionsContext() {
  return useContext(PermissionsContext)
}

"use client"

import { useRouter } from "next/navigation"
import { useState, useTransition } from "react"
import { toast } from "sonner"

import { Customer } from "@/lib/types"

export function useCustomerActions() {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [isFormDialogOpen, setIsFormDialogOpen] = useState(false)
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const [isDetailDialogOpen, setIsDetailDialogOpen] = useState(false)
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | undefined>()
  const [customerDetails, setCustomerDetails] = useState<any>(null)
  const [isLoadingDetails, setIsLoadingDetails] = useState(false)

  const openCreateDialog = () => {
    setSelectedCustomer(undefined)
    setIsFormDialogOpen(true)
  }

  const openEditDialog = (customer: Customer) => {
    setSelectedCustomer(customer)
    setIsFormDialogOpen(true)
  }

  const openDeleteDialog = (customer: Customer) => {
    setSelectedCustomer(customer)
    setIsDeleteDialogOpen(true)
  }

  const openDetailDialog = async (customer: Customer) => {
    setSelectedCustomer(customer)
    setIsDetailDialogOpen(true)
    setIsLoadingDetails(true)
    
    try {
      const response = await fetch(`/api/administracion/customers/${customer.id}`)
      if (response.ok) {
        const details = await response.json()
        setCustomerDetails(details)
      } else {
        toast.error("Error al cargar los detalles del cliente")
      }
    } catch (error) {
      console.error("Error al cargar detalles:", error)
      toast.error("Error al cargar los detalles del cliente")
    } finally {
      setIsLoadingDetails(false)
    }
  }

  const closeDialogs = () => {
    setIsFormDialogOpen(false)
    setIsDeleteDialogOpen(false)
    setIsDetailDialogOpen(false)
    setSelectedCustomer(undefined)
    setCustomerDetails(null)
  }

  const handleSave = async (data: any) => {
    try {
      const url = selectedCustomer
        ? `/api/administracion/customers/${selectedCustomer.id}`
        : "/api/administracion/customers"

      const method = selectedCustomer ? "PUT" : "POST"

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      })

      if (!response.ok) {
        throw new Error("Error al guardar el cliente")
      }

      const message = selectedCustomer ? "Cliente actualizado" : "Cliente creado"
      toast.success(message)
      closeDialogs()
      
      startTransition(() => {
        router.refresh()
      })
    } catch (error) {
      toast.error("Error al guardar el cliente")
    }
  }

  const handleDelete = async () => {
    if (!selectedCustomer) return

    try {
      const response = await fetch(`/api/administracion/customers/${selectedCustomer.id}`, {
        method: "DELETE",
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        const errorMessage = errorData.message || errorData.error || "Error al eliminar el cliente"
        throw new Error(errorMessage)
      }

      toast.success("Cliente eliminado exitosamente")
      closeDialogs()
      
      startTransition(() => {
        router.refresh()
      })
    } catch (error: any) {
      console.error("Error al eliminar cliente:", error)
      toast.error(error.message || "Error al eliminar el cliente")
    }
  }

  const handleToggleStatus = async (customer: Customer) => {
    try {
      const newStatus = !customer.isActive
      const response = await fetch(`/api/administracion/customers/${customer.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isActive: newStatus }),
      })

      if (!response.ok) {
        throw new Error("Error al cambiar el estado del cliente")
      }

      toast.success(newStatus ? "Cliente activado" : "Cliente desactivado")
      
      startTransition(() => {
        router.refresh()
      })
    } catch (error) {
      toast.error("Error al cambiar el estado del cliente")
    }
  }

  return {
    isFormDialogOpen,
    isDeleteDialogOpen,
    isDetailDialogOpen,
    setIsDetailDialogOpen,
    selectedCustomer,
    customerDetails,
    isLoadingDetails,
    openCreateDialog,
    openEditDialog,
    openDeleteDialog,
    openDetailDialog,
    closeDialogs,
    handleSave,
    handleDelete,
    handleToggleStatus
  }
}

