  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false)
  const [selectedOrganization, setSelectedOrganization] = useState<any>(undefined)
  const [deleteDialog, setDeleteDialog] = useState({ open: false, organizationId: '', organizationName: '' })

  const handleNewClick = () => {
    setSelectedOrganization(undefined)
    setOpenDialog(true)
  }

  const handleEdit = async (organizationId: string) => {
    try {
      const response = await fetch(`/api/administracion/organizations/${organizationId}`)
      if (response.ok) {
        const organization = await response.json()
        setSelectedOrganization(organization)
        setIsEditDialogOpen(true)
      } else {
        throw new Error("Error al cargar la organización")
      }
    } catch (error: any) {
      toast.error("Error al cargar la organización", {
        description: error.message || "No se pudo cargar la organización",
        duration: 5000,
      })
    }
  }

  const handleDeleteClick = (organizationId: string, organizationName: string) => {
    setDeleteDialog({ open: true, organizationId, organizationName })
  }

  const handleSave = async (data: any) => {
    try {
      const url = selectedOrganization 
        ? `/api/administracion/organizations/${selectedOrganization.id}`
        : '/api/administracion/organizations'
      
      const method = selectedOrganization ? 'PUT' : 'POST'

      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(data),
      })

      if (!response.ok) {
        const errorData = await response.json()
        throw new Error(errorData.error || 'Error al guardar la organización')
      }

      const result = await response.json()
      const updatedOrganization = result.organization || result
      
      if (selectedOrganization) {
        setIsEditDialogOpen(false)
      } else {
        setOpenDialog(false)
      }
      setSelectedOrganization(undefined)
      
      // Disparar evento para recargar organizaciones
      window.dispatchEvent(new Event('organization-updated'))
      
      // Mostrar toast de éxito
      const orgName = data.razonSocial || data.name || 'Organización'
      if (selectedOrganization) {
        toast.success('Organización actualizada', {
          description: `${orgName} ha sido actualizada exitosamente.`,
          duration: 3000,
        })
      } else {
        toast.success('Organización creada', {
          description: `${orgName} ha sido creada exitosamente.`,
          duration: 3000,
        })
      }
      
      startTransition(() => {
        router.refresh()
      })
    } catch (error: any) {
      console.error("Error al guardar la organización:", error)
      const errorMessage = error.message || 'Ocurrió un error inesperado al guardar la organización.'
      toast.error('Error al guardar la organización', {
        description: errorMessage,
        duration: 5000,
      })
      throw error
    }
  }

  const handleToggleStatus = async (organizationId: string, isActive: boolean) => {
    try {
      const response = await fetch(`/api/administracion/organizations/${organizationId}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ isActive }),
      })

      if (!response.ok) {
        const errorData = await response.json()
        throw new Error(errorData.error || 'Error al cambiar el estado de la organización')
      }

      toast.success(isActive ? 'Organización activada' : 'Organización desactivada', {
        description: `La organización ha sido ${isActive ? 'activada' : 'desactivada'} exitosamente.`,
        duration: 3000,
      })

      // Disparar evento para recargar organizaciones
      window.dispatchEvent(new Event('organization-updated'))

      startTransition(() => {
        router.refresh()
      })
    } catch (error: any) {
      console.error("Error al cambiar el estado de la organización:", error)
      toast.error('Error al cambiar estado', {
        description: error.message || 'No se pudo cambiar el estado de la organización.',
        duration: 5000,
      })
    }
  }

  const handleDeleteConfirm = async () => {
    try {
      const response = await fetch(`/api/administracion/organizations/${deleteDialog.organizationId}`, {
        method: 'DELETE',
      })

      if (!response.ok) {
        const errorData = await response.json()
        throw new Error(errorData.error || 'Error al eliminar la organización')
      }

      toast.success('Organización eliminada', {
        description: `${deleteDialog.organizationName || 'La organización'} ha sido eliminada exitosamente.`,
        duration: 3000,
      })

      setDeleteDialog({ open: false, organizationId: '', organizationName: '' })

      // Disparar evento para recargar organizaciones
      window.dispatchEvent(new Event('organization-updated'))

      startTransition(() => {
        router.refresh()
      })
    } catch (error: any) {
      console.error("Error al eliminar la organización:", error)
      const errorMessage = error.message || 'No se pudo eliminar la organización. Intente nuevamente.'
      setDeleteDialog({ open: false, organizationId: '', organizationName: '' })
      toast.error('Error al eliminar la organización', {
        description: errorMessage,
        duration: 5000,
      })
      throw error
    }
  }

  return {
    openDialog,
    setOpenDialog,
    isEditDialogOpen,
    setIsEditDialogOpen,
    selectedOrganization,
    setSelectedOrganization,
    deleteDialog,
    setDeleteDialog,
    handleNewClick,
    handleEdit,
    handleSave,
    handleToggleStatus,
    handleDeleteClick,
    handleDeleteConfirm,
    isPending,
  }
}

/**
 * Hook personalizado para manejo de errores de API
 * 
 * Estandariza el manejo de errores en componentes React
 */

"use client"

import { useState, useCallback } from 'react'
import { toast } from 'sonner'

import { logger } from '@/lib/utils/logger'

export interface ApiError {
  message: string
  code?: string
  details?: any
}

export interface UseApiErrorReturn {
  error: ApiError | null
  setError: (error: ApiError | null) => void
  handleError: (error: unknown, options?: HandleErrorOptions) => void
  clearError: () => void
  isError: boolean
}

export interface HandleErrorOptions {
  showToast?: boolean
  toastTitle?: string
  logError?: boolean
  onError?: (error: ApiError) => void
}

/**
 * Hook para manejar errores de API de forma consistente
 */
export function useApiError(): UseApiErrorReturn {
  const [error, setError] = useState<ApiError | null>(null)

  const handleError = useCallback(
    (error: unknown, options: HandleErrorOptions = {}) => {
      const {
        showToast = true,
        toastTitle = 'Error',
        logError = true,
        onError,
      } = options

      // Extraer mensaje de error
      let errorMessage = 'Ha ocurrido un error'
      let errorCode: string | undefined
      let errorDetails: any = undefined

      if (error instanceof Error) {
        errorMessage = error.message
        errorDetails = { stack: error.stack }
      } else if (typeof error === 'object' && error !== null) {
        const err = error as any
        errorMessage = err.message || err.error || errorMessage
        errorCode = err.code
        errorDetails = err.details || err.data
      } else if (typeof error === 'string') {
        errorMessage = error
      }

      // Crear objeto de error
      const apiError: ApiError = {
        message: errorMessage,
        code: errorCode,
        details: errorDetails,
      }

      // Actualizar estado
      setError(apiError)

      // Loggear error (si está habilitado)
      if (logError) {
        const logData: Record<string, any> = {}
        if (errorCode) logData.code = errorCode
        if (errorDetails) logData.details = errorDetails
        
        logger.error('API Error en frontend', error instanceof Error ? error : new Error(errorMessage), Object.keys(logData).length > 0 ? logData : undefined)
      }

      // Mostrar toast (si está habilitado)
      if (showToast) {
        toast.error(toastTitle, {
          description: errorMessage,
        })
      }

      // Callback personalizado
      if (onError) {
        onError(apiError)
      }
    },
    []
  )

  const clearError = useCallback(() => {
    setError(null)
  }, [])

  return {
    error,
    setError,
    handleError,
    clearError,
    isError: error !== null,
  }
}

/**
 * Helper para extraer mensaje de error de una respuesta fetch
 */
export async function extractErrorFromResponse(response: Response): Promise<string> {
  try {
    const data = await response.json()
    return data.error || data.message || `Error ${response.status}: ${response.statusText}`
  } catch {
    return `Error ${response.status}: ${response.statusText}`
  }
}

/**
 * Helper para manejar errores de fetch
 */
export async function handleFetchError(
  response: Response,
  options?: HandleErrorOptions
): Promise<never> {
  const errorMessage = await extractErrorFromResponse(response)
  throw new Error(errorMessage)
}

"use client"

import { Branch } from "@prisma/client"
import { useRouter } from "next/navigation"
import { useState, useTransition } from "react"
import { toast } from "sonner"

type BranchWithRelations = Branch & {
  organization?: { id: string; razonSocial: string | null; name: string | null; slug: string | null } | null
  _count?: { usuariosSas: number }
}

export function useBranchActions(
  customerSlug: string,
  setBranches?: (branches: BranchWithRelations[] | ((prev: BranchWithRelations[]) => BranchWithRelations[])) => void
) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [isFormDialogOpen, setIsFormDialogOpen] = useState(false)
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const [isDetailDialogOpen, setIsDetailDialogOpen] = useState(false)
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [confirmTitle, setConfirmTitle] = useState('')
  const [confirmDesc, setConfirmDesc] = useState<string>('')
  const [confirmColor, setConfirmColor] = useState<'red'|'orange'|'green'>('orange')
  const [pendingAction, setPendingAction] = useState<(() => Promise<void>) | null>(null)
  const [selectedBranch, setSelectedBranch] = useState<BranchWithRelations | undefined>()

  const openCreateDialog = () => {
    setSelectedBranch(undefined)
    setIsFormDialogOpen(true)
  }

  const openViewDetailsDialog = (branch: BranchWithRelations) => {
    setSelectedBranch(branch)
    setIsDetailDialogOpen(true)
  }

  const openEditDialog = (branch: BranchWithRelations) => {
    setSelectedBranch(branch)
    setIsFormDialogOpen(true)
  }

  const openDeleteDialog = (branch: BranchWithRelations) => {
    setSelectedBranch(branch)
    setIsDeleteDialogOpen(true)
  }

  const openDetailDialog = (branch: BranchWithRelations) => {
    setSelectedBranch(branch)
    setIsDetailDialogOpen(true)
  }

  const closeDialogs = () => {
    setIsFormDialogOpen(false)
    setIsDeleteDialogOpen(false)
    setIsDetailDialogOpen(false)
    setConfirmOpen(false)
    setSelectedBranch(undefined)
  }

  const handleSave = async (data: any) => {
    try {
      const url = selectedBranch
        ? `/api/${customerSlug}/sucursales/${selectedBranch.id}`
        : `/api/${customerSlug}/sucursales`

      const method = selectedBranch ? "PUT" : "POST"

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.error || "Error al guardar la sucursal")
      }

      const savedBranch = await response.json()
      const message = selectedBranch ? "Sucursal actualizada" : "Sucursal creada"
      toast.success(message)
      closeDialogs()
      
      // Actualizar estado local en tiempo real
      if (setBranches) {
        if (selectedBranch) {
          // Actualizar sucursal existente
          setBranches((prevBranches) =>
            prevBranches.map((branch) =>
              branch.id === selectedBranch.id ? { ...branch, ...savedBranch } : branch
            )
          )
        } else {
          // Agregar nueva sucursal
          setBranches((prevBranches) => [savedBranch, ...prevBranches])
        }
      } else {
        // Fallback a router.refresh si no hay setBranches
        startTransition(() => {
          router.refresh()
        })
      }
    } catch (error: any) {
      toast.error(error.message || "Error al guardar la sucursal")
    }
  }

  const handleDelete = async () => {
    if (!selectedBranch) return

    try {
      const response = await fetch(`/api/${customerSlug}/sucursales/${selectedBranch.id}`, {
        method: "DELETE",
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.error || "Error al eliminar la sucursal")
      }

      toast.success("Sucursal eliminada")
      closeDialogs()
      
      // Actualizar estado local en tiempo real
      if (setBranches) {
        setBranches((prevBranches) => prevBranches.filter((branch) => branch.id !== selectedBranch.id))
      } else {
        startTransition(() => {
          router.refresh()
        })
      }
    } catch (error: any) {
      toast.error(error.message || "Error al eliminar la sucursal")
    }
  }

  const handleToggleStatus = async (branch: BranchWithRelations) => {
    const newStatus = !branch.isActive
    const count = branch?._count?.usuariosSas || 0
    
    // Función para actualizar el estado de la sucursal
    const updateBranchStatus = async () => {
      const response = await fetch(`/api/${customerSlug}/sucursales/${branch.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isActive: newStatus }),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.error || "Error al cambiar el estado de la sucursal")
      }

      const updatedBranch = await response.json()
      
      // Actualizar estado local en tiempo real
      if (setBranches) {
        setBranches((prevBranches) =>
          prevBranches.map((b) =>
            b.id === branch.id ? { ...b, isActive: newStatus, ...updatedBranch } : b
          )
        )
      }
      
      toast.success(newStatus ? "Sucursal activada" : "Sucursal desactivada")
    }
    
    // Si está desactivando y no tiene usuarios asignados, hacer la acción directamente sin confirmación
    if (newStatus === false && count === 0) {
      try {
        await updateBranchStatus()
      } catch (error: any) {
        toast.error(error.message || "Error al cambiar el estado de la sucursal")
      }
      return
    }
    
    // Si está desactivando y tiene usuarios, mostrar confirmación
    if (newStatus === false) {
      setConfirmTitle('Desactivar sucursal')
      setConfirmColor('orange')
      setConfirmDesc(`Se desactivará la sucursal "${branch.name}" y se desactivarán ${count} usuario(s) asociados.`)
      setPendingAction(() => updateBranchStatus)
      setConfirmOpen(true)
      return
    }
    
    // Si está activando, hacer la acción directamente
    try {
      await updateBranchStatus()
    } catch (error: any) {
      toast.error(error.message || "Error al cambiar el estado de la sucursal")
    }
  }
  
  const confirmPerform = async () => {
    if (!pendingAction) return
    try {
      await pendingAction()
    } catch (error: any) {
      toast.error(error.message || "Acción fallida")
    } finally {
      setConfirmOpen(false)
      setPendingAction(null)
    }
  }

  return {
    isFormDialogOpen,
    isDeleteDialogOpen,
    isDetailDialogOpen,
    selectedBranch,
    confirmOpen,
    confirmTitle,
    confirmDesc,
    confirmColor,
    confirmPerform,
    setConfirmOpen,
    openCreateDialog,
    openEditDialog,
    openDeleteDialog,
    openViewDetailsDialog,
    closeDialogs,
    handleSave,
    handleDelete,
    handleToggleStatus
  }
}

