import { SalesExpenseWithRelations } from "@/components/sales/expense/types"
import { useApiError, extractErrorFromResponse } from "@/hooks/common/use-api-error"

export function useExpenseActions(customerSlug: string, onExpensesChange?: () => Promise<void> | void) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const { handleError } = useApiError()
  const [isFormDialogOpen, setIsFormDialogOpen] = useState(false)
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const [selectedExpense, setSelectedExpense] = useState<SalesExpenseWithRelations | undefined>()

  const openCreateDialog = () => {
    setSelectedExpense(undefined)
    setIsFormDialogOpen(true)
  }

  const openEditDialog = (expense: SalesExpenseWithRelations) => {
    setSelectedExpense(expense)
    setIsFormDialogOpen(true)
  }

  const openDeleteDialog = (expense: SalesExpenseWithRelations) => {
    setSelectedExpense(expense)
    setIsDeleteDialogOpen(true)
  }

  const closeDialogs = () => {
    setIsFormDialogOpen(false)
    setIsDeleteDialogOpen(false)
    setSelectedExpense(undefined)
  }

  const handleSave = async (data: any) => {
    try {
      const url = selectedExpense
        ? `/api/${customerSlug}/gastos/${selectedExpense.id}`
        : `/api/${customerSlug}/gastos`

      const method = selectedExpense ? "PUT" : "POST"

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(data),
      })

      if (!response.ok) {
        let errorPayload: unknown = null
        try {
          const clone = response.clone()
          errorPayload = await clone.json()
        } catch {
          errorPayload = null
        }
        const errorMessage = await extractErrorFromResponse(response)
        console.error(
          `Error al guardar gasto - status: ${response.status}, statusText: ${response.statusText}, message: ${errorMessage}`,
          errorPayload
        )
        if (errorPayload && typeof errorPayload === "object" && "details" in errorPayload) {
          const details = (errorPayload as any).details
          if (Array.isArray(details)) {
            console.table(details)
          } else if (details && typeof details === "object") {
            console.log("Detalles de validación:", details)
          } else {
            console.log("Detalles de validación:", details)
          }
        }
        throw new Error(errorMessage)
      }

      const message = selectedExpense ? "Gasto actualizado" : "Gasto creado"
      toast.success(message)
      closeDialogs()

      if (onExpensesChange) {
        await Promise.resolve(onExpensesChange())
      }

      startTransition(() => {
        router.refresh()
      })
    } catch (error) {
      handleError(error, {
        showToast: true,
        toastTitle: selectedExpense ? "Error al actualizar gasto" : "Error al crear gasto",
      })
    }
  }

  const handleDelete = async () => {
    if (!selectedExpense) return

    try {
      const response = await fetch(`/api/${customerSlug}/gastos/${selectedExpense.id}`, {
        method: "DELETE",
      })

      if (!response.ok) {
        const errorMessage = await extractErrorFromResponse(response)
        throw new Error(errorMessage)
      }

      toast.success("Gasto eliminado")
      closeDialogs()

      if (onExpensesChange) {
        await Promise.resolve(onExpensesChange())
      }

      startTransition(() => {
        router.refresh()
      })
    } catch (error) {
      handleError(error, {
        showToast: true,
        toastTitle: "Error al eliminar gasto",
      })
    }
  }

  return {
    isFormDialogOpen,
    isDeleteDialogOpen,
    selectedExpense,
    openCreateDialog,
    openEditDialog,
    openDeleteDialog,
    closeDialogs,
    handleSave,
    handleDelete
  }
}

"use client"

import { SalesProduct, Category } from "@prisma/client"
import { useRouter } from "next/navigation"
import { useState, useTransition } from "react"
import { toast } from "sonner"

import { useApiError, extractErrorFromResponse } from "@/hooks/common/use-api-error"

export function useProductActions(customerSlug: string, onProductsChange?: () => void) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const { handleError } = useApiError()
  const [isFormDialogOpen, setIsFormDialogOpen] = useState(false)
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const [selectedProduct, setSelectedProduct] = useState<(SalesProduct & { category: Category | null }) | undefined>()

  const openCreateDialog = () => {
    setSelectedProduct(undefined)
    setIsFormDialogOpen(true)
  }

  const openEditDialog = async (product: SalesProduct & { category: Category | null }) => {
    try {
      // Obtener el producto completo desde el API para asegurar que tenemos todos los datos
      const response = await fetch(`/api/${customerSlug}/productos/${product.id}`)
      if (response.ok) {
        const fullProduct = await response.json()
        setSelectedProduct(fullProduct)
      } else {
        // Si falla, usar el producto de la tabla como fallback
        setSelectedProduct(product)
      }
    } catch (error) {
      console.error('Error al cargar producto completo:', error)
      // Si falla, usar el producto de la tabla como fallback
      setSelectedProduct(product)
    }
    setIsFormDialogOpen(true)
  }

  const openDeleteDialog = (product: SalesProduct & { category: Category | null }) => {
    setSelectedProduct(product)
    setIsDeleteDialogOpen(true)
  }

  const closeDialogs = () => {
    setIsFormDialogOpen(false)
    setIsDeleteDialogOpen(false)
    setSelectedProduct(undefined)
  }

  const handleSave = async (data: any) => {
    try {
      const url = selectedProduct
        ? `/api/${customerSlug}/productos/${selectedProduct.id}`
        : `/api/${customerSlug}/productos`

      const method = selectedProduct ? "PUT" : "POST"

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        const errorMessage = errorData.error || errorData.message || `Error ${response.status}: ${response.statusText}`
        
        // Si hay detalles de validación, mostrarlos
        if (errorData.details && Array.isArray(errorData.details)) {
          const validationErrors = errorData.details.map((err: any) => `${err.field}: ${err.message}`).join(', ')
          throw new Error(`${errorMessage}. ${validationErrors}`)
        }
        
        throw new Error(errorMessage)
      }

      const message = selectedProduct ? "Producto actualizado" : "Producto creado"
      toast.success(message)
      closeDialogs()
      
      // Recargar productos si hay callback
      if (onProductsChange) {
        onProductsChange()
      }
      
      startTransition(() => {
        router.refresh()
      })
    } catch (error) {
      handleError(error, {
        showToast: true,
        toastTitle: selectedProduct ? "Error al actualizar producto" : "Error al crear producto",
      })
    }
  }

  const handleDelete = async () => {
    if (!selectedProduct) return

    try {
      const response = await fetch(`/api/${customerSlug}/productos/${selectedProduct.id}`, {
        method: "DELETE",
      })

      if (!response.ok) {
        const errorMessage = await extractErrorFromResponse(response)
        throw new Error(errorMessage)
      }

      toast.success("Producto eliminado")
      closeDialogs()
      
      // Recargar productos si hay callback
      if (onProductsChange) {
        onProductsChange()
      }
      
      startTransition(() => {
        router.refresh()
      })
    } catch (error) {
      handleError(error, {
        showToast: true,
        toastTitle: "Error al eliminar producto",
      })
    }
  }

  const handleToggleStatus = async (product: SalesProduct & { category: Category | null }) => {
    try {
      const newStatus = !product.isActive
      const response = await fetch(`/api/${customerSlug}/productos/${product.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isActive: newStatus }),
      })

      if (!response.ok) {
        const errorMessage = await extractErrorFromResponse(response)
        throw new Error(errorMessage)
      }

      toast.success(newStatus ? "Producto activado" : "Producto desactivado")
      
      // Recargar productos si hay callback
      if (onProductsChange) {
        onProductsChange()
      }
      
      startTransition(() => {
        router.refresh()
      })
    } catch (error) {
      handleError(error, {
        showToast: true,
        toastTitle: "Error al cambiar estado del producto",
      })
    }
  }

  return {
    isFormDialogOpen,
    isDeleteDialogOpen,
    selectedProduct,
    openCreateDialog,
    openEditDialog,
    openDeleteDialog,
    closeDialogs,
    handleSave,
    handleDelete,
    handleToggleStatus
  }
}

"use client"

import { RoleSas } from "@prisma/client"
import { useRouter } from "next/navigation"
import { useState, useTransition } from "react"
import { toast } from "sonner"

type RoleWithRelations = RoleSas & {
  organization?: { razonSocial: string | null; name: string | null; slug: string | null } | null
  sucursal?: { name: string } | null
  _count?: { usuariosSas: number }
}

export function useRoleSasActions(
  customerSlug: string,
  setRoles?: (roles: RoleWithRelations[] | ((prev: RoleWithRelations[]) => RoleWithRelations[])) => void
) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [isFormDialogOpen, setIsFormDialogOpen] = useState(false)
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const [selectedRole, setSelectedRole] = useState<RoleWithRelations | undefined>()
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [confirmTitle, setConfirmTitle] = useState('')
  const [confirmDesc, setConfirmDesc] = useState<string>('')
  const [confirmColor, setConfirmColor] = useState<'red'|'orange'|'green'>('orange')
  const [pendingAction, setPendingAction] = useState<(() => Promise<void>) | null>(null)

  // Función para recargar roles desde la API
  const reloadRoles = async () => {
    try {
      const response = await fetch(`/api/${customerSlug}/roles`)
      if (response.ok) {
        const data = await response.json()
        const rolesData = data.roles || data
        if (setRoles) {
          setRoles(rolesData)
        }
      }
    } catch (error) {
      console.error("Error recargando roles:", error)
    }
  }

  const openCreateDialog = () => {
    setSelectedRole(undefined)
    setIsFormDialogOpen(true)
  }

  const openEditDialog = (role: RoleWithRelations) => {
    setSelectedRole(role)
    setIsFormDialogOpen(true)
  }

  const openDeleteDialog = (role: RoleWithRelations) => {
    setSelectedRole(role)
    setIsDeleteDialogOpen(true)
  }

  const closeDialogs = () => {
    setIsFormDialogOpen(false)
    setIsDeleteDialogOpen(false)
    setSelectedRole(undefined)
  }

  const handleSave = async (data: any) => {
    try {
      const url = selectedRole
        ? `/api/${customerSlug}/roles/${selectedRole.id}`
        : `/api/${customerSlug}/roles`

      const method = selectedRole ? "PUT" : "POST"

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.error || "Error al guardar el rol")
      }

      const savedRole = await response.json()
      const message = selectedRole ? "Rol actualizado" : "Rol creado"
      toast.success(message)
      closeDialogs()
      
      // Actualizar estado local en tiempo real
      if (setRoles) {
        if (selectedRole) {
          // Actualizar rol existente manteniendo su posición
          setRoles((prevRoles) =>
            prevRoles.map((role) =>
              role.id === selectedRole.id ? { ...role, ...savedRole } : role
            )
          )
        } else {
          // Agregar nuevo rol al principio (ordenado por createdAt desc)
          setRoles((prevRoles) => [savedRole, ...prevRoles])
        }
      } else {
        // Fallback a router.refresh si no hay setRoles
        startTransition(() => {
          router.refresh()
        })
      }
    } catch (error: any) {
      toast.error(error.message || "Error al guardar el rol")
    }
  }

  const handleDelete = async () => {
    if (!selectedRole) return
    if ((selectedRole.nombre || '').toLowerCase() === 'administrador') {
      toast.error('No se puede eliminar el rol Administrador')
      return
    }
    const count = selectedRole?._count?.usuariosSas || 0
    setConfirmTitle('Eliminar rol')
    setConfirmColor('red')
    setConfirmDesc(`Se eliminará el rol "${selectedRole.nombre}" y se desactivarán ${count} usuario(s) asignados.`)
    setPendingAction(() => async () => {
      const response = await fetch(`/api/${customerSlug}/roles/${selectedRole.id}`, { method: 'DELETE' })
      if (!response.ok) {
        const error = await response.json(); throw new Error(error.error || 'Error al eliminar el rol')
      }
      toast.success('Rol eliminado')
      closeDialogs()
      
      // Actualizar estado local en tiempo real
      if (setRoles) {
        setRoles((prevRoles) => prevRoles.filter((role) => role.id !== selectedRole.id))
      } else {
        startTransition(() => router.refresh())
      }
    })
    setConfirmOpen(true)
  }

  const handleToggleStatus = async (role: RoleWithRelations) => {
    const newStatus = !role.isActive
    const count = role?._count?.usuariosSas || 0
    
    // Función para actualizar el estado del rol
    const updateRoleStatus = async () => {
      const response = await fetch(`/api/${customerSlug}/roles/${role.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isActive: newStatus })
      })
      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.error || 'Error al cambiar el estado del rol')
      }
      const updatedRole = await response.json()
      
      // Actualizar estado local en tiempo real
      if (setRoles) {
        setRoles((prevRoles) =>
          prevRoles.map((r) =>
            r.id === role.id ? { ...r, isActive: newStatus, ...updatedRole } : r
          )
        )
      }
      
      toast.success(newStatus ? 'Rol activado' : 'Rol desactivado')
    }
    
    // Si no tiene usuarios asignados, hacer la acción directamente sin confirmación
    if (count === 0) {
      try {
        await updateRoleStatus()
      } catch (e: any) {
        toast.error(e?.message || 'Acción fallida')
      }
      return
    }
    
    // Si tiene usuarios, mostrar confirmación
    setConfirmTitle(newStatus ? 'Activar rol' : 'Desactivar rol')
    setConfirmColor(newStatus ? 'green' : 'orange')
    setConfirmDesc(`Se ${newStatus ? 'activará' : 'desactivará'} el rol "${role.nombre}" y afectará a ${count} usuario(s) asignados.`)
    setPendingAction(() => updateRoleStatus)
    setConfirmOpen(true)
  }

  const confirmPerform = async () => {
    if (!pendingAction) return
    try {
      await pendingAction()
    } catch (e: any) {
      toast.error(e?.message || 'Acción fallida')
    } finally {
      setConfirmOpen(false)
      setPendingAction(null)
    }
  }

  return {
    isFormDialogOpen,
    isDeleteDialogOpen,
    selectedRole,
    confirmOpen,
    confirmTitle,
    confirmDesc,
    confirmColor,
    confirmPerform,
    setConfirmOpen,
    openCreateDialog,
    openEditDialog,
    openDeleteDialog,
    closeDialogs,
    handleSave,
    handleDelete,
    handleToggleStatus
  }
}

"use client"

import { useRouter } from "next/navigation"
import { useState, useTransition } from "react"
import { toast } from "sonner"

import { SalesSaleWithRelations } from "@/components/sales/sale/types"
import { extractErrorFromResponse } from "@/hooks/common/use-api-error"

interface UseSaleActionsReturn {
  isFormDialogOpen: boolean
  isDeleteDialogOpen: boolean
  selectedSale?: SalesSaleWithRelations
  openCreateDialog: () => void
  openEditDialog: (sale: SalesSaleWithRelations) => void
  openDeleteDialog: (sale: SalesSaleWithRelations) => void
  closeDialogs: () => void
  handleSave: (data: any) => Promise<void>
  handleDelete: () => Promise<void>
}

export function useSaleActions(customerSlug: string, onSalesChange?: () => Promise<void> | void): UseSaleActionsReturn {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [isFormDialogOpen, setIsFormDialogOpen] = useState(false)
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const [selectedSale, setSelectedSale] = useState<SalesSaleWithRelations | undefined>()

  const openCreateDialog = () => {
    setSelectedSale(undefined)
    setIsFormDialogOpen(true)
  }

  const openEditDialog = (sale: SalesSaleWithRelations) => {
    setSelectedSale(sale)
    setIsFormDialogOpen(true)
  }

  const openDeleteDialog = (sale: SalesSaleWithRelations) => {
    setSelectedSale(sale)
    setIsDeleteDialogOpen(true)
  }

  const closeDialogs = () => {
    setIsFormDialogOpen(false)
    setIsDeleteDialogOpen(false)
    setSelectedSale(undefined)
  }

  const handleSave = async (data: any) => {
    try {
      const url = selectedSale
        ? `/api/${customerSlug}/ventas/${selectedSale.id}`
        : `/api/${customerSlug}/ventas`

      const method = selectedSale ? "PUT" : "POST"

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      })

      if (!response.ok) {
        const errorMessage = await extractErrorFromResponse(response)
        throw new Error(errorMessage)
      }

      toast.success(selectedSale ? "Venta actualizada" : "Venta registrada")
      closeDialogs()

      if (onSalesChange) {
        await Promise.resolve(onSalesChange())
      }

      startTransition(() => {
        router.refresh()
      })

      // Retornar la venta creada
      try {
        return await response.json()
      } catch (error) {
        // Si no hay JSON en la respuesta, retornar undefined
        return undefined
      }
    } catch (error: any) {
      toast.error(error.message || "Error al guardar la venta")
      throw error
    }
  }

  const handleDelete = async () => {
    if (!selectedSale) return

    try {
      const response = await fetch(`/api/${customerSlug}/ventas/${selectedSale.id}`, {
        method: "DELETE",
      })

      if (!response.ok) {
        const errorMessage = await extractErrorFromResponse(response)
        throw new Error(errorMessage)
      }

      toast.success("Venta eliminada")
      closeDialogs()

      if (onSalesChange) {
        await Promise.resolve(onSalesChange())
      }

      startTransition(() => {
        router.refresh()
      })
    } catch (error: any) {
      toast.error(error.message || "Error al eliminar la venta")
    }
  }

  return {
    isFormDialogOpen,
    isDeleteDialogOpen,
    selectedSale,
    openCreateDialog,
    openEditDialog,
    openDeleteDialog,
    closeDialogs,
    handleSave,
    handleDelete,
  }
}

"use client"

import { UsuarioSas } from "@prisma/client"
import { useRouter } from "next/navigation"
import { useState, useTransition } from "react"
import { toast } from "sonner"

type UsuarioWithRelations = UsuarioSas & {
  rol?: { id: string; nombre: string } | null
  sucursal?: { id: string; name: string } | null
  customer?: any
}

export function useUsuarioSasActions(
  customerSlug: string,
  setUsuarios?: (usuarios: UsuarioWithRelations[] | ((prev: UsuarioWithRelations[]) => UsuarioWithRelations[])) => void
) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [isFormDialogOpen, setIsFormDialogOpen] = useState(false)
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const [selectedUsuario, setSelectedUsuario] = useState<UsuarioWithRelations | undefined>()
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [confirmTitle, setConfirmTitle] = useState('')
  const [confirmDesc, setConfirmDesc] = useState('')
  const [confirmColor, setConfirmColor] = useState<'red'|'orange'|'green'>('orange')
  const [pendingAction, setPendingAction] = useState<(() => Promise<void>) | null>(null)

  const openCreateDialog = () => {
    setSelectedUsuario(undefined)
    setIsFormDialogOpen(true)
  }

  const openEditDialog = (usuario: UsuarioWithRelations) => {
    setSelectedUsuario(usuario)
    setIsFormDialogOpen(true)
  }

  const openDeleteDialog = (usuario: UsuarioWithRelations) => {
    setSelectedUsuario(usuario)
    setIsDeleteDialogOpen(true)
  }

  const closeDialogs = () => {
    setIsFormDialogOpen(false)
    setIsDeleteDialogOpen(false)
    setSelectedUsuario(undefined)
  }

  const handleSave = async (data: any) => {
    try {
      const url = selectedUsuario
        ? `/api/${customerSlug}/usuarios/${selectedUsuario.id}`
        : `/api/${customerSlug}/usuarios`

      const method = selectedUsuario ? "PUT" : "POST"

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.error || "Error al guardar el usuario")
      }

      const savedUsuario = await response.json()
      const message = selectedUsuario ? "Usuario actualizado" : "Usuario creado"
      toast.success(message)
      closeDialogs()
      
      // Actualizar estado local en tiempo real
      if (setUsuarios) {
        if (selectedUsuario) {
          // Actualizar usuario existente
          setUsuarios((prevUsuarios) =>
            prevUsuarios.map((usuario) =>
              usuario.id === selectedUsuario.id ? { ...usuario, ...savedUsuario } : usuario
            )
          )
        } else {
          // Agregar nuevo usuario
          setUsuarios((prevUsuarios) => [savedUsuario, ...prevUsuarios])
        }
      } else {
        // Fallback a router.refresh si no hay setUsuarios
        startTransition(() => {
          router.refresh()
        })
      }

      // Disparar evento personalizado para actualizar el header si es el usuario logueado
      if (savedUsuario) {
        const event = new CustomEvent('sas-user-updated', { detail: savedUsuario })
        window.dispatchEvent(event)
        // También usar localStorage para sincronizar entre pestañas
        try {
          localStorage.setItem('sas-user-updated', JSON.stringify({ userId: savedUsuario.id, timestamp: Date.now() }))
          localStorage.removeItem('sas-user-updated') // Remover inmediatamente para que el evento se dispare
        } catch {}
      }
    } catch (error: any) {
      toast.error(error.message || "Error al guardar el usuario")
    }
  }

  const handleDelete = async () => {
    if (!selectedUsuario) return
    setConfirmTitle('Eliminar usuario')
    setConfirmColor('red')
    setConfirmDesc(`Se eliminará al usuario "${selectedUsuario.nombre} ${selectedUsuario.apellido}" y se revocarán sus accesos.`)
    setPendingAction(() => async () => {
      const response = await fetch(`/api/${customerSlug}/usuarios/${selectedUsuario.id}`, { method: 'DELETE' })
      if (!response.ok) { const error = await response.json(); throw new Error(error.error || 'Error al eliminar el usuario') }
      toast.success('Usuario eliminado')
      closeDialogs()
      
      // Actualizar estado local en tiempo real
      if (setUsuarios) {
        setUsuarios((prevUsuarios) => prevUsuarios.filter((usuario) => usuario.id !== selectedUsuario.id))
      } else {
        startTransition(() => router.refresh())
      }
    })
    setConfirmOpen(true)
  }

  const handleToggleStatus = async (usuario: UsuarioWithRelations) => {
    const newStatus = !usuario.isActive
    
    // Función para actualizar el estado del usuario
    const updateUsuarioStatus = async () => {
      const response = await fetch(`/api/${customerSlug}/usuarios/${usuario.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isActive: newStatus })
      })
      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.error || 'Error al cambiar el estado del usuario')
      }
      const updatedUsuario = await response.json()
      
      // Actualizar estado local en tiempo real
      if (setUsuarios) {
        setUsuarios((prevUsuarios) =>
          prevUsuarios.map((u) =>
            u.id === usuario.id ? { ...u, isActive: newStatus, ...updatedUsuario } : u
          )
        )
      }
      
      toast.success(newStatus ? 'Usuario activado' : 'Usuario desactivado')
    }
    
    setConfirmTitle(newStatus ? 'Activar usuario' : 'Desactivar usuario')
    setConfirmColor(newStatus ? 'green' : 'orange')
    setConfirmDesc(`Se ${newStatus ? 'activará' : 'desactivará'} al usuario "${usuario.nombre} ${usuario.apellido}" (${usuario.ci || 'sin CI'}).`)
    setPendingAction(() => updateUsuarioStatus)
    setConfirmOpen(true)
  }

  const confirmPerform = async () => {
    if (!pendingAction) return
    try {
      await pendingAction()
    } catch (e: any) {
      toast.error(e?.message || 'Acción fallida')
    } finally {
      setConfirmOpen(false)
      setPendingAction(null)
    }
  }

  return {
    isFormDialogOpen,
    isDeleteDialogOpen,
    selectedUsuario,
    confirmOpen,
    confirmTitle,
    confirmDesc,
    confirmColor,
    confirmPerform,
    setConfirmOpen,
    openCreateDialog,
    openEditDialog,
    openDeleteDialog,
    closeDialogs,
    handleSave,
    handleDelete,
    handleToggleStatus
  }
}

'use client'

// Inspired by react-hot-toast library
import * as React from 'react'

import type { ToastActionElement, ToastProps } from '@/components/ui/toast'

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: 'ADD_TOAST',
  UPDATE_TOAST: 'UPDATE_TOAST',
  DISMISS_TOAST: 'DISMISS_TOAST',
  REMOVE_TOAST: 'REMOVE_TOAST',
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType['ADD_TOAST']
      toast: ToasterToast
    }
  | {
      type: ActionType['UPDATE_TOAST']
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType['DISMISS_TOAST']
      toastId?: ToasterToast['id']
    }
  | {
      type: ActionType['REMOVE_TOAST']
      toastId?: ToasterToast['id']
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: 'REMOVE_TOAST',
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case 'ADD_TOAST':
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case 'UPDATE_TOAST':
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t,
        ),
      }

    case 'DISMISS_TOAST': {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t,
        ),
      }
    }
    case 'REMOVE_TOAST':
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, 'id'>

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: 'UPDATE_TOAST',
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: 'DISMISS_TOAST', toastId: id })

  dispatch({
    type: 'ADD_TOAST',
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: 'DISMISS_TOAST', toastId }),
  }
}

export { useToast, toast }

import jwt from 'jsonwebtoken'

import type { NextRequest } from 'next/server'

import { AdminJWTService } from '@/lib/auth/admin-jwt'
import { PasswordService } from '@/lib/auth/password'
import { prisma } from '@/lib/prisma'



const ADMIN_JWT_SECRET = process.env.ADMIN_JWT_SECRET || 'dev-admin-secret'
const ADMIN_JWT_EXPIRES_IN = process.env.ADMIN_JWT_EXPIRES_IN || '7d'

export class AdminAuthService {
  static async login({ 
    email, 
    password,
    request 
  }: { 
    email: string
    password: string
    request?: NextRequest
  }) {
    const user = await prisma.profile.findUnique({
      where: { email }
    })

    if (!user || !user.password) {
      return { success: false, error: 'Credenciales inválidas' }
    }
    if (!user.isActive) {
      return { success: false, error: 'Cuenta desactivada' }
    }

    const ok = await PasswordService.verifyPassword(password, user.password)
    if (!ok) {
      return { success: false, error: 'Credenciales inválidas' }
    }

    // Verificar si tiene 2FA habilitado
    const profile = await prisma.profile.findUnique({
      where: { id: user.id },
      select: {
        twoFactorEnabled: true,
      },
    })

    // Si tiene 2FA habilitado, retornar token temporal en lugar de token final
    if (profile?.twoFactorEnabled) {
      // Generar token temporal (válido por 5 minutos) para verificación 2FA
      const tempToken = jwt.sign(
        {
          userId: user.id,
          email: user.email,
          isSuperAdmin: user.isSuperAdmin,
          temp: true,
        },
        ADMIN_JWT_SECRET,
        { expiresIn: '5m' } // 5 minutos para verificar 2FA
      )

      const { password: _p, ...userSafe } = user as any
      return {
        success: true,
        user: userSafe,
        requires2FA: true,
        tempToken, // Token temporal para verificar 2FA
      }
    }

    // No tiene 2FA: proceder con login normal
    await prisma.profile.update({ where: { id: user.id }, data: { lastLoginAt: new Date() } })

    // Crear sesión en BD
    const { SessionManagement } = await import('@/lib/auth/session-management')
    
    // Obtener info del request
    const ipAddress = request?.headers.get('x-forwarded-for')?.split(',')[0] || request?.headers.get('x-real-ip') || undefined
    const userAgent = request?.headers.get('user-agent') || undefined
    const deviceInfo = request ? SessionManagement.getDeviceInfo(request) : undefined
    
    const sessionToken = await SessionManagement.createSession({
      userId: user.id,
      systemType: 'admin',
      ipAddress,
      userAgent,
      deviceInfo,
    }, {
      forceSingleSession: false, // Permitir múltiples sesiones
      trackDevice: true,
    })

    // Generar token JWT con sessionId
    const token = await AdminJWTService.generateToken({ 
      userId: user.id, 
      email: user.email, 
      isSuperAdmin: user.isSuperAdmin,
      sessionId: sessionToken
    })
    
    const { password: _p, ...userSafe } = user as any
    return { success: true, user: userSafe, token }
  }
}

import { prisma } from '../prisma'
import { logger } from '../utils/logger'

import { JWTService, type JWTPayload } from './jwt'
import { PasswordService } from './password'

export interface LoginCredentials {
  email: string
  password: string
}

export interface RegisterData {
  email: string
  password: string
  fullName?: string
}

export interface AuthResult {
  success: boolean
  user?: any
  token?: string
  error?: string
}

export class AuthService {
  // Login de usuario
  static async login(credentials: LoginCredentials): Promise<AuthResult> {
    try {
      const { email, password } = credentials

      // Buscar usuario en la tabla Profile (sistema de administración)
      // NOTA: Los usuarios del sistema de administración NO tienen organizaciones
      const user = await prisma.profile.findUnique({
        where: { email }
      })

      if (!user) {
        return {
          success: false,
          error: 'Credenciales inválidas'
        }
      }

      if (!user.isActive) {
        return {
          success: false,
          error: 'Cuenta desactivada'
        }
      }

      if (!user.password) {
        return {
          success: false,
          error: 'Contraseña no configurada'
        }
      }

      // Verificar contraseña
      const isValidPassword = await PasswordService.verifyPassword(password, user.password)
      if (!isValidPassword) {
        return {
          success: false,
          error: 'Credenciales inválidas'
        }
      }

      // Actualizar último login
      await prisma.profile.update({
        where: { id: user.id },
        data: { lastLoginAt: new Date() }
      })

      // Generar token JWT
      const payload: JWTPayload = {
        userId: user.id,
        email: user.email,
        isSuperAdmin: user.isSuperAdmin
      }

      const token = JWTService.generateToken(payload)

      // Preparar datos del usuario
      const userData = {
        id: user.id,
        email: user.email,
        fullName: user.fullName,
        role: user.role,
        isSuperAdmin: user.isSuperAdmin
      }

      return {
        success: true,
        user: userData,
        token
      }

    } catch (error) {
      logger.error('Error en login', error as Error)
      return {
        success: false,
        error: 'Error interno del servidor'
      }
    }
  }

  // Registro de usuario
  static async register(data: RegisterData): Promise<AuthResult> {
    try {
      const { email, password, fullName } = data

      // Verificar si el email ya existe
      const existingUser = await prisma.profile.findUnique({
        where: { email }
      })

      if (existingUser) {
        return {
          success: false,
          error: 'El email ya está registrado'
        }
      }

      // Validar fortaleza de contraseña
      const passwordValidation = PasswordService.validatePasswordStrength(password)
      if (!passwordValidation.isValid) {
        return {
          success: false,
          error: passwordValidation.errors.join(', ')
        }
      }

      // Hash de la contraseña
      const hashedPassword = await PasswordService.hashPassword(password)

      // Crear usuario
      const user = await prisma.profile.create({
        data: {
          email,
          password: hashedPassword,
          fullName,
          role: 'user',
          isActive: true
        }
      })

      // Generar token JWT
      const payload: JWTPayload = {
        userId: user.id,
        email: user.email,
        isSuperAdmin: user.isSuperAdmin
      }

      const token = JWTService.generateToken(payload)

      // Preparar datos del usuario
      const userData = {
        id: user.id,
        email: user.email,
        fullName: user.fullName,
        role: user.role,
        isSuperAdmin: user.isSuperAdmin
      }

      return {
        success: true,
        user: userData,
        token
      }

    } catch (error) {
      logger.error('Error en registro', error as Error)
      return {
        success: false,
        error: 'Error interno del servidor'
      }
    }
  }

  // Verificar token y obtener usuario
  static async verifyToken(token: string) {
    try {
      const user = await JWTService.getAuthenticatedUser(token)
      return user
    } catch (error) {
      return null
    }
  }

  // Logout (solo invalidar token del lado del cliente)
  static async logout(): Promise<{ success: boolean }> {
    // En una implementación completa, aquí podrías:
    // 1. Agregar el token a una lista negra
    // 2. Actualizar el lastLogoutAt del usuario
    // 3. Limpiar sesiones activas
    
    return { success: true }
  }

  // Cambiar contraseña
  static async changePassword(userId: string, currentPassword: string, newPassword: string): Promise<AuthResult> {
    try {
      const user = await prisma.profile.findUnique({
        where: { id: userId }
      })

      if (!user || !user.password) {
        return {
          success: false,
          error: 'Usuario no encontrado'
        }
      }

      // Verificar contraseña actual
      const isValidCurrentPassword = await PasswordService.verifyPassword(currentPassword, user.password)
      if (!isValidCurrentPassword) {
        return {
          success: false,
          error: 'Contraseña actual incorrecta'
        }
      }

      // Validar nueva contraseña
      const passwordValidation = PasswordService.validatePasswordStrength(newPassword)
      if (!passwordValidation.isValid) {
        return {
          success: false,
          error: passwordValidation.errors.join(', ')
        }
      }

      // Hash de la nueva contraseña
      const hashedNewPassword = await PasswordService.hashPassword(newPassword)

      // Actualizar contraseña
      await prisma.profile.update({
        where: { id: userId },
        data: { 
          password: hashedNewPassword,
          updatedAt: new Date()
        }
      })

      return {
        success: true
      }

    } catch (error) {
      logger.error('Error cambiando contraseña', error as Error)
      return {
        success: false,
        error: 'Error interno del servidor'
      }
    }
  }

  // Resetear contraseña (para super admin)
  static async resetPassword(userId: string, newPassword: string): Promise<AuthResult> {
    try {
      // Validar nueva contraseña
      const passwordValidation = PasswordService.validatePasswordStrength(newPassword)
      if (!passwordValidation.isValid) {
        return {
          success: false,
          error: passwordValidation.errors.join(', ')
        }
      }

      // Hash de la nueva contraseña
      const hashedPassword = await PasswordService.hashPassword(newPassword)

      // Actualizar contraseña
      await prisma.profile.update({
        where: { id: userId },
        data: { 
          password: hashedPassword,
          updatedAt: new Date()
        }
      })

      return {
        success: true
      }

    } catch (error) {
      logger.error('Error reseteando contraseña', error as Error)
      return {
        success: false,
        error: 'Error interno del servidor'
      }
    }
  }

  // Generar contraseña temporal
  static async generateTemporaryPassword(userId: string): Promise<AuthResult> {
    try {
      const tempPassword = PasswordService.generateRandomPassword(12)
      const hashedPassword = await PasswordService.hashPassword(tempPassword)

      await prisma.profile.update({
        where: { id: userId },
        data: { 
          password: hashedPassword,
          updatedAt: new Date()
        }
      })

      return {
        success: true,
        user: { tempPassword }
      }

    } catch (error) {
      logger.error('Error generando contraseña temporal', error as Error)
      return {
        success: false,
        error: 'Error interno del servidor'
      }
    }
  }
}

import jwt, { SignOptions } from 'jsonwebtoken'

import { AuthService } from '../services/auth-service'

const JWT_SECRET = process.env.JWT_SECRET || 'your-super-secret-jwt-key-here'
const JWT_EXPIRES_IN = process.env.JWT_EXPIRES_IN || '7d'

export interface JWTPayload {
  userId: string
  email?: string
  isSuperAdmin?: boolean
  organizationId?: string
}

export class JWTService {
  // Generar token JWT
  static generateToken(payload: JWTPayload): string {
    return jwt.sign(payload, JWT_SECRET, {
      expiresIn: JWT_EXPIRES_IN
    } as SignOptions)
  }

  // Verificar token JWT
  static verifyToken(token: string): JWTPayload | null {
    try {
      return jwt.verify(token, JWT_SECRET) as JWTPayload
    } catch (error) {
      return null
    }
  }

  // Obtener token desde las cookies
  static getTokenFromCookies(cookies: string): string | null {
    const cookieArray = cookies.split(';')
    const authCookie = cookieArray.find(cookie => 
      cookie.trim().startsWith('auth-token=')
    )
    
    if (!authCookie) return null
    
    return authCookie.split('=')[1]
  }

  // Crear cookie de autenticación
  static createAuthCookie(token: string): string {
    const isProduction = process.env.NODE_ENV === 'production'
    
    return `auth-token=${token}; Path=/; HttpOnly; SameSite=Strict${
      isProduction ? '; Secure' : ''
    }`
  }

  // Crear cookie de logout
  static createLogoutCookie(): string {
    return 'auth-token=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0'
  }

  // Obtener usuario desde el token
  static async getUserFromToken(token: string) {
    const payload = this.verifyToken(token)
    if (!payload) return null

    const user = await AuthService.getProfileById(payload.userId)
    return user
  }

  // Verificar si el usuario está autenticado
  static async isAuthenticated(token: string): Promise<boolean> {
    const user = await this.getUserFromToken(token)
    return user !== null
  }

  // Verificar si el usuario es super admin
  static async isSuperAdmin(token: string): Promise<boolean> {
    const user = await this.getUserFromToken(token)
    return user?.isSuperAdmin || false
  }

  // Obtener información del usuario autenticado
  static async getAuthenticatedUser(token: string) {
    const payload = this.verifyToken(token)
    if (!payload) return null

    const user = await AuthService.getProfileById(payload.userId)
    if (!user) return null

    return {
      id: user.id,
      fullName: user.fullName,
      role: user.role,
      isSuperAdmin: user.isSuperAdmin
    }
  }
}

/**
 * Servicio de Autenticación de Dos Factores (2FA)
 * 
 * Implementa TOTP (Time-based One-Time Password) usando otplib
 * Compatible con Google Authenticator, Authy, Microsoft Authenticator, etc.
 */

import crypto from 'crypto'

import { authenticator } from 'otplib'
import QRCode from 'qrcode'

import { PasswordService } from './password'

// Configurar otplib
authenticator.options = {
  step: 30, // Códigos válidos por 30 segundos
  window: 1, // Permitir 1 paso de tolerancia (±30 segundos)
}

export interface TwoFactorSetup {
  secret: string
  qrCode: string // Data URL de la imagen QR
  backupCodes: string[] // Códigos de respaldo (mostrar solo una vez)
}

export interface TwoFactorVerificationResult {
  valid: boolean
  isBackupCode?: boolean
}

export class TwoFactorService {
  /**
   * Genera un secret único para el usuario
   */
  static generateSecret(): string {
    return authenticator.generateSecret()
  }

  /**
   * Genera un código TOTP para un secret dado (útil para testing)
   */
  static generateToken(secret: string): string {
    return authenticator.generate(secret)
  }

  /**
   * Valida un código TOTP contra un secret
   */
  static verifyToken(secret: string, token: string): boolean {
    try {
      return authenticator.verify({ token, secret })
    } catch {
      return false
    }
  }

  /**
   * Genera QR Code para configuración inicial
   */
  static async generateQRCode(
    secret: string,
    email: string,
    serviceName: string = 'Ventas SAS'
  ): Promise<string> {
    // Crear URI para authenticator apps
    const otpauth = authenticator.keyuri(email, serviceName, secret)

    // Generar QR Code como Data URL
    try {
      const qrCodeDataURL = await QRCode.toDataURL(otpauth, {
        errorCorrectionLevel: 'M',
        type: 'image/png',
        width: 300,
        margin: 2,
      })
      return qrCodeDataURL
    } catch (error) {
      throw new Error('Error generando QR Code')
    }
  }

  /**
   * Genera códigos de respaldo (backup codes)
   * Cada código debe ser único y aleatorio
   */
  static generateBackupCodes(count: number = 10): string[] {
    const codes: string[] = []
    for (let i = 0; i < count; i++) {
      // Generar código de 8 dígitos
      const code = crypto.randomInt(10000000, 99999999).toString()
      codes.push(code)
    }
    return codes
  }

  /**
   * Hashea un backup code para almacenamiento seguro
   */
  static async hashBackupCode(code: string): Promise<string> {
    // Usar bcrypt para hashear backup codes
    return await PasswordService.hashPassword(code)
  }

  /**
   * Verifica un backup code contra la lista hasheada
   */
  static async verifyBackupCode(
    code: string,
    hashedCodes: string[]
  ): Promise<boolean> {
    for (const hashedCode of hashedCodes) {
      const isValid = await PasswordService.verifyPassword(code, hashedCode)
      if (isValid) {
        return true
      }
    }
    return false
  }

  /**
   * Hashea todos los backup codes para almacenamiento
   */
  static async hashBackupCodes(codes: string[]): Promise<string[]> {
    return Promise.all(codes.map(code => this.hashBackupCode(code)))
  }

  /**
   * Prepara setup completo de 2FA para un usuario
   */
  static async setupTwoFactor(
    email: string,
    serviceName: string = 'Ventas SAS'
  ): Promise<TwoFactorSetup> {
    // Generar secret
    const secret = this.generateSecret()

    // Generar QR Code
    const qrCode = await this.generateQRCode(secret, email, serviceName)

    // Generar backup codes
    const backupCodes = this.generateBackupCodes(10)

    return {
      secret,
      qrCode,
      backupCodes,
    }
  }

  /**
   * Valida un código 2FA (puede ser TOTP o backup code)
   */
  static async verifyTwoFactor(
    secret: string | null,
    token: string,
    backupCodes?: string[] | null
  ): Promise<TwoFactorVerificationResult> {
    // Si no hay secret, 2FA no está habilitado
    if (!secret) {
      return { valid: false }
    }

    // Intentar verificar como TOTP primero
    if (this.verifyToken(secret, token)) {
      return { valid: true, isBackupCode: false }
    }

    // Si falla TOTP, verificar como backup code
    if (backupCodes && Array.isArray(backupCodes) && backupCodes.length > 0) {
      const isValidBackup = await this.verifyBackupCode(token, backupCodes)
      if (isValidBackup) {
        return { valid: true, isBackupCode: true }
      }
    }

    return { valid: false }
  }

  /**
   * Encripta un secret para almacenamiento seguro
   * En producción, usar una clave de encriptación desde variables de entorno
   */
  static encryptSecret(secret: string): string {
    const algorithm = 'aes-256-cbc'
    const key = Buffer.from(
      process.env.ENCRYPTION_KEY || 
      'your-32-char-encryption-key-here-change-in-production',
      'utf8'
    ).slice(0, 32)
    
    const iv = crypto.randomBytes(16)
    const cipher = crypto.createCipheriv(algorithm, key, iv)
    
    let encrypted = cipher.update(secret, 'utf8', 'hex')
    encrypted += cipher.final('hex')
    
    // Retornar IV + encrypted data (base64)
    return Buffer.from(iv.toString('hex') + ':' + encrypted, 'utf8').toString('base64')
  }

  /**
   * Desencripta un secret almacenado
   */
  static decryptSecret(encryptedSecret: string): string {
    try {
      const algorithm = 'aes-256-cbc'
      const key = Buffer.from(
        process.env.ENCRYPTION_KEY || 
        'your-32-char-encryption-key-here-change-in-production',
        'utf8'
      ).slice(0, 32)
      
      const data = Buffer.from(encryptedSecret, 'base64').toString('utf8')
      const [ivHex, encrypted] = data.split(':')
      
      if (!ivHex || !encrypted) {
        throw new Error('Formato de secret encriptado inválido')
      }
      
      const iv = Buffer.from(ivHex, 'hex')
      const decipher = crypto.createDecipheriv(algorithm, key, iv)
      
      let decrypted = decipher.update(encrypted, 'hex', 'utf8')
      decrypted += decipher.final('utf8')
      
      return decrypted
    } catch (error) {
      throw new Error('Error desencriptando secret')
    }
  }

  /**
   * Formatea el secret en grupos de 4 caracteres para mejor legibilidad
   */
  static formatSecret(secret: string): string {
    return secret.match(/.{1,4}/g)?.join(' ') || secret
  }
}

import { prisma } from './prisma'
import { logger } from './utils/logger'

// Funciones de utilidad para la base de datos
export class DatabaseService {
  // Obtener cliente de Prisma
  static getClient() {
    return prisma
  }

  // Conectar a la base de datos
  static async connect() {
    try {
      await prisma.$connect()
      logger.info('Conectado a la base de datos PostgreSQL', {
        type: 'database',
        operation: 'connect',
      })
    } catch (error) {
      logger.error('Error conectando a la base de datos', error as Error, {
        type: 'database',
        operation: 'connect',
      })
      throw error
    }
  }

  // Desconectar de la base de datos
  static async disconnect() {
    try {
      await prisma.$disconnect()
      logger.info('Desconectado de la base de datos', {
        type: 'database',
        operation: 'disconnect',
      })
    } catch (error) {
      logger.error('Error desconectando de la base de datos', error as Error, {
        type: 'database',
        operation: 'disconnect',
      })
      throw error
    }
  }

  // Verificar estado de la conexión
  static async healthCheck() {
    try {
      await prisma.$queryRaw`SELECT 1`
      return { status: 'healthy', message: 'Base de datos conectada' }
    } catch (error) {
      return { status: 'unhealthy', message: 'Error de conexión a la base de datos' }
    }
  }

  // Obtener estadísticas de la base de datos
  static async getStats() {
    try {
      const [customers, products, orders, organizations] = await Promise.all([
        prisma.customer.count(),
        prisma.product.count(),
        prisma.order.count(),
        prisma.organization.count()
      ])

      return {
        customers,
        products,
        orders,
        organizations
      }
    } catch (error) {
      logger.error('Error obteniendo estadísticas de base de datos', error as Error, {
        type: 'database',
        operation: 'getStats',
      })
      return null
    }
  }
}

export { prisma }
export default DatabaseService

import type { NextRequest } from 'next/server'

import { PasswordService } from '@/lib/auth/password'
import { SasJWTService } from '@/lib/auth/sas-jwt'
import { prisma } from '@/lib/prisma'
import { logger } from '@/lib/utils/logger'
import { getCustomerBySlug, getOrganizationBySlug } from '@/lib/utils/organization'


export interface LoginSasCredentials {
  ci?: string
  email?: string
  password: string
}

export interface AuthSasResult {
  success: boolean
  user?: any
  token?: string
  error?: string
  requires2FA?: boolean
  tempToken?: string
}

export class AuthSasService {
  // Login de usuario del sistema SAS
  static async login(
    customerSlug: string, 
    credentials: LoginSasCredentials,
    request?: NextRequest
  ): Promise<AuthSasResult> {
    try {
      const { ci, email, password } = credentials

      if (!password) {
        return {
          success: false,
          error: 'La contraseña es requerida'
        }
      }

      if (!ci && !email) {
        return {
          success: false,
          error: 'CI o correo electrónico es requerido'
        }
      }

      // Obtener la organización por slug (valida suscripción activa)
      let organization
      try {
        organization = await getOrganizationBySlug(customerSlug)
        if (!organization) {
          logger.debug('Organización no encontrada o sin suscripción activa', { customerSlug })
          return {
            success: false,
            error: 'Organización no encontrada, inactiva o sin suscripción activa'
          }
        }
      } catch (orgError) {
        logger.error('Error al obtener organización por slug', orgError as Error, { customerSlug })
        return {
          success: false,
          error: 'Error al validar organización'
        }
      }

      // Buscar usuario en la tabla usuarios_sas por organizationId
      const where: any = {
        organizationId: organization.id
      }

      if (ci) {
        where.ci = ci
      } else if (email) {
        where.email = email
      }

      let usuario
      try {
        usuario = await prisma.usuarioSas.findFirst({
          where,
          select: {
            id: true,
            ci: true,
            nombre: true,
            apellido: true,
            email: true,
            address: true,
            phone: true,
            foto: true,
            password: true,
            isActive: true,
            organizationId: true,
            twoFactorEnabled: true,
            twoFactorSecret: true,
            rolId: true,
            sucursalId: true,
            rol: {
              select: {
                id: true,
                nombre: true,
                descripcion: true
              }
            },
            sucursal: {
              select: {
                id: true,
                name: true
              }
            },
            organization: {
              select: {
                id: true,
                razonSocial: true,
                slug: true
              }
            }
          }
        })
      } catch (dbError) {
        logger.error('Error al buscar usuario SAS', dbError as Error, {
          organizationId: organization.id,
          hasCi: !!ci,
          hasEmail: !!email,
        })
        throw new Error('Error al buscar usuario en la base de datos')
      }

      if (!usuario) {
        return {
          success: false,
          error: 'Credenciales inválidas'
        }
      }

      if (!usuario.isActive) {
        return {
          success: false,
          error: 'Cuenta desactivada'
        }
      }

      // Validar que el usuario tenga organización asociada
      if (!usuario.organization || !usuario.organization.id) {
        logger.error('Usuario sin organización asociada', {
          userId: usuario.id,
          organizationId: usuario.organizationId,
        })
        return {
          success: false,
          error: 'Usuario sin organización asociada'
        }
      }

      if (!usuario.password) {
        logger.debug('Usuario sin contraseña configurada', {
          userId: usuario.id,
          organizationId: usuario.organizationId,
        })
        return {
          success: false,
          error: 'Contraseña no configurada'
        }
      }

      // Verificar contraseña
      let isValidPassword = false
      try {
        isValidPassword = await PasswordService.verifyPassword(password, usuario.password)
      } catch (passwordError) {
        logger.error('Error al verificar contraseña', passwordError as Error, {
          userId: usuario.id,
          organizationId: usuario.organizationId,
        })
        return {
          success: false,
          error: 'Error al verificar credenciales'
        }
      }

      if (!isValidPassword) {
        logger.debug('Contraseña inválida', {
          userId: usuario.id,
          organizationId: usuario.organizationId,
          hasCi: !!ci,
          hasCorreo: !!email,
        })
        return {
          success: false,
          error: 'Credenciales inválidas'
        }
      }

      // Verificar si tiene 2FA habilitado
      if (usuario.twoFactorEnabled && usuario.twoFactorSecret) {
        // Generar token temporal (válido por 5 minutos) para verificación 2FA
        const { default: jwt } = await import('jsonwebtoken')
        const SAS_JWT_SECRET = process.env.SAS_JWT_SECRET || 'dev-sas-secret'
        
        const tempToken = jwt.sign(
          {
            userId: usuario.id,
            organizationId: usuario.organization.id,
            temp: true,
          },
          SAS_JWT_SECRET,
          { expiresIn: '5m' } // 5 minutos para verificar 2FA
        )

        // Preparar datos del usuario (sin información sensible)
        const userData = {
          id: usuario.id,
          nombre: usuario.nombre,
          apellido: usuario.apellido,
          email: usuario.email,
          organization: usuario.organization,
        }

        return {
          success: true,
          user: userData,
          requires2FA: true,
          tempToken, // Token temporal para verificar 2FA
        }
      }

      // No tiene 2FA: proceder con login normal
      // Crear sesión en BD
      let sessionToken: string | null = null
      try {
        const { SessionManagement } = await import('@/lib/auth/session-management')
        
        // Obtener info del request
        const forwardedFor = request?.headers.get('x-forwarded-for')
        const ipAddress = forwardedFor?.split(',')[0]?.trim() || request?.headers.get('x-real-ip') || undefined
        const userAgent = request?.headers.get('user-agent') || undefined
        const deviceInfo = request ? SessionManagement.getDeviceInfo(request) : undefined
        
        sessionToken = await SessionManagement.createSession({
          userId: usuario.id,
          organizationId: usuario.organization.id,
          systemType: 'sas',
          ipAddress,
          userAgent,
          deviceInfo,
        }, {
          forceSingleSession: false, // Permitir múltiples sesiones
          trackDevice: true,
        })
      } catch (sessionError) {
        logger.error('Error al crear sesión SAS', sessionError as Error, {
          userId: usuario.id,
          organizationId: usuario.organization.id,
        })
        // Continuar sin sesión si falla (no crítico para el login)
        console.warn('No se pudo crear sesión, continuando sin ella:', sessionError)
      }

      // Generar token JWT (SAS) con sessionId
      let token: string
      try {
        token = await SasJWTService.generateToken({ 
          userId: usuario.id, 
          email: usuario.email || undefined,
          organizationId: usuario.organization.id,
          sessionId: sessionToken || undefined
        })
      } catch (tokenError) {
        logger.error('Error al generar token JWT SAS', tokenError as Error, {
          userId: usuario.id,
          organizationId: usuario.organization.id,
        })
        throw new Error('Error al generar token de autenticación')
      }

      // Preparar datos del usuario (sin contraseña)
      const userData = {
        id: usuario.id,
        ci: usuario.ci,
        nombre: usuario.nombre,
        apellido: usuario.apellido,
        email: usuario.email,
        address: usuario.address,
        phone: usuario.phone,
        foto: usuario.foto,
        rol: usuario.rol,
        sucursal: usuario.sucursal,
        organization: usuario.organization,
        isActive: usuario.isActive
      }

      return {
        success: true,
        user: userData,
        token
      }

    } catch (error) {
      logger.error('Error en login SAS', error as Error, {
        customerSlug,
        hasCi: !!credentials.ci,
        hasCorreo: !!credentials.email,
      })
      console.error('Error completo en AuthSasService.login:', error)
      console.error('Stack trace:', error instanceof Error ? error.stack : 'No stack available')
      
      // Retornar mensaje de error más específico en desarrollo
      const errorMessage = process.env.NODE_ENV === 'development' && error instanceof Error
        ? error.message
        : 'Error interno del servidor'
      
      return {
        success: false,
        error: errorMessage
      }
    }
  }

  // Verificar token y obtener usuario
  static async verifyToken(customerSlug: string, token: string) {
    try {
      // verifyToken es asíncrono, debemos esperarlo
      const decoded = await SasJWTService.verifyToken(token)
      if (!decoded) {
        logger.debug('Token SAS no decodificado', { customerSlug })
        return null
      }

      // Verificar que el usuario pertenece al cliente
      const customer = await getCustomerBySlug(customerSlug)
      if (!customer) {
        logger.debug('Cliente no encontrado al verificar token', { customerSlug })
        return null
      }

      const usuario = await prisma.usuarioSas.findUnique({
        where: { id: decoded.userId },
        include: {
          rol: true,
          sucursal: true,
          organization: true
        }
      })

      if (!usuario) {
        logger.debug('Usuario no encontrado al verificar token', { userId: decoded.userId, customerSlug })
        return null
      }

      // Obtener la organización por slug para validar
      const organization = await getOrganizationBySlug(customerSlug)
      if (!organization || usuario.organizationId !== organization.id) {
        logger.debug('Usuario no pertenece a la organización', { 
          userId: decoded.userId, 
          usuarioOrganizationId: usuario.organizationId,
          organizationId: organization?.id,
          customerSlug 
        })
        return null
      }

      if (!usuario.isActive) {
        logger.debug('Usuario inactivo', { userId: decoded.userId, customerSlug })
        return null
      }

      // No retornar la contraseña
      const { password: usuarioPassword, ...usuarioSinPassword } = usuario
      return usuarioSinPassword

    } catch (error) {
      logger.error('Error verificando token SAS', error as Error, {
        customerSlug,
        errorMessage: error instanceof Error ? error.message : String(error),
      })
      return null
    }
  }
}

import { Category } from '@prisma/client'

import { getCachedData, invalidateCachePattern, CacheKeys } from '@/lib/cache/cache-service'
import { prisma } from '@/lib/prisma'

export interface CreateCategoryData {
  name: string
  description?: string
}

export interface UpdateCategoryData {
  name?: string
  description?: string
  isActive?: boolean
}

export class CategoryService {
  // Obtener todas las categorías de una organización
  static async getAllCategories(
    organizationId: string,
    skip: number = 0,
    take: number = 10,
    search?: string,
    status?: string
  ) {
    const where: any = {
      organizationId,
      deletedAt: null // Excluir soft deleted por defecto
    }

    if (search) {
      where.OR = [
        { name: { contains: search, mode: 'insensitive' } },
        { description: { contains: search, mode: 'insensitive' } },
      ]
    }

    if (status === 'active') {
      where.isActive = true
    } else if (status === 'inactive') {
      where.isActive = false
    }

    const [categories, total] = await Promise.all([
      prisma.category.findMany({
        where,
        skip,
        take,
        include: {
          _count: {
            select: {
              products: true
            }
          }
        },
        orderBy: { createdAt: 'desc' }
      }),
      prisma.category.count({ where })
    ])

    return { categories, total }
  }

  // Obtener categoría por ID
  static async getCategoryById(id: string): Promise<Category | null> {
    return prisma.category.findUnique({
      where: { id },
      include: {
        _count: {
          select: {
            products: true
          }
        }
      }
    })
  }

  // Crear nueva categoría
  static async createCategory(
    organizationId: string,
    data: CreateCategoryData
  ): Promise<Category & { _count?: { products: number } }> {
    const category = await prisma.category.create({
      data: {
        organizationId,
        name: data.name,
        description: data.description,
        isActive: true
      },
      include: {
        _count: {
          select: {
            products: true
          }
        }
      }
    })

    // Invalidar caché de categorías de esta organización
    invalidateCachePattern(`category:${organizationId}*`)

    return category
  }

  // Actualizar categoría
  static async updateCategory(
    id: string,
    data: UpdateCategoryData
  ): Promise<Category & { _count?: { products: number } }> {
    // Obtener categoría para saber el organizationId
    const category = await this.getCategoryById(id)
    
    const updated = await prisma.category.update({
      where: { id },
      data,
      include: {
        _count: {
          select: {
            products: true
          }
        }
      }
    })

    // Invalidar caché de categorías si existe
    if (category) {
      invalidateCachePattern(`category:${category.organizationId}*`)
    }

    return updated
  }

  // Eliminar categoría (soft delete)
  static async deleteCategory(id: string): Promise<void> {
    // Obtener categoría para saber el organizationId antes de eliminar
    const category = await this.getCategoryById(id)
    
    // Soft delete en lugar de eliminación física
    await prisma.category.update({
      where: { id },
      data: {
        deletedAt: new Date()
      }
    })

    // Invalidar caché de categorías si existe
    if (category) {
      invalidateCachePattern(`category:${category.organizationId}*`)
    }
  }

  // Restaurar categoría (deshacer soft delete)
  static async restoreCategory(id: string): Promise<Category> {
    const category = await this.getCategoryById(id)
    
    const restored = await prisma.category.update({
      where: { id },
      data: {
        deletedAt: null
      },
      include: {
        _count: {
          select: {
            products: true
          }
        }
      }
    })

    // Invalidar caché
    if (category) {
      invalidateCachePattern(`category:${category.organizationId}*`)
    }

    return restored
  }

  // Obtener categorías activas (para selects) - CON CACHÉ
  // Siempre retorna todas las categorías activas de la organización
  // El filtrado por sucursal se aplica solo a los productos, no a las categorías
  static async getActiveCategories(organizationId: string, branchId?: string) {
    const cacheKey = CacheKeys.category(organizationId, 'active')
    
    return getCachedData(
      cacheKey,
      () => prisma.category.findMany({
        where: {
          organizationId,
          isActive: true,
          deletedAt: null // Excluir soft deleted
        },
        orderBy: { name: 'asc' }
      }),
      600 // Cache por 10 minutos (categorías no cambian frecuentemente)
    )
  }
}

import { existsSync } from 'fs'
import { unlink } from 'fs/promises'
import { join } from 'path'

import { SalesProduct } from '@prisma/client'

import { getCachedData, invalidateCachePattern, CacheKeys } from '@/lib/cache/cache-service'
import { prisma } from '@/lib/prisma'
import { NotificationService } from '@/lib/services/notification-service'
import { logDatabase } from '@/lib/utils/logger'
import { CommonIncludes } from '@/lib/utils/query-optimizer'

export interface CreateSalesProductData {
  branchId?: string
  categoryId?: string
  name: string
  description?: string
  brand?: string
  model?: string
  price: number
  cost: number
  stock?: number
  minStock?: number
  sku?: string
  barcode?: string
  imageUrl?: string
}

export interface UpdateSalesProductData {
  branchId?: string
  categoryId?: string
  name?: string
  description?: string
  brand?: string
  model?: string
  price?: number
  cost?: number
  stock?: number
  minStock?: number
  sku?: string
  barcode?: string
  imageUrl?: string
  isActive?: boolean
}

export class SalesProductService {
  // Obtener todos los productos de una organización (opcionalmente filtrados por sucursal)
  static async getAllProducts(
    organizationId: string,
    skip: number = 0,
    take: number = 10,
    search?: string,
    status?: string,
    categoryId?: string,
    branchId?: string,
    includeDeleted: boolean = false
  ) {
    const where: any = {
      organizationId,
      ...(includeDeleted ? {} : { deletedAt: null }) // Excluir soft deleted por defecto
    }

    // Filtrar por sucursal si se proporciona
    if (branchId) {
      where.branchId = branchId
    }

    if (search) {
      where.OR = [
        { name: { contains: search, mode: 'insensitive' } },
        { description: { contains: search, mode: 'insensitive' } },
        { sku: { contains: search, mode: 'insensitive' } },
        { barcode: { contains: search, mode: 'insensitive' } },
      ]
    }

    if (status === 'active') {
      where.isActive = true
    } else if (status === 'inactive') {
      where.isActive = false
    }

    if (categoryId) {
      where.categoryId = categoryId
    }

    const startTime = Date.now()
    const [products, total] = await Promise.all([
      prisma.salesProduct.findMany({
        where,
        skip,
        take,
        include: {
          ...CommonIncludes.product,
          branch: {
            select: {
              id: true,
              name: true,
            },
          },
        },
        orderBy: { createdAt: 'desc' }
      }),
      prisma.salesProduct.count({ where })
    ])
    
    const duration = Date.now() - startTime
    logDatabase('FIND_MANY', 'sales_products', duration, undefined, {
      organizationId,
      count: products.length,
    })

    return { products, total }
  }

  // Obtener producto por ID
  static async getProductById(id: string, includeDeleted: boolean = false): Promise<(SalesProduct & {
    category: { id: string; name: string } | null;
    branch: { id: string; name: string } | null;
  }) | null> {
    const product = await prisma.salesProduct.findUnique({
      where: { id },
      include: {
        category: true,
        branch: {
          select: {
            id: true,
            name: true,
          },
        },
      }
    })

    // Si no se incluyen eliminados y el producto está eliminado, retornar null
    if (!includeDeleted && product && 'deletedAt' in product && product.deletedAt) {
      return null
    }

    return product
  }

  // Crear nuevo producto
  static async createProduct(
    organizationId: string,
    data: CreateSalesProductData
  ): Promise<SalesProduct> {
    const startTime = Date.now()
    const product = await prisma.salesProduct.create({
      data: {
        organizationId,
        branchId: data.branchId,
        categoryId: data.categoryId,
        name: data.name,
        description: data.description,
        brand: data.brand,
        model: data.model,
        price: data.price,
        cost: data.cost,
        stock: data.stock || 0,
        minStock: data.minStock || 0,
        sku: data.sku,
        barcode: data.barcode,
        imageUrl: data.imageUrl,
        isActive: true
      }
    })

    // Invalidar caché de productos de esta organización
    invalidateCachePattern(`product:${organizationId}*`)

    return product
  }

  // Actualizar producto
  static async updateProduct(
    id: string,
    data: UpdateSalesProductData
  ): Promise<SalesProduct> {
    // Obtener organizationId antes de actualizar
    const product = await prisma.salesProduct.findUnique({
      where: { id },
      select: { organizationId: true }
    })
    
    const updated = await prisma.salesProduct.update({
      where: { id },
      data: {
        ...data,
        brand: data.brand !== undefined ? data.brand : undefined,
        model: data.model !== undefined ? data.model : undefined,
      },
      include: {
        organization: {
          select: {
            id: true,
          },
        },
      },
    })

    // Invalidar caché de productos si existe
    if (product) {
      invalidateCachePattern(`product:${product.organizationId}*`)
    }

    // Notificar si el stock está bajo
    if (data.stock !== undefined && updated.minStock !== null) {
      const finalStock = data.stock
      const minStock = updated.minStock || 0
      
      if (finalStock <= minStock && updated.organizationId) {
        NotificationService.notifyStockLow(
          updated.organizationId,
          updated.id,
          updated.name,
          finalStock,
          minStock,
          updated.organizationId || undefined
        ).catch((error) => {
          logDatabase('NOTIFICATION_ERROR', 'notifications', undefined, error as Error, {
            productId: updated.id,
          })
        })
      }
    }

    return updated
  }

  // Eliminar producto (soft delete)
  static async deleteProduct(id: string, slug?: string): Promise<void> {
    // Obtener producto para saber el organizationId y imageUrl ANTES de eliminar
    const product = await prisma.salesProduct.findUnique({
      where: { id },
      select: { 
        organizationId: true,
        imageUrl: true
      }
    })
    
    // Eliminar imagen asociada si existe y es una ruta local
    if (product?.imageUrl && slug) {
      try {
        // Verificar si es una ruta local (no URL externa)
        if (product.imageUrl.startsWith('/uploads/products/')) {
          // Extraer el nombre del archivo de la ruta
          const imagePath = join(process.cwd(), 'public', product.imageUrl)
          
          // Verificar que el archivo existe antes de intentar eliminarlo
          if (existsSync(imagePath)) {
            await unlink(imagePath)
            logDatabase('FILE_DELETE', 'product_image', 0, undefined, {
              productId: id,
              imagePath: product.imageUrl,
            })
          }
        }
      } catch (error) {
        // Log el error pero no fallar la eliminación del producto
        logDatabase('FILE_DELETE_ERROR', 'product_image', 0, error as Error, {
          productId: id,
          imagePath: product.imageUrl,
        })
      }
    }
    
    // Soft delete en lugar de eliminación física
    const startTime = Date.now()
    await prisma.salesProduct.update({
      where: { id },
      data: {
        deletedAt: new Date()
      } as any // deletedAt está en el schema pero TypeScript puede no reconocerlo inmediatamente
    })
    
    const duration = Date.now() - startTime
    logDatabase('SOFT_DELETE', 'sales_products', duration, undefined, {
      productId: id,
      organizationId: product?.organizationId,
    })

    // Invalidar caché de productos si existe
    if (product) {
      invalidateCachePattern(`product:${product.organizationId}*`)
    }
  }

  // Restaurar producto (deshacer soft delete)
  static async restoreProduct(id: string): Promise<SalesProduct> {
    const restored = await prisma.salesProduct.update({
      where: { id },
      data: {
        deletedAt: null
      } as any, // deletedAt está en el schema pero TypeScript puede no reconocerlo inmediatamente
      include: {
        category: true
      }
    })

    // Invalidar caché
    if (restored.organizationId) {
      invalidateCachePattern(`product:${restored.organizationId}*`)
    }

    return restored
  }

  // Actualizar stock
  static async updateStock(id: string, quantity: number): Promise<SalesProduct> {
    const product = await prisma.salesProduct.findUnique({
      where: { id }
    })

    if (!product) {
      throw new Error('Producto no encontrado')
    }

    const updated = await prisma.salesProduct.update({
      where: { id },
      data: {
        stock: product.stock + quantity
      }
    })

    // Invalidar caché de productos (el stock cambió)
    invalidateCachePattern(`product:${product.organizationId}*`)

    return updated
  }

  // Obtener productos activos (para selects) - CON CACHÉ
  // Opcionalmente filtrados por sucursal
  static async getActiveProducts(organizationId: string, branchId?: string) {
    const cacheKey = CacheKeys.product(organizationId, branchId ? `active-${branchId}` : 'active')
    
    return getCachedData(
      cacheKey,
      () => prisma.salesProduct.findMany({
        where: {
          organizationId,
          ...(branchId ? { branchId } : {}),
          isActive: true,
          deletedAt: null // Excluir soft deleted
        } as any, // deletedAt está en el schema pero TypeScript puede no reconocerlo inmediatamente
        include: {
          category: true
        },
        orderBy: { name: 'asc' }
      }),
      300 // Cache por 5 minutos (productos pueden cambiar más frecuentemente)
    )
  }
}

